# =========================================================================== #
# 用户反馈（2026-10-09 §3，docs/admin-viewer-round4-20261009.md）。
#
#   - POST /api/feedback，登录用户 + CSRF（全局闸：/api/* 只认 X-CSRF-Token
#     头）。body ``{"description": str(10..4000 字), "client": object}``；
#   - 202 ``{"feedback_id", "mailed"}``；401 未登录（demo/匿名无 session，
#     在 before_request 认证闸照常 401）；400 描述长度不符或 client 非对象；
#     413 序列化后超 256 KB；429 频率超限（每小时 5 次/每天 20 次，带
#     retry_after）；
#   - 记录先落库（user_feedback），邮件复用注册邮件队列（purpose=
#     'user_feedback'，收件人=现有管理员通知邮箱配置）；未配置管理员邮箱
#     时仍保存记录、mailed=false。owner 预览态由全局 _preview_write_guard
#     统一拒绝写（403 preview_readonly），不在此重复判定。
# =========================================================================== #
@app.route("/api/feedback", methods=["POST"])
def api_feedback_submit():
    """提交用户反馈（问题描述 + 客户端环形缓冲记录）。"""
    if not AUTH_ENABLED:
        return jsonify(error="提交反馈需要启用认证"), 400
    user_id = session.get("user_id") or None
    if not user_id:
        return jsonify(error="登录状态已失效，请重新登录后再试",
                       code="auth_required"), 401
    body = request.get_json(silent=True)
    if not isinstance(body, dict):
        return jsonify(error="请求体需为 JSON 对象", code="invalid_request"), 400
    client = body.get("client")
    if not isinstance(client, dict):
        return jsonify(error="client 需为 JSON 对象", code="invalid_request"), 400
    serialized = json.dumps(client, ensure_ascii=False, separators=(",", ":"))
    if len(serialized.encode("utf-8")) > feedback_store.CLIENT_MAX_BYTES:
        return jsonify(error="客户端记录超过 256 KB 上限",
                       code="payload_too_large"), 413
    try:
        description = feedback_store.validate_description(
            body.get("description"))
    except feedback_store.FeedbackError as exc:
        return jsonify(error=str(exc), code=exc.code), 400
    user = user_store.get_user(user_id)
    if user is None or user.get("disabled"):
        return jsonify(error="登录状态已失效，请重新登录后再试",
                       code="auth_required"), 401
    server = feedback_store.build_server_context(user)
    try:
        result = feedback_store.submit(
            user, description, client, server,
            recipient=feedback_store.admin_recipient())
    except feedback_store.FeedbackRateLimitedError as exc:
        resp = jsonify(error="反馈提交过于频繁，请稍后再试",
                       code="rate_limited", retry_after=exc.retry_after)
        resp.status_code = 429
        resp.headers["Retry-After"] = str(exc.retry_after)
        return resp
    except Exception:
        app.logger.exception("用户反馈提交失败")
        return jsonify(error="反馈暂不可用，请稍后重试",
                       code="storage_unavailable"), 503
    # best-effort 即时排水（失败留 queued，worker 循环是权威发送方）
    registration_mail_worker.drain_async()
    return jsonify(feedback_id=result["feedback_id"],
                   mailed=result["mailed"]), 202


# =========================================================================== #
# P2 可撤回研究授权与账户设置（docs/agent-plan-20260921-registration-consent-
# research.md §3.5/§6）。
#
#   - GET  /api/account/agreements          当前发布文档 + 本人接受情况 +
#                                           本人研究状态（no-store）；
#   - POST /api/account/agreements/accept   接受当前必选文档（CSRF/本人/
#                                           版本校验，source=account_reaccept）；
#   - PUT  /api/account/research-consent    {enabled, document_version,
#                                           expected_epoch}——CAS 撤回/再同意，
#                                           grant 版本必填，withdraw 不校验文稿；
#   - POST /api/account/research-data/deletion  幂等创建本人研究副本删除任务；
#       GET 同路径返回当前任务状态（可查询）。
#
# 身份规则（§6.1「当前真实用户本人」）：一律取 **actor_identity()**（真实登录
# 本人）而非 current_identity()（预览态 = 被预览用户）——owner 预览不能替用户
# 查看或变更授权；预览态显式 403 preview_forbidden。demo/公开分享访客没有
# 登录 session，到不了这里（全局 _require_auth 401）。写方法照走全局 CSRF 闸。
# 客户端提交的 user_id/角色/时间一律不作权威；expected_epoch 只用于 CAS。
# =========================================================================== #
def _p2_rfc3339(value):
    """timestamptz → RFC3339（UTC，Z 后缀；None 透传）——同 _test_app_rfc3339。"""
    if value is None:
        return None
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _account_settings_actor():
    """账户设置面（协议/研究授权/删除）身份解析：真实登录本人；预览态拒绝。

    返回 ``(user_id, None)`` 或 ``(None, error_response)``。AUTH 关闭时与
    test-application 同口径 400（这些端点语义上需要登录本人）。
    """
    if not AUTH_ENABLED:
        return None, (jsonify(error="账户设置需要启用认证"), 400)
    if _preview_active():
        return None, (jsonify(
            error="管理员预览态不能查看或变更用户的协议与研究授权",
            code="preview_forbidden"), 403)
    user_id = session.get("user_id") or None
    if not user_id:
        return None, (jsonify(error="登录状态已失效，请重新登录后再试",
                              code="auth_required"), 401)
    return user_id, None


def _consent_doc_wire(doc_type, doc, builtin):
    """协议文档出线（published 行或内置 draft 回退；url 为版本化链接）。"""
    slug = builtin.get(doc_type, {}).get("slug")
    return {
        "document_type": doc_type,
        "title": (doc or builtin.get(doc_type) or {}).get("title"),
        "version": (doc or builtin.get(doc_type) or {}).get("version"),
        "locale": (doc or builtin.get(doc_type) or {}).get("locale"),
        "content_sha256": (doc or builtin.get(doc_type) or {}).get(
            "content_sha256"),
        "status": (doc["status"] if doc else "draft"),
        "published_at": _p2_rfc3339(doc["published_at"]) if doc else None,
        "effective_at": _p2_rfc3339(doc["effective_at"]) if doc else None,
        "url": "/legal/%s/%s" % (slug, (doc or builtin.get(doc_type) or {})
                                 .get("version")) if slug else None,
    }


@app.route("/api/account/agreements", methods=["GET"])
def api_account_agreements():
    """当前发布文档、本人接受情况与本人研究状态（§3.5；no-store）。

    - documents：三类文稿的**当前 published** 版本；缺 published 时回退内置
      draft 信息（status=draft——draft 不可用于接受/授权，仅供阅读）；
    - acceptances：本人 user_agreement_acceptances（新→旧，上限 20）；
    - research：research_authorization_view（唯一权威 + 旧 test_application
      选项的 historical_only 标记）；
    - history：本人授权历史（上限 20）；deletion_jobs：研究副本删除任务
      （上限 10，含未终态任务状态）；
    - collection_enabled：研究采集功能开关（P2 默认关闭）。
    """
    user_id, err = _account_settings_actor()
    if err:
        return err
    try:
        builtin = {d["document_type"]: d
                   for d in agreement_store.builtin_documents()}
        documents = [
            _consent_doc_wire(dt, agreement_store.current_published(dt),
                              builtin)
            for dt in agreement_store.DOCUMENT_TYPES]
        acceptances = [{
            "document_type": r["document_type"],
            "version": r["version"],
            "content_sha256": r["content_sha256"],
            "accepted_at": _p2_rfc3339(r["accepted_at"]),
            "source": r["source"],
            "locale": r["locale"],
        } for r in research_consent_store.list_acceptances(user_id)[:20]]
        history = [{
            "from_state": r["from_state"], "to_state": r["to_state"],
            "epoch": r["epoch"],
            "document_version": r["document_version"],
            "created_at": _p2_rfc3339(r["created_at"]),
        } for r in research_consent_store.list_history(user_id)[:20]]
        jobs = [{
            "job_id": r["job_id"], "reason": r["reason"],
            "status": r["status"], "consent_epoch": r["consent_epoch"],
            "online_cleared": r["online_cleared"],
            "exports_cleared": r["exports_cleared"],
            "backups_pending": r["backups_pending"],
            "error_code": r["error_code"],
            "attempts": r.get("attempts", 0),
            "next_retry_at": _p2_rfc3339(r.get("next_retry_at")),
            "created_at": _p2_rfc3339(r["created_at"]),
            "updated_at": _p2_rfc3339(r["updated_at"]),
            "completed_at": _p2_rfc3339(r["completed_at"]),
        } for r in research_consent_store.list_deletion_jobs(user_id)[:10]]
        research = research_consent_store.research_authorization_view(user_id)
        if research.get("active_deletion_job") is not None:
            research["active_deletion_job"] = dict(
                research["active_deletion_job"])
            for key in ("created_at", "updated_at", "completed_at",
                        "next_retry_at"):
                research["active_deletion_job"][key] = _p2_rfc3339(
                    research["active_deletion_job"].get(key))
        for key in ("granted_at", "withdrawn_at"):
            research[key] = _p2_rfc3339(research.get(key))
    except Exception:
        app.logger.exception("账户协议/研究状态读取失败")
        return jsonify(error="暂无法读取账户协议状态，请稍后重试",
                       code="storage_unavailable"), 503
    resp = jsonify(documents=documents, acceptances=acceptances,
                   research=research, history=history, deletion_jobs=jobs,
                   collection_enabled=research_consent_store
                   .collection_enabled())
    resp.headers["Cache-Control"] = "no-store"
    return resp


def _consent_error_response(exc):
    """consent/agreement 服务异常 → 统一 HTTP 映射（4xx 业务码 + 503 存储）。"""
    if isinstance(exc, research_consent_store.EpochConflictError):
        return jsonify(error=str(exc), code="epoch_conflict"), 409
    if isinstance(exc, agreement_store.DocumentNotPublishedError):
        return jsonify(error=str(exc), code="document_not_published"), 409
    if isinstance(exc, research_consent_store.DocumentVersionRequiredError):
        return jsonify(error=str(exc),
                       code="document_version_required"), 400
    if isinstance(exc, research_consent_store.ActorForbiddenError):
        return jsonify(error=str(exc), code="actor_forbidden"), 403
    if isinstance(exc, (research_consent_store.ConsentError,
                       agreement_store.AgreementStoreError)):
        return jsonify(error=str(exc), code="invalid_request"), 400
    app.logger.exception("consent 服务异常")
    return jsonify(error="操作暂不可用，请稍后重试",
                   code="storage_unavailable"), 503


@app.route("/api/account/agreements/accept", methods=["POST"])
def api_account_agreements_accept():
    """接受当前必选《用户协议与数据处理说明》（§3.5）。

    body: ``{version, content_sha256?, document_type?}``（document_type 仅
    接受 user_agreement；version 必填）。CSRF/本人身份由全局闸与本路由的
    actor 解析保证；版本与 hash 以**服务端注册表**为权威——引用版本不是
    当前 published，或提供的 hash 不匹配，一律 409 document_not_published
    （不接受旧版本、不接受客户端自造 hash）。成功追加
    source=account_reaccept 凭据（不覆盖 register 期凭据）。
    """
    user_id, err = _account_settings_actor()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    doc_type = body.get("document_type") or \
        research_consent_store.TERMS_DOCUMENT_TYPE
    if doc_type != research_consent_store.TERMS_DOCUMENT_TYPE:
        return jsonify(error="本端点仅接受必选《用户协议与数据处理说明》",
                       code="unsupported_document_type"), 400
    version = body.get("version")
    if not isinstance(version, str) or not version.strip():
        return jsonify(error="必须提供协议版本", code="invalid_request"), 400
    version = version.strip()
    # hash 可省略（以服务端 published 为权威）；提供了就必须匹配
    sha256 = (body.get("content_sha256") or "").strip().lower() or None
    if sha256 is None:
        published = agreement_store.current_published(doc_type)
        sha256 = published["content_sha256"] if published else "0" * 64
    try:
        record = research_consent_store.record_terms_acceptance(
            user_id, doc_type, version, sha256,
            source="account_reaccept")
    except Exception as exc:  # noqa: BLE001 - 统一映射（含存储故障 503）
        return _consent_error_response(exc)
    return jsonify(ok=True, acceptance={
        "acceptance_id": record["acceptance_id"],
        "document_type": record["document_type"],
        "version": record["version"],
        "content_sha256": record["content_sha256"],
        "accepted_at": _p2_rfc3339(record["accepted_at"]),
        "source": record["source"],
        "locale": record["locale"],
    })


@app.route("/api/account/research-consent", methods=["PUT"])
def api_account_research_consent():
    """同意/撤回研究数据共享（§3.5；CAS + epoch）。

    body: ``{enabled: boolean, document_version?, expected_epoch?,
    document_sha256?}``：

    - ``enabled`` 必须是明确布尔值（字符串 "false" 等 truthiness 陷阱一律
      400，§3.1）；identity 取自 session，body 里的 user_id/角色/时间不作
      权威（用户 A 不能替 B 操作）；
    - grant（enabled=true）：``document_version`` 必填且必须等于当前
      published research_sharing 版本（缺版本 400，版本/hash 不匹配或无
      published 409）；hash 以服务端注册表为权威，客户端提供则须匹配；
    - withdraw（enabled=false）：不校验文稿（旧协议下架后仍可撤回）；
    - ``expected_epoch`` 提供多标签页 CAS：与当前 epoch 不一致 → 409
      epoch_conflict + current_epoch（调用方刷新后重试）；
    - 撤回成功时**同事务**创建研究副本删除任务（§6.3 撤回原子），响应附
      deletion_job 供前端提示清理进度；
    - Idempotency-Key 头透传为请求幂等键（网络重放不重复写历史）。
    """
    user_id, err = _account_settings_actor()
    if err:
        return err
    body = request.get_json(silent=True) or {}
    enabled = body.get("enabled")
    if not isinstance(enabled, bool):
        return jsonify(error="enabled 必须为布尔值", code="invalid_request"), 400
    expected_epoch = body.get("expected_epoch")
    if expected_epoch is not None and (
            isinstance(expected_epoch, bool)
            or not isinstance(expected_epoch, int)
            or expected_epoch < 0):
        return jsonify(error="expected_epoch 必须是非负整数",
                       code="invalid_request"), 400
    idem = (request.headers.get("Idempotency-Key") or "").strip() or None
    try:
        if enabled:
            version = body.get("document_version")
            if not isinstance(version, str) or not version.strip():
                return jsonify(
                    error="同意研究共享必须提供协议版本（document_version）",
                    code="document_version_required"), 400
            version = version.strip()
            published = agreement_store.current_published(
                research_consent_store.RESEARCH_DOCUMENT_TYPE)
            if published is None:
                raise agreement_store.DocumentNotPublishedError(
                    "当前没有已发布的数据共享协议文稿，暂不能同意研究共享")
            client_sha = (body.get("document_sha256") or "").strip().lower()
            if client_sha and client_sha != published["content_sha256"]:
                raise agreement_store.DocumentNotPublishedError(
                    "数据共享协议 %s 的内容摘要不匹配" % version)
            result = research_consent_store.grant(
                user_id, document_version=version,
                document_sha256=published["content_sha256"],
                expected_epoch=expected_epoch, actor_user_id=user_id,
                idempotency_key=idem)
        else:
            result = research_consent_store.withdraw(
                user_id, expected_epoch=expected_epoch,
                actor_user_id=user_id, idempotency_key=idem)
    except research_consent_store.EpochConflictError as exc:
        current = research_consent_store.get_consent(user_id)
        return jsonify(error=str(exc), code="epoch_conflict",
                       current_epoch=current["epoch"] if current else 0), 409
    except Exception as exc:  # noqa: BLE001 - 统一映射（含存储故障 503）
        return _consent_error_response(exc)

    def _wire(consent):
        if not consent:
            return None
        out = dict(consent)
        for key in ("granted_at", "withdrawn_at", "updated_at"):
            out[key] = _p2_rfc3339(out.get(key))
        return out

    job = result.get("deletion_job")
    if job is not None:
        job = dict(job)
        for key in ("created_at", "updated_at", "completed_at",
                    "next_retry_at"):
            job[key] = _p2_rfc3339(job.get(key))
    return jsonify(ok=True, consent=_wire(result.get("consent")),
                   changed=result.get("changed", False),
                   replayed=result.get("replayed", False),
                   deletion_job=job)


@app.route("/api/account/research-data/deletion", methods=["POST", "GET"])
def api_account_research_data_deletion():
    """研究副本删除任务：POST 幂等创建，GET 查询状态（§3.5）。

    - POST：为**本人**创建 reason=user_request 删除任务；已有未了结
      （pending/running 或 failed——含达上限、待人工处置的终态 failed）
      任务时原样返回（created=false，幂等——网络重试不重复建任务）。该
      任务只清理研究副本层（在线副本/导出/隔离备份），**不删除业务切片、
      标注或临床/科研工作记录**；不需要撤回授权也可申请（删除已采集研究
      副本与当前授权状态是两件事）。任务由 research_deletion_worker 异步
      执行（pending→running→completed/failed，失败有界退避重试；终态
      failed 停止自动重试但研究侧持续阻断，待人工处置）。
    - GET：返回当前未了结任务（含待人工处置的终态 failed——向用户/管理
      呈现「删除任务待人工处理」的真实状态）；没有则返回最近一条终态
      记录（都无则 null）。
    """
    user_id, err = _account_settings_actor()
    if err:
        return err
    if request.method == "POST":
        try:
            created = research_consent_store.create_deletion_job(
                user_id, reason="user_request", actor_user_id=user_id)
        except Exception as exc:  # noqa: BLE001 - 统一映射
            return _consent_error_response(exc)
        job = created["job"]
    else:
        job = research_consent_store.get_active_deletion_job(user_id)
        if job is None:
            history = research_consent_store.list_deletion_jobs(user_id)
            job = history[0] if history else None
        created = {"created": False}
    if job is not None:
        job = dict(job)
        for key in ("created_at", "updated_at", "completed_at",
                    "next_retry_at"):
            job[key] = _p2_rfc3339(job.get(key))
    resp = jsonify(ok=True, job=job, created=created.get("created", False))
    resp.headers["Cache-Control"] = "no-store"
    return resp


# =========================================================================== #
# P3 人工读片行为采集（docs/agent-plan-20260921-registration-consent-research.md
# §6.2/§7.1/§7.2/§7.3）。
#
#   - POST /api/research/viewing-sessions   登录+CSRF，提交业务 slide ID 供
#                                           ACL 验证；服务端创建研究 session
#                                           并绑定 user/epoch；无授权不创建；
#   - POST /api/research/viewer-events      {viewing_session_id, consent_epoch,
#                                           events:[...]}——后端从 session 解析
#                                           主体与切片，不信任客户端 user/
#                                           owner/资源映射。
#
# 身份与边界（§6.1）：一律取真实登录本人（session.user_id；匿名 401 由全局
# _require_auth、预览态写 403 由全局 _preview_write_guard 先行拦截）。demo/
# 公开分享访客无登录 session，到不了这里。客户端提交的 user_id/角色/owner
# 一律不作权威。事件白名单校验在 research_store（额外字段整批拒绝）；
# 观测事件可丢（429），绝不阻塞标注或主业务。研究存储故障不影响读片与
# 业务保存（本组端点独立于标注/AI 链路）。
# =========================================================================== #
def _research_ingest_actor():
    """研究采集端点身份解析：真实登录本人。

    与 _account_settings_actor 同口径：AUTH 关闭 → 400（研究采集语义上需要
    登录本人）；预览态由全局 _preview_write_guard 统一 403（POST 非安全方法）。
    """
    if not AUTH_ENABLED:
        return None, (jsonify(error="研究采集需要启用认证",
                              code="auth_required"), 400)
    user_id = session.get("user_id") or None
    if not user_id:
        return None, (jsonify(error="登录状态已失效，请重新登录后再试",
                              code="auth_required"), 401)
    return user_id, None


def _research_store_error_response(exc):
    """research_store 异常 → 统一 HTTP 映射（§7.3：403/409/429/413/503）。"""
    if isinstance(exc, research_store.RateLimitedError):
        resp = jsonify(error=str(exc), code="rate_limited")
        resp.headers["Retry-After"] = str(exc.retry_after)
        return resp, 429
    if isinstance(exc, research_store.NotAuthorizedError):
        # 未授权（开关关闭/未同意/撤回/文档过期/删除任务未清）——reason 机器码
        # 只进 code 字段，不向最终用户展开内部判定细节
        return jsonify(error=str(exc), code=exc.reason), 403
    if isinstance(exc, research_store.EpochMismatchError):
        return jsonify(error=str(exc), code="epoch_mismatch"), 409
    if isinstance(exc, (research_store.EventIdConflictError,
                        research_store.SeqConflictError)):
        return jsonify(error=str(exc), code=exc.code), 409
    if isinstance(exc, research_store.SessionNotFoundError):
        return jsonify(error="研究会话不存在或已失效",
                       code="session_not_found"), 404
    if isinstance(exc, research_store.SessionClosedError):
        return jsonify(error=str(exc), code="session_closed"), 409
    if isinstance(exc, research_store.PayloadTooLargeError):
        return jsonify(error=str(exc), code="payload_too_large"), 413
    if isinstance(exc, research_store.ResearchStoreError):
        return jsonify(error=str(exc), code=exc.code), 400
    app.logger.exception("研究采集存储异常")
    return jsonify(error="研究上报暂不可用（不影响读片）",
                   code="storage_unavailable"), 503


@app.route("/api/research/viewing-sessions", methods=["POST"])
def api_research_viewing_sessions():
    """创建研究读片会话（§7.3）。

    body: ``{slide}``（业务切片名，供 ACL 验证；project 可选、本版忽略）。
    第一版资源权利（§6.1）：只允许**本人拥有**的切片建立研究会话——
    「可查看他人切片」不足以授权研究；无 owner 的切片同样拒绝。响应不含
    账号、邮箱或真实文件路径；slide 只以研究伪名落库。
    """
    user_id, err = _research_ingest_actor()
    if err:
        return err
    body = request.get_json(silent=True)
    if not isinstance(body, dict):
        return jsonify(error="请求体必须是 JSON 对象",
                       code="invalid_request"), 400
    unknown = sorted(set(body.keys()) - {"slide", "project", "slide_id"})
    if unknown:
        return jsonify(error="请求体含未知字段 %s" % unknown,
                       code="invalid_request"), 400
    slide = body.get("slide")
    slide_id_in = body.get("slide_id")
    # slide ID 化（P2 前端缺口③）：双字段——slide_id 优先（权威），slide
    # 为 legacy alias；两者同给且解析到不同资产 → 400（合同 §2.1）。
    if slide_id_in is not None and (not isinstance(slide_id_in, str)
                                    or not slide_id_in.strip()):
        return jsonify(error="slide_id 非法", code="invalid_request"), 400
    if slide is not None and (not isinstance(slide, str)
                              or not (1 <= len(slide.strip()) <= 255)):
        return jsonify(error="必须提供有效的业务切片标识（slide）",
                       code="invalid_request"), 400
    if slide is None and slide_id_in is None:
        return jsonify(error="必须提供有效的业务切片标识（slide）",
                       code="invalid_request"), 400
    slide = slide.strip() if isinstance(slide, str) else None
    sid = None
    if slide_id_in:
        desc = slide_store.resolve_slide_id(slide_id_in.strip())
        if desc is None:
            return jsonify(error="切片不存在", code="slide_not_found"), 404
        sid = desc.slide_id
        if slide:
            by_name = share_store.get_slide_id(slide)
            if by_name is not None and by_name != sid:
                return jsonify(error="slide 与 slide_id 指向不同资产",
                               code="slide_ref_conflict"), 400
        # ACL（§6.1 资源权利）：按 descriptor owner 判定
        owner = desc.owner_user_id
        if slide is None:
            # 名称快照仅作记录兜底（伪名由 slide_id 派生，不存真实名）
            slide = desc.legacy_filename or desc.original_filename or sid
    else:
        # ACL：本人拥有（§6.1 资源权利——研究第一版只允许本人拥有的切片）
        owner = _slide_owner(slide)
        try:
            sid = share_store.get_slide_id(slide)
        except Exception:
            sid = None
    if not owner or owner != user_id:
        return jsonify(
            error="仅本人拥有的切片可用于研究共享",
            code="resource_not_owned"), 403
    # P2（合同 §3.4/R-11）：新会话的 slide_pseudonym 改从 slide_id 派生
    # （HMAC("slide-id:"+slide_id)）——同资产改名不再产生不同研究伪名；
    # 历史伪名不动。研究删除按 user 维度执行（research_deletion_jobs 无
    # slide 维度），无回绑风险。
    try:
        view = research_store.create_viewing_session(user_id, slide,
                                                     slide_id=sid)
    except Exception as exc:  # noqa: BLE001 - 统一映射
        return _research_store_error_response(exc)
    return jsonify(ok=True,
                   viewing_session_id=view["viewing_session_id"],
                   schema_version=view["schema_version"],
                   consent_epoch=view["consent_epoch"],
                   started_day=view["started_day"],
                   status=view["status"],
                   expires_at=_p2_rfc3339(view["expires_at"]))


@app.route("/api/research/viewer-events", methods=["POST"])
def api_research_viewer_events():
    """批次上传研究读片事件（§7.3）。

    body: ``{viewing_session_id, consent_epoch, events: [...]}``：

    - 主体从 session 解析（session → subject → user），body 携带的任何
      user/owner/资源字段一律忽略（白名单外整批 400）；
    - 批次 ≤50 条、≤64 KiB（超限 400/413，不部分写入）；
    - 事件 enum/seq/id/数值/字段白名单校验失败 → 整批 400；
    - 未授权 403；epoch 与会话或当前不一致 409；限流 429（Retry-After）；
      存储故障 503；响应不含账号与原始文件路径；
    - 相同 event_id 重传幂等（内容一致 replayed）；不同内容复用 ID 409。
    """
    user_id, err = _research_ingest_actor()
    if err:
        return err
    raw = request.get_data(cache=True)
    if len(raw) > research_store.BATCH_MAX_BYTES:
        return jsonify(error="请求体超过 64 KiB 上限",
                       code="payload_too_large"), 413
    try:
        body = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return jsonify(error="请求体必须是合法 JSON",
                       code="invalid_request"), 400
    if not isinstance(body, dict):
        return jsonify(error="请求体必须是 JSON 对象",
                       code="invalid_request"), 400
    unknown = sorted(set(body.keys())
                     - {"viewing_session_id", "consent_epoch", "events"})
    if unknown:
        return jsonify(error="请求体含未知字段 %s" % unknown,
                       code="invalid_request"), 400
    sid = body.get("viewing_session_id")
    if not isinstance(sid, str) or not sid:
        return jsonify(error="必须提供 viewing_session_id",
                       code="invalid_request"), 400
    epoch = body.get("consent_epoch")
    if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 1:
        return jsonify(error="consent_epoch 必须是 >=1 的整数",
                       code="invalid_request"), 400
    events = body.get("events")
    if not isinstance(events, list) or not events:
        return jsonify(error="events 必须是非空数组",
                       code="invalid_request"), 400
    if len(events) > research_store.BATCH_MAX_EVENTS:
        return jsonify(error="单批次最多 %d 条事件"
                       % research_store.BATCH_MAX_EVENTS,
                       code="batch_too_large"), 400
    try:
        result = research_store.append_viewer_events(
            user_id, sid, epoch, events, body_bytes=len(raw))
    except Exception as exc:  # noqa: BLE001 - 统一映射
        return _research_store_error_response(exc)
    return jsonify(ok=True, accepted=result["accepted"],
                   replayed=result["replayed"])


@app.route("/api/registration/resend", methods=["POST"])
def api_registration_resend():
    """退役（2026-10-08 §4）：旧 email_verify 形态的 JSON 重发接口下线。

    该端点只服务于 email_verify_invite_activation 模式（已从词表移除，
    永远 403）；public 流程的主动重发是 POST /register/resend（表单 +
    Turnstile + submission_id 幂等，见 register_resend）。对任何已登录/
    匿名调用方稳定 410 endpoint_retired，不写队列、不动任何 token。
    """
    return jsonify(error="该注册重发入口已退役：请返回注册页重新开始",
                   code="endpoint_retired"), 410


# =========================================================================== #
# 匿名 Demo（Phase 2，docs §5/§9.1/§9.3/§12.1）
#
# 结构原则（fail-closed，逐条对设计）：
#   - /api/demo/* 绝不调用 current_identity()（无 role→owner 归一）；身份一律
#     来自独立 Demo capability cookie（demo_capability → demo_sessions token_hash）；
#   - PostgreSQL 唯一后端：/api/demo/* 不依赖 json/dual 判定的 503（旧
#     pg_backend_required 门已随 R3 Wave3 退役）；
#   - 公开 Demo 模式（PUBLIC_DEMO_ENABLED=1 或周期 demo_enabled=true）下，HistoPilot
#     healthz 的 adapter 必须是 plugin-contract；探测失败/legacy → /demo AI 与
#     /api/demo/ai/run fail-closed（§5.4-1）；同时禁用 /internal/ai/annotate 写通道；
#   - capability 只能调 /api/demo/*：其余端点不读该 cookie（登录态 session 鉴权
#     照常 401）；
#   - slide 一律按 demo_catalog allowlist（slide_id）校验，不接受任意文件名。
# =========================================================================== #
#: Demo capability cookie 名（与登录 session cookie 分离，docs §5.2/§10.3）
DEMO_CAPABILITY_COOKIE = "demo_capability"
#: Demo run 用户任务限长（docs §5.3：最多 300 字或预设任务）
DEMO_TASK_MAX_CHARS = 300
#: Demo session 可重连窗口（0026 起 = accepted_at + 1h；与 demo_store 的
#: accepted run 活跃窗口同源，run 到期由 finish/对账/惰性路径转终态）
DEMO_SESSION_RECONNECT_SECONDS = demo_store.DEMO_RUN_RECONNECT_WINDOW_SECONDS
#: Demo 安全协商 envelope（docs §5.4；与 HistoPilot security-envelope.ts 常量一致）
DEMO_SECURITY_CONTRACT_VERSION = "1.0"
DEMO_TOOL_PROFILE = "demo-readonly-v1"
DEMO_SESSION_TTL_SECONDS = 86400
DEMO_REQUIRED_FEATURES = [
    "tool-profile:demo-readonly-v1",
    "session:ephemeral-v1",
    "session-ttl:v1",
]
#: 官方 run 携带 extra_tools 时的安全协商 envelope（docs §5.1/§5.3；与
#: HistoPilot security-envelope.ts 的 standard-v1 / extra-tools:v1 一致）。
#: standard-v1 行为等价于无信封的官方 run（非只读、非 ephemeral），仅作为
#: extra-tools:v1 授权的合法信封载体；sidecar fail-closed 要求 config 携带
#: extra_tools 时信封必须声明 extra-tools:v1。
AGENT_TOOL_PROFILE_STANDARD = "standard-v1"
AGENT_EXTRA_TOOLS_ENVELOPE = {
    "security_contract_version": DEMO_SECURITY_CONTRACT_VERSION,
    "required_features": [
        "tool-profile:standard-v1",
        "extra-tools:v1",
    ],
    "tool_profile": AGENT_TOOL_PROFILE_STANDARD,
}


def _demo_token_hash(token: str) -> str:
    """Demo capability 明文 token 的带盐 hash（库中只存 hash，docs §5.2）。"""
    return hmac.new(
        ("democap:" + _auth_hash_salt()).encode("utf-8"),
        (token or "").encode("utf-8"), hashlib.sha256).hexdigest()


def _demo_subject(token_hash: str) -> str:
    """HistoPilot session_owner 用的不可反推 Demo subject（docs §5.4）。

    ``demo_`` + token_hash 前 16 位——不含 IP、不含 cookie 明文，不可反推回
    真实浏览器身份（token_hash 本身已是带盐单向哈希）。
    """
    return "demo_" + (token_hash or "")[:16]


def _demo_require_open():
    """公开 Demo 已开启；否则 403（切片与 AI 一并拒绝）。"""
    if not _demo_public_mode():
        return (jsonify(error="Demo 当前未开放", code="demo_disabled"), 403)
    return None


def _demo_public_mode() -> bool:
    """公开 Demo 是否开启：PUBLIC_DEMO_ENABLED=1 或 ai_safety.demo_enabled。

    批次 F：demo_enabled 自 ai_budget_periods 列迁居 platform_settings
    （settings_store.get_ai_safety_settings，0027 backfill 已搬值）。
    """
    if platform_features.public_demo_enabled():
        return True
    try:
        return bool(settings_store.get_ai_safety_settings()["demo_enabled"])
    except Exception:
        app.logger.warning("读取 Demo 开关失败（按关闭处理）", exc_info=True)
        return False


def _demo_task_max_steps() -> int:
    """Demo 单次任务步骤（ai_safety.demo_task_max_steps，默认 100；docs §4.1/§5.3）。

    工单 C（plan 20260919 §4）：默认自 20 抬到 100（0058 迁移同步 DB 缺省与
    旧缺省存量；运行时仍钳制 _MAX_STEPS_LIMIT=100，只读工具/单任务/预算闸
    不变——100 是上限，任务允许提前结束）。
    批次 F：自周期列迁居 platform_settings（settings_store 统一设置源）。
    读取失败按默认处理（保守内置上限，方向不变）但不再静默——对齐
    _demo_public_mode 的写法记 warning（fix 2026-09-11 P4：管理员调紧后
    被静默放宽必须留痕）。
    """
    try:
        raw = settings_store.get_ai_safety_settings()["demo_task_max_steps"]
        v = int(raw)
    except Exception:
        app.logger.warning("读取 Demo 步数上限失败（按默认 %d 处理）",
                           budget_store.DEFAULT_DEMO_TASK_MAX_STEPS,
                           exc_info=True)
        v = budget_store.DEFAULT_DEMO_TASK_MAX_STEPS
    return max(1, min(v, _MAX_STEPS_LIMIT))


# --------------------------------------------------------------------------- #
# HistoPilot adapter mode 探测（公开 Demo 前置，docs §5.4-1）
# --------------------------------------------------------------------------- #
_ADAPTER_MODE_CACHE = {"ts": 0.0, "mode": None}
#: 探测结果短缓存（避免每个请求打一次 HistoPilot；TESTING 下不缓存保证可测）
_ADAPTER_MODE_TTL_SECONDS = 15.0


def _histopilot_adapter_mode(force=False):
    """探测 HistoPilot /healthz 的 adapter mode。

    返回 "plugin-contract" / "legacy" / None（不可达或应答异常）。legacy adapter
    不消费 run grant，不能用于任何声称只读的 Demo（§5.4-1）。
    """
    ttl = 0.0 if app.config.get("TESTING") else _ADAPTER_MODE_TTL_SECONDS
    now = time.time()
    if not force and now - _ADAPTER_MODE_CACHE["ts"] < ttl:
        return _ADAPTER_MODE_CACHE["mode"]
    mode = None
    try:
        r = requests.get(AI_SIDECAR_URL.rstrip("/") + "/healthz", timeout=3.0,
                         headers=_sidecar_auth_headers())
        if r.status_code == 200:
            mode = ((r.json() or {}).get("adapter")) or None
    except Exception:
        mode = None
    _ADAPTER_MODE_CACHE.update(ts=now, mode=mode)
    return mode


def _demo_adapter_gate():
    """公开 Demo AI 前置闸：HistoPilot 可达且 adapter=plugin-contract，否则 503。"""
    mode = _histopilot_adapter_mode()
    if mode == "plugin-contract":
        return None, mode
    if mode == "legacy":
        return (
            jsonify(error="HistoPilot 正运行 legacy adapter，公开 Demo 已按安全"
                          "策略停用（需要 plugin-contract；legacy 不消费 run grant）",
                    code="histopilot_legacy_adapter"),
            503,
        ), mode
    return (
        jsonify(error="HistoPilot 不可达，Demo AI 暂不可用（切片仍可浏览）",
                code="histopilot_unreachable"),
        503,
    ), mode


# --------------------------------------------------------------------------- #
# Demo capability 解析与签发（docs §5.2）
# --------------------------------------------------------------------------- #
def _demo_current_capability():
    """从 cookie 解析有效 Demo capability。

    返回 (capability_dict|None, reason)：reason ∈ None / "missing"（无 cookie）/
    "invalid"（过期、被撤销或库中无此 hash）。**绝不**回落到登录 session。
    """
    token = request.cookies.get(DEMO_CAPABILITY_COOKIE) or ""
    if not token:
        return None, "missing"
    try:
        cap = demo_store.get_valid_capability(_demo_token_hash(token))
    except Exception:
        app.logger.warning("Demo capability 读取失败", exc_info=True)
        return None, "invalid"
    if cap is None:
        return None, "invalid"
    return cap, None


def _demo_require_capability():
    """Demo API 的 capability fail-closed 守卫。

    返回 (capability, None) 或 (None, error_response)：无 cookie → 401；
    cookie 存在但无效/过期/已撤销 → 410 capability_expired（docs §5.2：过期或
    退出后不能继续查看 AI session）。
    """
    cap, why = _demo_current_capability()
    if cap is not None:
        return cap, None
    if why == "missing":
        return None, (jsonify(error="缺少 Demo capability", code="capability_missing"), 401)
    return None, (jsonify(error="Demo capability 已失效或过期", code="capability_expired"), 410)


def _demo_issue_capability():
    """（无有效 cookie 时）生成新 Demo capability（不落 cookie）。

    返回 (capability|None, token|None)：随机不透明 token（secrets）只留在浏览器，
    库中只写 hash；签发失败 (None, None) 不阻断页面。
    """
    cap, _why = _demo_current_capability()
    if cap is not None:
        return cap, None
    token = secrets.token_urlsafe(32)
    ip_hash = _ip_prefix_hash(request.remote_addr or "") or None
    try:
        cap = demo_store.create_capability(
            "dcp_" + secrets.token_hex(8), _demo_token_hash(token),
            ip_prefix_hash=ip_hash)
    except Exception:
        app.logger.warning("Demo capability 签发失败", exc_info=True)
        return None, None
    return cap, token


def _demo_capability_cookie_attrs(resp, token):
    """把 capability 明文 token 写入响应 cookie（HttpOnly/Lax/Secure/24h）。"""
    resp.set_cookie(
        DEMO_CAPABILITY_COOKIE, token,
        httponly=True, samesite="Lax",
        secure=bool(app.config.get("SESSION_COOKIE_SECURE", False)),
        max_age=int(demo_store.DEMO_CAPABILITY_TTL_HOURS * 3600),
        path="/",
    )
    return resp


def _demo_set_capability_cookie(resp):
    """签发新 Demo capability 并 Set-Cookie（docs §5.2）；返回 capability|None。"""
    cap, token = _demo_issue_capability()
    if cap is not None and token:
        _demo_capability_cookie_attrs(resp, token)
    return cap


# --------------------------------------------------------------------------- #
# Demo 切片 allowlist 解析（docs §5.1：独立 demo_catalog，public ≠ 匿名可见）
# --------------------------------------------------------------------------- #
def _demo_catalog_slide(slide_id):
    """校验 slide_id 在 Demo 目录并解析为 descriptor（P1-B2）。

    返回 (entry, desc) 或 (None, None)：不在目录 / slides 行缺失 /
    authorize_read(demo_capability=True, allow_public=False) 不通过
    （asset_state='ready' 唯一可见性开关；allowlist 唯一入口，public ≠
    匿名可见）一律 None（fail-closed，绝不按文件名猜）。P2 收口：无行兜底
    分支已删除（catalog 项必须 resolve_slide_id 命中且 ready）。
    P3：**id_bundle 资产（legacy_filename=NULL）放行**——demo 读端点全部经
    descriptor 路径（_desc_read_path/_get_slide），名不再是前置条件（P1 时
    的 NULL 拒绝是尚无 id_bundle writer 的过渡口径）。
    """
    if not isinstance(slide_id, str) or not slide_id:
        return None, None
    try:
        entry = demo_store.catalog_get(slide_id)
        if entry is None:
            return None, None
        desc = slide_store.resolve_slide_id(slide_id)
    except Exception:
        app.logger.warning("Demo 目录读取失败", exc_info=True)
        return None, None
    # P2 收口（合同 §3.4 / P1-B2 遗留）：resolve_slide_id 必须命中——catalog
    # 项指向无 slides 行的资产一律 fail-closed（404/409 由调用方裁决），
    # resolve_slide_filename 的 id→filename 兜底分支已删除（demo_store 侧
    # 函数保留给目录列表展示）。
    if desc is None:
        return None, None
    if not slide_store.authorize_read(desc, demo_capability=True,
                                      allow_public=False):
        return None, None
    return entry, desc


def _demo_request_lang():
    """Demo 目录展示语言（工单 B）：``?lang=`` 优先，其次 Accept-Language。

    只认 ``zh``/``en``（与前端 HP_I18N.getLang 同集），其余一律 zh（缺省语言）。
    仅影响 API 载荷里的便利字段 ``display_name``/``description``；双语原始
    字段恒返回，前端自身按当前语言选择（切换语言无需重载）。
    """
    raw = (request.args.get("lang") or "").strip().lower()
    if not raw:
        accept = (request.headers.get("Accept-Language") or "").lower()
        raw = accept.split(",")[0].strip() if accept else ""
    return "en" if raw.startswith("en") else "zh"


def _demo_localized_entry(entry, lang=None):
    """目录条目双语出口：补齐 ``*_en`` 字段 + 当前语言的便利字段。

    ``display_name``/``description`` 恒为中文/缺省语言原值；lang=en 时额外
    提供 ``localized_display_name``/``localized_description``（无英文译文回落
    缺省字段，明确回退不猜值）。不修改 slide_id / 原始文件名。
    """
    out = dict(entry)
    out.setdefault("display_name_en", None)
    out.setdefault("description_en", None)
    lang = lang or _demo_request_lang()
    if lang == "en":
        out["localized_display_name"] = (
            out.get("display_name_en") or out.get("display_name"))
        out["localized_description"] = (
            out.get("description_en") or out.get("description"))
    else:
        out["localized_display_name"] = out.get("display_name")
        out["localized_description"] = out.get("description")
    return out


# --------------------------------------------------------------------------- #
# /demo 页面与 /api/demo/*（docs §9.1）
# --------------------------------------------------------------------------- #
@app.route("/demo")
def demo_landing():
    """Demo 只读 Viewer 入口（Phase 2，docs §5.6）。

    服务端渲染明确的 demo 模式（非 CSS 隐藏）：PostgreSQL 为唯一后端。
    """
    enabled = bool(_demo_public_mode())
    adapter_mode = _histopilot_adapter_mode() if enabled else None
    # 仅模板渲染用登录态（已登录访问 /demo 时 CTA 切换为“打开完整版”）；
    # /api/demo/* 面仍不读 identity，capability 安全设计不变
    logged_in = bool(session.get("auth_user"))
    resp = make_response(render_template(
        "demo.html",
        app_mode="demo",
        capabilities=_app_capabilities("demo"),
        histopilot_ui_enabled=False,
        demo_available=True,
        demo_enabled=enabled,
        adapter_mode=adapter_mode,
        logged_in=logged_in,
        canonical=_public_canonical_url("/demo"),
    ))
    # 入口 HTML 可重新验证（§5.3）：普通刷新必须取得新 UI
    resp.headers["Cache-Control"] = "no-cache"
    if enabled:
        _demo_set_capability_cookie(resp)
    return resp


@app.route("/api/demo/config")
def api_demo_config():
    """Demo 开关 / run 状态 / AI 可达性（capability 首次在此签发，docs §9.1）。

    批次 E（§4.1）：run 状态来自 demo_runs 最近一次流水（capability 与 run
    分离；同 capability 顺序多次 run，无每浏览器累计上限）。``run_state`` ∈
    reserved|accepted（在途）| finished|released|expired（终态）| None（未跑过）；
    ``histopilot_session_id`` / ``session_reconnect_until`` 取最近一次已接受 run。

    批次 F：``spend`` 段为金额口径（Demo 周金额窗口 limit/spent/reserved，
    十进制字符串 nano-CNY + demo_exhausted），只读不建窗；``budget`` 段为
    turn 口径冻结历史（legacy=true，软闸回退期前端兜底）。
    """
    payload = {
        "demo_enabled": _demo_public_mode(),
        "task_max_chars": DEMO_TASK_MAX_CHARS,
        "task_max_steps": _demo_task_max_steps(),
        "run_state": None,
        "histopilot_session_id": None,
        "session_reconnect_until": None,
        "active_run": False,
        "budget": None,
    }
    # adapter / AI 可达性（探测失败也返回 200：Viewer 仍可浏览切片，§5.6）
    gate, mode = _demo_adapter_gate()
    payload["adapter_mode"] = mode
    payload["ai_available"] = gate is None
    payload["ai_unavailable_code"] = None if gate is None else (
        gate[0].get_json().get("code"))
    # 本浏览器最近一次 run + 平台/Demo 预算余量（读失败不阻断 config）
    try:
        cap, _why = _demo_current_capability()
    except Exception:
        cap = None
    if cap is not None:
        try:
            run = demo_store.latest_run_for_capability(cap["id"])
        except Exception:
            app.logger.warning("Demo run 状态读取失败", exc_info=True)
            run = None
        if run is not None:
            payload["run_state"] = run.get("state")
            payload["active_run"] = run.get("state") in demo_store.RUN_ACTIVE_STATES
            sid = run.get("histopilot_session_id")
            accepted_at = run.get("accepted_at")
            if sid and run.get("state") in ("accepted", "finished") \
                    and accepted_at:
                payload["histopilot_session_id"] = sid
                payload["session_reconnect_until"] = (
                    float(accepted_at) + DEMO_SESSION_RECONNECT_SECONDS)
    try:
        report = budget_store.usage_report()
        demo_total = report["demo"]["total"]
        plat_total = report["platform"]["total"]
        payload["budget"] = {
            # 批次 F：turn 口径已随消费闸退役失真（mode=all 时不再更新），
            # legacy 标记提示前端优先读 spend 段（软闸回退期仍作兜底）
            "legacy": True,
            "demo_used": demo_total,
            "demo_limit": report["demo"]["limit"],
            "demo_exhausted": demo_total + 1 > report["demo"]["limit"],
            "platform_used": plat_total,
            "platform_limit": report["platform"]["limit"],
            "platform_exhausted": plat_total + 1 > report["platform"]["limit"],
        }
    except Exception:
        app.logger.warning("Demo 额度状态读取失败", exc_info=True)
    # 批次 F：金额口径 spend 段（Demo 周金额窗口，十进制字符串 nano-CNY）。
    # 只读不建窗（peek_current_window）：无窗口时 exhausted=false、数值 "0"，
    # 上限回落策略面值（demo_global 默认 50 CNY）；读失败不阻断 config。
    payload["spend"] = {
        "week_limit_nano_cny": "0",
        "week_spent_nano_cny": "0",
        "week_reserved_nano_cny": "0",
        "demo_exhausted": False,
    }
    try:
        window = spend_store.peek_current_window(
            "demo", spend_store.DEMO_GLOBAL_SUBJECT)
        if window is not None:
            limit_nano = int(window["limit_nano_snapshot"])
            spent_nano = int(window["spent_nano_cny"])
            reserved_nano = int(window["reserved_nano_cny"])
        else:
            policy = spend_store.resolve_policy(
                "demo", spend_store.DEMO_GLOBAL_SUBJECT)
            limit_nano = int(policy["limit_nano_cny"]) if policy else 0
            spent_nano = 0
            reserved_nano = 0
        payload["spend"] = {
            "week_limit_nano_cny": str(limit_nano),
            "week_spent_nano_cny": str(spent_nano),
            "week_reserved_nano_cny": str(reserved_nano),
            "demo_exhausted": bool(
                limit_nano > 0
                and spent_nano + reserved_nano >= limit_nano),
        }
    except Exception:
        app.logger.warning("Demo 金额窗口状态读取失败", exc_info=True)
    issued_token = None
    if cap is None and _demo_public_mode():
        try:
            issued_cap, issued_token = _demo_issue_capability()
            if issued_cap is not None:
                # 首次签发：新 capability 无 run（run_state=None，可立即体验）
                payload["run_state"] = None
                payload["active_run"] = False
        except Exception:
            app.logger.warning("Demo capability 签发失败", exc_info=True)
    resp = jsonify(payload)
    if issued_token:
        _demo_capability_cookie_attrs(resp, issued_token)
    return resp


@app.route("/api/demo/slides")
def api_demo_slides():
    """Demo 目录切片摘要（allowlist 内条目 + 稳定 slide_id，docs §5.1/§9.1）。

    工单 B（双语）：条目同时返回 ``display_name``/``description``（中文/缺省
    语言）与 ``display_name_en``/``description_en``（可空 = 无译文）；另按
    ``?lang=``/Accept-Language 提供 ``localized_display_name``/
    ``localized_description`` 便利字段。前端（demo.js）按 HP_I18N.getLang()
    自行选择，切换语言无需重载。slide_id 与原始文件名恒不变。
    """
    err = _demo_require_open()
    if err is not None:
        return err
    cap, cap_err = _demo_require_capability()
    if cap_err is not None:
        return cap_err
    lang = _demo_request_lang()
    items = []
    try:
        for entry in demo_store.catalog_list_ordered():
            filename = demo_store.resolve_slide_filename(entry["slide_id"])
            if not filename:
                continue  # 行缺失/无映射：fail-closed 不展示
            item = _demo_localized_entry(entry, lang)
            item["name"] = filename
            items.append(item)
    except Exception:
        app.logger.warning("Demo 目录读取失败", exc_info=True)
        return jsonify(error="demo catalog 不可用"), 503
    return jsonify({"slides": items})


@app.route("/api/demo/slides/<slide_id>/info")
def api_demo_slide_info(slide_id):
    """Demo 切片信息；slide_id 必须在 catalog（否则 404，docs §12.1）。"""
    err = _demo_require_open()
    if err is not None:
        return err
    cap, cap_err = _demo_require_capability()
    if cap_err is not None:
        return cap_err
    entry, desc = _demo_catalog_slide(slide_id)
    if entry is None:
        return jsonify(error="slide 不在 Demo 目录内", code="slide_not_in_catalog"), 404
    path = _desc_read_path(desc)
    info = _slide_info_dict_desc(desc, path)
    info["slide_id"] = slide_id
    # 工单 B：demo_* 双语展示字段（en 可空 = 无译文，前端回落缺省字段）
    if entry.get("display_name"):
        info["demo_display_name"] = entry["display_name"]
    if entry.get("description"):
        info["demo_description"] = entry["description"]
    if entry.get("display_name_en"):
        info["demo_display_name_en"] = entry["display_name_en"]
    if entry.get("description_en"):
        info["demo_description_en"] = entry["description_en"]
    info["demo_is_default"] = bool(entry.get("is_default"))
    if not info.get("error"):
        # Batch 3（§6.1）：render additive 字段与主站同一份 manifest/统计
        # image-transport-upgrade：Demo 无缩略图能力 → 不输出 thumbnail 描述
        try:
            info.update(_slide_render_info_fields(
                desc, include_thumbnail=False))
        except (slide_render.RenderRequestError,
                slide_io.SlideRenderError) as e:
            return _render_error_response(e)
        except slide_cache.SlideFileChanged:
            return jsonify(error="slide_file_changed",
                           code="slide_file_changed"), 503
    return jsonify(info)


