def _demo_ip_request_rate_gate():
    """Demo 短窗口请求速率闸（批次 E §1.2/§4.1：防刷/防 DoS，非消费额度）。

    每 IP 前缀每分钟**请求数**（PG 权威固定窗口计数，不累计成功次数——
    24h 成功 run 桶已退役）。超限 → 429 ``demo_ip_request_rate_limited`` +
    Retry-After。``DEMO_IP_RATE_PER_MINUTE`` ≤ 0 关闭该桶。存储异常 fail-closed
    （429，不得因抖动放行洪泛）。
    """
    limit = demo_store.ip_rate_limit()
    if limit <= 0:
        return None
    ip_hash = _ip_prefix_hash(request.remote_addr or "") or "unknown"
    try:
        usage = demo_store.hit_ip_request_rate(ip_hash, limit=limit)
    except Exception:
        app.logger.warning("Demo IP 请求速率计数失败（fail-closed）",
                           exc_info=True)
        return (jsonify(error="Demo 暂时无法确认访问频率，请稍后重试",
                        code="demo_ip_request_rate_limited"), 429)
    if usage.get("allowed") is not False:
        return None
    retry = max(1, int(usage.get("retry_after_seconds") or 0)
                or demo_store.ip_rate_window_seconds())
    resp = jsonify(
        error="请求过于频繁，请稍后再试",
        code="demo_ip_request_rate_limited",
        retry_after_seconds=retry,
        limit=limit,
        used=int(usage.get("count") or 0),
    )
    resp.status_code = 429
    resp.headers["Retry-After"] = str(retry)
    return resp


@app.route("/api/demo/ai/run", methods=["POST"])
def api_demo_ai_run():
    """Demo 一次性只读 AI run（docs §5.3/§5.4；单请求内按序推进，失败回滚）。

    批次 E（§4.1）：capability 与 run 分离——每次 run 是 demo_runs 独立流水，
    上一次终态后即可再开（无限顺序体验）；同 capability 同时最多一个
    reserved/accepted run（DB 部分唯一索引硬保证，409 ``demo_run_in_progress``）。

    顺序：capability → Demo 开关 → adapter 闸 → catalog allowlist → request_id
    → IP 短窗口请求速率闸 → demo_store.reserve_run（capability 行锁 + 惰性
    过期 + active 冲突判定）→ budget_store.reserve_turn → 组装 /run body
    （平台凭据 + demo_task_max_steps + security envelope，**不发 run_grant**）→
    代理 SSE；2xx（security_profile_applied 已确保，X-AI-Session-ID）→ accept；
    上游流正常结束 → finish（capability 解锁，可开下一个 run）；4xx/连接失败
    → release。禁止 continue/ask/branch（docs §5.3 表）。
    """
    err = _demo_require_open()
    if err is not None:
        return err
    gate, _mode = _demo_adapter_gate()
    if gate is not None:
        return gate
    cap, cap_err = _demo_require_capability()
    if cap_err is not None:
        return cap_err
    body = request.get_json(silent=True) or {}
    slide_id = body.get("slide_id") if isinstance(body.get("slide_id"), str) else None
    entry, desc = _demo_catalog_slide(slide_id)
    if entry is None:
        return (jsonify(error="slide 不在 Demo 目录内", code="slide_not_in_catalog"),
                404)
    task = body.get("task")
    if task is not None and (not isinstance(task, str)
                             or len(task) > DEMO_TASK_MAX_CHARS):
        return (jsonify(error="task 非法：需字符串且最多 %d 字"
                        % DEMO_TASK_MAX_CHARS, code="task_too_long"), 400)
    rid, rid_err = _parse_client_request_id(body)
    if rid_err is not None:
        return rid_err
    ip_gate = _demo_ip_request_rate_gate()
    if ip_gate is not None:
        return ip_gate
    safe = desc.legacy_filename or desc.original_filename or ""
    _demo_run_path = _desc_path(desc)

    # 惰性对账（docs §5.3-5：每次新预占前回收过期项；对账含 HistoPilot 反查）
    try:
        reconcile_expired_reservations()
    except Exception:
        app.logger.warning("Demo 预占前惰性对账失败（不阻断）", exc_info=True)

    # 3) run 预占：demo_runs 流水（capability 行锁内：过期校验 + 惰性终态 +
    #    同 ID 幂等 + 单 active 冲突 + 全局并发闸（批次 F 迁入，上限读
    #    ai_safety.demo_max_concurrency）；DB 部分唯一索引兜底并发）
    try:
        run = demo_store.reserve_run(
            cap["id"], rid, slide_id, _slide_revision(desc, _demo_run_path),
            ip_prefix_hash=_ip_prefix_hash(request.remote_addr or "") or "unknown")
    except demo_store.DemoCapabilityExpired:
        return (jsonify(error="Demo capability 已失效或过期",
                        code="capability_expired"), 410)
    except demo_store.DemoRunActiveConflict as exc:
        return (jsonify(error="本次体验仍在进行中，请等待当前运行结束",
                        code="demo_run_in_progress",
                        active_run=True), 409)
    except demo_store.DemoRunFinalConflict as exc:
        return (jsonify(error="该请求已结束，请重新发起体验",
                        code="demo_run_request_final"), 409)
    except demo_store.DemoConcurrencyExceeded as exc:
        # 批次 F：并发闸迁居 demo_store（安全参数，独立于已退役的 turn 消费闸）
        return _budget_error_response(exc, 429)
    if run is None:
        # capability 在守卫与预占之间消失（撤销/过期竞态）：按失效处理
        return (jsonify(error="Demo capability 已失效或过期",
                        code="capability_expired"), 410)
    demo_run_id = run["demo_run_id"]
    run_attempt = run.get("attempt")
    run_rollback_epoch = int(run.get("rollback_epoch") or 0)

    def _rollback_demo_run(reason, expected_attempt=None, expected_request_id=None,
                           expected_rollback_epoch=None):
        """预占后、HistoPilot 接受前的统一回滚（幂等；accepted 拒绝释放）。"""
        if run.get("replayed"):
            app.logger.info("Demo 在途 request_id 重放失败，不释放原 run：%s (%s)",
                            rid, reason)
            return
        try:
            demo_store.release_run(
                demo_run_id, expected_attempt=expected_attempt,
                expected_request_id=expected_request_id,
                expected_rollback_epoch=expected_rollback_epoch)
        except demo_store.RunAttemptConflict:
            app.logger.warning("Demo run 回滚遇 attempt 冲突（保留新尝试）：%s",
                               reason)
        except ValueError:
            app.logger.warning("Demo run 回滚遇 accepted（防误退款保留）：%s",
                               reason)
        except Exception:
            app.logger.warning("Demo run 回滚失败：%s", reason, exc_info=True)

    # 4) 消费闸分流（批次 F §7.3 阶段 2）：demo 主体绑定本就在
    #    demo_runs.histopilot_session_id，**不写 ai_run_bindings**。金额硬闸
    #    （mode=all，demo 硬）→ 完全跳过 budget_store.reserve_turn（turn 消费
    #    闸关闭，消费额度由 Demo 周金额窗口独占）；软闸回退（shadow/
    #    registered）→ Demo 子额度 + 平台总预算原子预占（超限释放 run，不
    #    回退其它凭据）——既有行为逐字保留。
    spend_hard_demo = spend_store.mode_is_hard(_spend_mode_snapshot(), "demo")
    if spend_hard_demo:
        resv = None
    else:
        try:
            resv = budget_store.reserve_turn(rid, "demo", cap["id"], "platform")
        except budget_store.DemoConcurrencyExceeded as exc:
            _rollback_demo_run("demo_concurrency_exceeded",
                               expected_attempt=run_attempt,
                               expected_request_id=rid,
                               expected_rollback_epoch=run_rollback_epoch)
            return _budget_error_response(exc, 429)
        except budget_store.DemoBudgetExhausted as exc:
            _rollback_demo_run("demo_budget_exhausted", expected_attempt=run_attempt,
                               expected_request_id=rid,
                               expected_rollback_epoch=run_rollback_epoch)
            return _budget_error_response(exc, 429)
        except budget_store.PlatformBudgetExhausted as exc:
            _rollback_demo_run("platform_ai_budget_exhausted",
                               expected_attempt=run_attempt,
                               expected_request_id=rid,
                               expected_rollback_epoch=run_rollback_epoch)
            return _budget_error_response(exc, 429)
        except budget_store.BudgetError as exc:
            _rollback_demo_run("budget_error", expected_attempt=run_attempt,
                               expected_request_id=rid,
                               expected_rollback_epoch=run_rollback_epoch)
            return _budget_error_response(exc, 409)

    resv_attempt = (resv or {}).get("attempt")
    resv_rollback_epoch = int((resv or {}).get("rollback_epoch") or 0)

    def _rollback_all(reason):
        _rollback_demo_run(reason, expected_attempt=run_attempt,
                           expected_request_id=rid,
                           expected_rollback_epoch=run_rollback_epoch)
        if resv is None:
            return  # 硬闸分支无预占可退（turn 闸已关闭）
        if resv.get("replayed"):
            app.logger.info("Demo 在途预算重放失败，不释放原预占：%s", rid)
            return
        try:
            budget_store.release(
                rid, expected_attempt=resv_attempt,
                expected_rollback_epoch=resv_rollback_epoch)
        except budget_store.ReservationAttemptConflict:
            app.logger.warning("预算回滚遇 attempt 冲突（保留新尝试）：%s", reason)
        except ValueError:
            app.logger.warning("预算回滚遇 consumed（防误退款保留）：%s", reason)
        except Exception:
            app.logger.warning("预算回滚失败：%s", reason, exc_info=True)

    # 5) /run body：平台凭据 + 周期 demo_task_max_steps；不发 run_grant（只读
    #    tool profile 无平台写工具，docs §5.4-5）；session_owner 用不可反推 subject。
    #    demo_capability_id 供官方模式伪名 user_id 隔离：匿名 Demo scope =
    #    "demo:" + capability_id（dcp_* 每浏览器伪名，§4.2，绝不共用匿名 scope）。
    config = _build_sidecar_config(None, demo_capability_id=cap["id"])
    if config is None:
        _rollback_all("platform_credentials_missing")
        return (jsonify(error="平台 AI 未配置，Demo AI 暂不可用（切片仍可浏览）",
                        code="platform_credentials_missing"), 503)
    config["max_steps"] = _demo_task_max_steps()
    config["session_owner"] = _demo_subject(cap["token_hash"])
    # 计费主体断言注入（PR2 §7.2）：demo_sessions.id（capability id）与
    # accept_run 绑定 histopilot_session_id 的 run 行同源（0026 起绑定在
    # demo_runs，resolver 第②步 SELECT capability_id 同值）；缺省回退
    # "unknown" 会 409 usage_subject_conflict 进 dead。
    config["billing_subject"] = _billing_subject_assertion(
        None, demo_capability_id=cap["id"])

    payload = {
        "slide": safe,
        "config": config,
        "request_id": rid,
        "security": {
            "security_contract_version": DEMO_SECURITY_CONTRACT_VERSION,
            "required_features": list(DEMO_REQUIRED_FEATURES),
            "tool_profile": DEMO_TOOL_PROFILE,
            "session_ttl_seconds": DEMO_SESSION_TTL_SECONDS,
            "request_id": rid,
        },
    }
    if task is not None:
        payload["task"] = task

    # 6/7) 代理 SSE；_proxy_sse 在 2xx（security_profile_applied 已由 HistoPilot
    #     在建流前发出/确保）时 on_accepted → accept（reserved→accepted + 预算
    #     consume）；4xx/连接失败 on_rejected → release；上游流**正常结束**
    #     on_finished → finish（accepted→finished 终态，capability 解锁，可顺序
    #     再开下一个 run；客户端提前断开不 finish——由重连窗口/对账收敛）。
    #     回调内部吞异常（交由对账兜底）。
    def on_accepted(hp_session_id):
        sid = hp_session_id or ""
        try:
            demo_store.accept_run(demo_run_id, sid,
                                  expected_attempt=run_attempt,
                                  expected_request_id=rid)
        except demo_store.RunAttemptConflict:
            app.logger.warning("Demo run accept attempt 冲突（对账兜底）",
                               exc_info=True)
        except Exception:
            app.logger.warning("Demo run accept 失败（对账兜底）", exc_info=True)
        if spend_hard_demo:
            # 硬闸分支：无 reservation 可 consume（turn 闸已关闭；demo 主体
            # 绑定已在 accept_run 写入 demo_runs.histopilot_session_id）
            return
        try:
            budget_store.consume(rid, sid, expected_attempt=resv_attempt)
        except budget_store.ReservationAttemptConflict:
            app.logger.warning("Demo 预算 consume attempt 冲突（对账兜底）",
                               exc_info=True)
        except Exception:
            app.logger.warning("Demo 预算 consume 失败（对账兜底）", exc_info=True)

    def on_finished(_session_id):
        # 流正常结束：run 转 finished 终态 → capability 可立即再开（顺序多次）
        try:
            demo_store.finish_run(demo_run_id)
        except Exception:
            app.logger.warning("Demo run finish 失败（对账兜底）", exc_info=True)

    def on_rejected():
        _rollback_all("histopilot_rejected")

    _audit("demo.ai.run", target_type="demo_session", target_id=cap["id"],
           slide=safe, detail={"request_id": rid, "slide_id": slide_id,
                                   "demo_run_id": demo_run_id})
    return _proxy_sse("/run", payload, on_accepted=on_accepted,
                      on_rejected=on_rejected, on_finished=on_finished)


@app.route("/api/demo/ai/session/<session_id>")
def api_demo_ai_session_detail(session_id):
    """Demo session snapshot（capability 绑定；不扣额度；docs §5.5 event_reset）。

    与 stream 同一授权：capability 有效且绑定该 histopilot_session_id，且在
    consumed_at + 1h 窗口内。供 UI 在 event_reset 后全量重建 transcript/overlay。
    """
    bound = _demo_session_access(session_id)
    if bound is not None:
        return bound
    return _proxy_json("/session/" + session_id, None, method="GET")


@app.route("/api/demo/ai/session/<session_id>/stream")
def api_demo_ai_session_stream(session_id):
    """Demo session SSE 重连（不扣额度，docs §5.3-3/§5.5）。

    仅当：capability 有效（过期/撤销 → 410）且该 capability 绑定的
    histopilot_session_id 与请求一致（拿别的 session id 读不到他人 session），
    且仍在 consumed_at + 1h 重连窗口内。
    """
    bound = _demo_session_access(session_id)
    if bound is not None:
        return bound
    return _proxy_sse("/session/{}/stream".format(session_id), None, method="GET")


def _demo_session_access(session_id):
    """Demo session 读通道共用守卫。通过返回 None；否则返回 error response。

    capability 有效（过期/撤销 → 410）且该 capability 的 demo_runs 流水中
    存在 histopilot_session_id 与请求一致的 accepted/finished run，且仍在
    accepted_at + 1h 重连窗口内（0026 起：capability 可顺序多次 run，各 run
    绑定各自 HP session，互不串读）。
    """
    err = _demo_require_open()
    if err is not None:
        return err
    cap, cap_err = _demo_require_capability()
    if cap_err is not None:
        return cap_err
    run = None
    try:
        run = demo_store.get_run_for_session(cap["id"], session_id)
    except Exception:
        app.logger.warning("Demo run 会话绑定读取失败", exc_info=True)
        return _denied()
    if run is None:
        return _denied()
    accepted_at = run.get("accepted_at")
    if not accepted_at or (float(accepted_at) + DEMO_SESSION_RECONNECT_SECONDS
                           < time.time()):
        return (jsonify(error="Demo AI 会话重连窗口已过（accepted_at + 1 小时）",
                        code="session_reconnect_expired"), 410)
    return None


@app.route("/api/auth/info")
def api_auth_info():
    """返回认证状态、effective subject 与真实 actor（预览态下二者分离）。

    顶层 username/role/user_id 是 **effective subject**（预览中为被预览用户），
    供前端模块可见性与切片列表与 current_identity 对齐。``actor`` 永远是真实
    登录管理员；``preview`` 为预览态快照（无预览则为 null）。未登录时顶层
    role 仍为 session 原值（None），不归一 owner。
    """
    actor_username = session.get("auth_user")
    actor_role = session.get("role")
    actor_user_id = session.get("user_id")
    actor = {
        "username": actor_username,
        "role": actor_role,
        "user_id": actor_user_id,
    }
    subject = _preview_subject() if AUTH_ENABLED else None
    if subject is not None:
        pv = _preview_state() or {}
        role = subject.get("role") or user_store.ROLE_USER
        user_id = subject.get("user_id") or ""
        # P1-3 收口：与登录 session 同口径——email_normalized → email →
        # login_id（display_name 是纯展示字段，绝不冒充身份）
        username = (subject.get("email_normalized") or subject.get("email")
                    or subject.get("login_id") or actor_username)
        preview = {
            "subject_user_id": user_id,
            "subject_role": role,
            "subject_username": username,
            "expires_at": float(pv.get("expires_at") or 0),
            "actor_user_id": actor_user_id,
        }
    else:
        role = actor_role
        user_id = actor_user_id
        username = actor_username
        preview = None
    return jsonify(
        auth_enabled=AUTH_ENABLED,
        username=username,
        role=role,
        user_id=user_id,
        actor=actor,
        preview=preview,
    )


@app.route("/healthz")
def api_healthz():
    """容器存活探针（Stage 4-3）。

    返回后端信息 + sidecar 可达性。sidecar 不可达**不**导致本端点失败
    （platform 角色无 sidecar 也健康）；"sidecar" 字段供监控区分降级状态。
    sidecar 可达性探测 2s 超时（比代理端点更短，避免探针拖慢健康检查）。
    """
    sidecar_status = _sidecar_health_status()
    return jsonify(
        ok=True,
        backend=getattr(share_store, "STORAGE_BACKEND", "json"),
        sidecar=sidecar_status,
    )


@app.route("/favicon.ico")
def favicon():
    """空 favicon（204，D1 修复 2026-09-10）。

    浏览器加载任意页面后都会自动 GET /favicon.ico（带 Lax cookie）。此前
    本应用没有该路由，Flask 对未匹配路由仍跑 before_request → 鉴权闸把
    pending 用户的激活会话当未登录拒绝。现按非敏感公开路径返回 204 空
    body（可短缓存），配合各页面 <link rel="icon" href="data:,"> 不再
    产生该请求。
    """
    resp = Response(status=204)
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


# --------------------------------------------------------------------------- #
# P0 协议底座（docs/agent-plan-20260921-registration-consent-research.md §3.2）：
# 公开只读、版本化不可变的协议页面。
#
#   - GET /legal/<slug>           当前内置版本页面（no-cache，可重新验证）；
#   - GET /legal/<slug>/<version> 版本化不可变链接（长缓存 immutable）；
#   - 任一 URL 加 ?download=1     以 attachment 下载 Markdown 原文。
#
# 页面由 agreement_store 的内置版本化文稿直接渲染：**不查库、不创建用户、
# 不记录同意**；链接绝不拼接任何验证 token；响应带 Referrer-Policy:
# no-referrer（从验证邮件页打开协议不泄露来源 URL）。当前内置文稿为
# 2026-09-21-v4 草稿（数据使用规则说明），页面明确标注草稿状态。
# --------------------------------------------------------------------------- #
@app.route("/legal/<slug>", methods=["GET"])
@app.route("/legal/<slug>/<version>", methods=["GET"])
def legal_document(slug, version=None):
    doc = agreement_store.get_builtin_document(slug, version)
    if doc is None:
        abort(404)
    permalink = "/legal/%s/%s" % (doc["slug"], doc["version"])
    if (request.args.get("download") or "").strip() == "1":
        resp = Response(doc["content"], mimetype="text/markdown; charset=utf-8")
        resp.headers["Content-Disposition"] = (
            "attachment; filename=\"%s_%s.md\"" % (doc["slug"], doc["version"]))
    else:
        resp = make_response(render_template(
            "legal_doc.html", doc=doc, permalink=permalink,
            # canonical=版本化不可变链接（public_pages 口径）：/legal/<slug>
            # 当前版本页与带 query 的 HTML 请求都归一到该 permalink。
            canonical=_public_canonical_url(permalink),
            content_html=legal_render.render_markdown(doc["content"])))
    # 版本化链接内容不可变 → 长缓存；当前版本页可重新验证
    if version is None:
        resp.headers["Cache-Control"] = "no-cache"
    else:
        resp.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    # 不泄露来源（验证邮件页打开协议时不带 Referer）
    resp.headers["Referrer-Policy"] = "no-referrer"
    return resp


def _sidecar_health_status(timeout=2.0):
    """探测 sidecar /healthz，返回 "reachable" / "unreachable" / "unknown"。

    reachable    sidecar /healthz 200。
    unreachable  连接错误/超时/非 200。
    unknown      AI_SIDECAR_URL 未配置（理论上不会发生，防御）。
    """
    url = AI_SIDECAR_URL.rstrip("/") + "/healthz"
    try:
        r = requests.get(url, timeout=timeout)
    except (requests.ConnectionError, requests.Timeout):
        return "unreachable"
    if r.status_code == 200:
        return "reachable"
    return "unreachable"


def _require_owner():
    """owner-only 守卫：**actor** 角色非 owner 返回 403 JSON。

    仅 owner（部署者 / superadmin）可管理用户。未登录或 user/guest 一律 403
    （资源级鉴权矩阵是下一节点的事，这里只做身份级 owner 判定）。
    S4：查 actor_identity()（真实管理员），**永不被身份预览骗过**——预览态下
    管理员仍可过本守卫（如 GET 管理端点），subject 的 role 无关。
    """
    if actor_identity()["role"] == user_store.ROLE_OWNER:
        return None
    return jsonify(error="需要 owner 权限"), 403


# =========================================================================== #
# Stage 3a-2a：身份与资源级鉴权矩阵（docs §5.1.1）
#
# 读隔离模型（review P0 2026-09-05）× 升级 B 收紧（R5）：读判定按主体分域
# ——_subject_can_view_slide 分发：
#   user  = 自己的 ∪ public ∪ 认领(view) ∪ 显式授权（语义不变）；
#   owner = 自己的 ∪ 显式添加（slide_view_grants 且资产生代匹配）——public
#           与 claimed 不再自动计入；「看全部」唯一出口是管理台
#           /api/admin/v1/slides/*（inventory + visibility）。
# 写路径（升级 B）：can_annotate_slide 的认证 owner 同样按收录集合（未添加
# 他人切片不可读写）；can_delete_slide / 项目管理写 / 分享撤销 / 标注删除
# 的 owner 语义不变。
#
# AUTH_ENABLED=False（内网模式）时 session 无 role 是合法路径，current_identity
# 归一 role=owner：本地免认证开发态 owner 无稳定 user_id → 读/写全量（
# §5.4 明确例外，不存在「其他用户」可隔离）。稳定 owner 账户部署中，owner
# 看自己上传的切片不受影响，他人切片需系统管理显式添加。
# AUTH_ENABLED=True 时 session 无 role 只可能是异常（session 写入 bug /
# 序列化问题）→ 降级 ROLE_GUEST（最低权限）+ 节流 warning，不再默认最高
# 权限（fix 2026-09-11 P1；登录/激活等合法路径均写入 role，见
# _require_auth 对 auth_user 的硬校验）。
#
# user：上传/维护自己的图库；查看 = 自己的 + 公开 + 受邀（认领过 active
#       share）+ 显式授权；标注 = 自己的 + 协作切片；删除标注 = 仅本人创建；
#       创建分享 = 仅自己的切片。
# guest：不能上传/维护图库；标注按分享权限走 /s/* 流程（share_server）；不能创建分享。
# =========================================================================== #
# --------------------------------------------------------------------------- #
# S4 管理员只读身份预览（HistoPilot/docs/session-isolation-fix-plan.md §3）：
# actor / subject **非破坏分离**——不改 current_identity() 的返回形状（全平台
# 直接读 ident["role"]/ident["user_id"]），而是：
#   - current_identity() 保持扁平，返回 **effective subject**（预览态 = 被预览
#     用户；否则 = 本人）。权限矩阵 / 切片可见性 / AI 会话过滤继续读它。
#   - actor_identity() 返回真实管理员 actor（永不被预览替换）。
#   - _require_owner() 查 actor（预览态不能骗过 owner 守卫）。
#   - _audit 写 actor，预览态附 subject_user_id / preview 字段。
# 预览只读：_preview_write_guard（before_request，挂在 CSRF 之后）拦截预览态的
# 一切非安全方法（白名单仅退出预览）；subject 每请求重新解析，禁用/删除/TTL
# 过期即自动退出。AUTH_ENABLED=False 无预览（start 明确 400），不变量不破。
# --------------------------------------------------------------------------- #
#: session 内预览态键：{subject_user_id, expires_at, actor_user_id}（S4 §3.4）
PREVIEW_SESSION_KEY = "preview"
#: 预览 TTL 秒（默认 15 分钟；env 可调）
PREVIEW_TTL_SECONDS = int(
    os.environ.get("PREVIEW_TTL_SECONDS") or 15 * 60)


#: session role 缺失告警节流（fix 2026-09-11 P1）：AUTH_ENABLED=True 下
#: session 无 role 只可能是异常（写入 bug / 序列化问题），降级 GUEST 时记
#: 一条节流 warning（同类一条/5 分钟，惯例同 _warn_site_stats_throttled）；
#: 只记 session 是否有 user_id，绝不记 session 内容本身。
_ROLE_MISSING_WARN_INTERVAL_SECONDS = 300
_role_missing_warn_last = {"ts": None}  # None = 从未记过（首条必发，不被节流）


def _reset_role_missing_warn_state():
    """测试辅助：清空 role 缺失告警节流状态（下一条告警必然发出）。"""
    _role_missing_warn_last["ts"] = None


def actor_identity():
    """真实登录身份（flat {"role","user_id"}，**永不被预览替换**）。

    归一契约与 current_identity 一致：session 无 role 时按 AUTH 模式区分
    （fix 2026-09-11 P1，不再无条件「保守放行」owner）——AUTH_ENABLED=False
    （内网免认证）为合法路径，归一 role=owner；AUTH_ENABLED=True 下 role
    缺失只可能是异常 → 降级 ROLE_GUEST（最低权限）+ 节流 warning。
    预览态下 session 仍是管理员的——本函数即「管理员本人」视角。
    """
    role = session.get("role")
    if role is None:
        if AUTH_ENABLED:
            now = time.monotonic()
            last = _role_missing_warn_last["ts"]
            if last is None or (now - last) >= \
                    _ROLE_MISSING_WARN_INTERVAL_SECONDS:
                _role_missing_warn_last["ts"] = now
                app.logger.warning(
                    "[auth] session 缺少 role（AUTH_ENABLED=True，合法登录/"
                    "激活路径均应写入；只可能是 session 异常）——按最低权限"
                    " %s 处理（session 有 user_id=%s；节流窗口内同类仅记本条）",
                    user_store.ROLE_GUEST, bool(session.get("user_id")))
            role = user_store.ROLE_GUEST
        else:
            role = user_store.ROLE_OWNER
    return {"role": role, "user_id": session.get("user_id")}


def _preview_state():
    """读 session 内预览态 dict；无/形态不对返回 None。"""
    pv = session.get(PREVIEW_SESSION_KEY)
    return pv if isinstance(pv, dict) else None


def _quit_preview():
    session.pop(PREVIEW_SESSION_KEY, None)


def _preview_subject():
    """解析当前预览 subject 用户行；无效自动退出预览并返回 None。

    每次调用**重新回查 user_store**（§3.4 不缓存）；TTL 过期、subject 不存在、
    已禁用、结构非法 → 清掉 session 预览态（自动退出），回到 actor 本人身份。
    """
    pv = _preview_state()
    if pv is None:
        return None
    try:
        expires_at = float(pv.get("expires_at") or 0)
    except (TypeError, ValueError):
        _quit_preview()
        return None
    if expires_at <= time.time():
        _quit_preview()  # TTL 过期自动退出（§3.4）
        return None
    subject_id = pv.get("subject_user_id") or ""
    if not subject_id:
        _quit_preview()
        return None
    try:
        user = user_store.get_user(subject_id)
    except Exception:
        app.logger.exception("preview subject lookup failed: %s", subject_id)
        _quit_preview()
        return None
    if not user or user.get("disabled"):
        _quit_preview()  # 禁用/删除用户不可作 subject（§3.4）
        return None
    return user


def _preview_active():
    """预览态是否生效（subject 有效）。写 guard / 审计共用。"""
    return _preview_subject() is not None


def current_identity():
    """返回 {"role","user_id"}（**effective subject**；S4 预览态 = 被预览用户）。

    session 无 role 的归一见 actor_identity（fix 2026-09-11 P1，按 AUTH 模式
    区分）：AUTH_ENABLED=False（内网模式）→ owner 免认证语义不动；
    AUTH_ENABLED=True → ROLE_GUEST（最低权限）+ 节流 warning——该模式下
    未登录请求已被 _require_auth 在 before_request 拦截为 401，不会走到
    资源级判定，此处无 role 只可能是 session 异常，不再保守放行。

    预览态（session[preview] 有效）→ 返回 subject 的 role/user_id：can_view /
    can_annotate / 切片列表 / AI 会话过滤等继续读本函数，预览下自动按 subject
    生效（§3.2 非破坏式——调用方零改动）。
    """
    subject = _preview_subject()
    if subject is not None:
        return {"role": subject.get("role") or user_store.ROLE_USER,
                "user_id": subject.get("user_id") or ""}
    return actor_identity()


def _is_owner():
    return current_identity()["role"] == user_store.ROLE_OWNER


def _current_uid():
    return current_identity()["user_id"]


def _slide_owner(name):
    """切片归属 owner_user_id（来自 slide_meta）；无记录返回 None。"""
    meta = share_store.get_slide_meta_full(name)
    return meta.get("owner_user_id") if meta else None


def _slide_is_public(name):
    meta = share_store.get_slide_meta_full(name)
    return bool(meta.get("public")) if meta else False


def _claimed_slides(uid, permission=None):
    """user 认领的 active share 中的切片名集合（协作切片）。

    permission 若给出，只计入 grant 含该权限的切片（view / annotate）。
    """
    if not uid:
        return set()
    return share_store.claimed_active_slides_for_user(uid, permission=permission)


def can_upload(slide=None):
    """owner/user 可上传；guest 不可。

    Stage 3c-2（docs §v1.5）：归档项目内的切片只读，owner 亦不可写——上传/覆盖
    指定切片时若属于归档项目返回 False（解除归档才可）。
    """
    if current_identity()["role"] not in (user_store.ROLE_OWNER, user_store.ROLE_USER):
        return False
    if slide and slide in _archived_slide_names():
        return False
    return True


def can_view_slide(name):
    """读隔离模型（review P0 2026-09-05）× 升级 B 收紧（R5）。

    owner 不再全量短路——与 user 同一主体判定（_subject_can_view_slide）。
    owner 的「看全部」唯一出口是管理台 /api/admin/v1/slides/inventory（显式
    管理）。例外：本地免认证单租户态（AUTH_ENABLED=False，owner 无 user_id）
    读恢复全量——该形态下不存在「其他用户」可隔离，维持读隔离前的既有不变
    量（本地开发/测试依赖）；认证部署的 owner 隔离语义不受影响。
    """
    ident = current_identity()
    return _subject_can_view_slide(ident["role"], ident["user_id"], name)


def _user_can_view_slide(uid, name):
    """普通 user 的 view 主体判定（无 session 上下文，供 dispatch 复用）。

    user 集合：本人的 ∪ public ∪ 认领(view) ∪ 显式授权（普通 user 语义在
    升级 B 中不变；owner 集合见 _owner_can_view_slide）。
    """
    if not uid:
        return False
    if _slide_owner(name) == uid:
        return True
    if _slide_is_public(name):
        return True
    if name in _claimed_slides(uid, permission=share_store.PERMISSION_VIEW):
        return True
    if name in share_store.slide_view_grants_for_user(uid):
        return True
    return False


def _owner_can_view_slide(uid, name):
    """认证 owner 的 view 集合（升级 B R5 收紧）。

    集合 = 本人拥有 ∪ 本账号显式添加且仍有效（slide_view_grants，且资产生
    代匹配）。public 与 claimed 不再自动计入——其他用户新增上传、公开标志
    变化、新建项目都不能自动扩大 owner 的普通工作区（原文档 §5.1）。
    """
    if not uid:
        return False
    if _slide_owner(name) == uid:
        return True
    return name in share_store.slide_view_grants_for_user(uid)


def _subject_can_view_slide(role, uid, name):
    """主体级 view 判定（role/user_id 显式传入，owner × user 集合分域）。

    - 本地免认证单租户态（owner 且无 uid）→ True（升级 B §5.4 明确例外）；
    - 认证 owner → _owner_can_view_slide（本人 ∪ 显式添加）；
    - 其余（user/guest）→ _user_can_view_slide（guest 无 uid 恒 False）。
    """
    if role == user_store.ROLE_OWNER:
        if not uid:
            return True
        return _owner_can_view_slide(uid, name)
    return _user_can_view_slide(uid, name)


def can_delete_slide(name):
    """owner 任意；user 仅自己的。"""
    ident = current_identity()
    if ident["role"] == user_store.ROLE_OWNER:
        return True
    return _slide_owner(name) == ident["user_id"]


def can_annotate_slide(name):
    """标注/AI 写能力判定（升级 B 收紧 owner 语义）。

    升级 B：认证 owner 未添加他人切片不可读写——annotate 集合同 view 集合
    （本人 ∪ 显式添加；授权切片上 owner 既有标注/AI 权限生效，归档项目仍
    只读）。本地免认证单租户态（owner 无 user_id）保持全量（§5.4 例外）。
    """
    if name in _archived_slide_names():
        return False
    ident = current_identity()
    return _subject_can_annotate_slide(ident["role"], ident["user_id"], name)


def _user_can_annotate_slide(uid, name):
    """can_annotate_slide 的 user 主体判定（归档检查由调用方先行，供 dispatch 复用）。"""
    if not uid:
        return False
    if _slide_owner(name) == uid:
        return True
    if name in _claimed_slides(uid, permission=share_store.PERMISSION_ANNOTATE):
        return True
    return False


def _subject_can_annotate_slide(role, uid, name):
    """主体级 annotate 判定（role/user_id 显式传入；归档检查由调用方先行）。

    认证 owner：本人 ∪ 显式添加（_owner_can_view_slide 同集合——管理台显式
    添加后 owner 在该切片的标注/AI 工具生效；未添加不可读写）。user 语义
    不变；本地免认证单租户态（owner 且无 uid）→ True。
    """
    if role == user_store.ROLE_OWNER:
        if not uid:
            return True
        return _owner_can_view_slide(uid, name)
    return _user_can_annotate_slide(uid, name)


def _slide_id_archived(slide_id):
    """slide_id 是否在归档项目内（P2：project_slides 双写后的归档只读判定）。"""
    if not slide_id:
        return False
    try:
        conn = pg_store.connect()
    except Exception:  # noqa: BLE001 - 查询失败按未归档（与名通道容错一致）
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM project_slides ps JOIN projects p "
                "ON p.project_id = ps.project_id "
                "WHERE ps.slide_id=%s AND p.archived LIMIT 1", (slide_id,))
            return cur.fetchone() is not None
    except Exception:  # noqa: BLE001
        return False
    finally:
        conn.close()


def _desc_can_annotate(desc):
    """can_annotate_slide 的 descriptor 形态（P2，合同 §3.1：判定按 ID）。

    - 有 legacy 名（行/文件历史形态）：走既有名通道（归档集合/收录判定
      语义不变）；
    - id_bundle（无冻结别名）：归档按 slide_id；收录 = owner/public/显式
      授权（authorize_read session 同集）∪ annotate 档 share 成员。
    """
    if desc is None:
        return False
    name = desc.legacy_filename
    if name:
        return can_annotate_slide(name)
    if _slide_id_archived(desc.slide_id):
        return False
    ident = current_identity()
    role, uid = ident.get("role"), ident.get("user_id")
    if role == user_store.ROLE_OWNER and not uid:
        return True  # 本地免认证单租户态
    if not _authorize_or_deny(desc, channel="session"):
        return False
    if not uid:
        return False
    if desc.owner_user_id and uid == desc.owner_user_id:
        return True
    return slide_store.has_share_permission(
        uid, desc.slide_id, share_store.PERMISSION_ANNOTATE)


# --------------------------------------------------------------------------- #
# 用户权限 → capability requiredPermissions 映射表（插件能力层 docs §6.1）
#
# requiredPermissions 用的是插件 permissions 枚举，而用户侧权限按 slide 角色
# 判定。网关注入过滤（/api/ai/run）与 dispatch 权限检查必须共用同一张映射——
# 落为下面的共享常量与 _subject_slide_permissions，避免两处实现漂移：
#   - 用户对 slide 有 view 权限 → 满足 slide:metadata:read / slide:region:read /
#     annotation:read；
#   - annotate 权限 → 另加 annotation:write。
# --------------------------------------------------------------------------- #
_CAPABILITY_VIEW_GRANTS = frozenset((
    "slide:metadata:read",
    "slide:region:read",
    "annotation:read",
))
_CAPABILITY_ANNOTATE_GRANTS = frozenset(("annotation:write",))


def _subject_slide_permissions(role, user_id, slide):
    """主体（role/user_id 显式传入，不依赖 session）对 slide 的权限集合。

    读隔离模型（review P0 2026-09-05）× 升级 B 收紧：owner 与 user 的 view
    能力按 _subject_can_view_slide 分域判定（owner = 本人 ∪ 显式添加）——
    否则插件 dispatch 会成为绕过收录关系的旁路。annotation:write 同样按
    收录集合授予（升级 B：未添加他人切片不可读写；授权切片上 owner 既有
    标注/AI 权限生效，归档切片除外）。user → view/annotate 判定映射
    （§6.1 表）。例外：本地免认证单租户态（owner 且无 user_id）恢复全量
    4 项（can_view_slide 同款口径）。
    """
    if role == user_store.ROLE_OWNER and not user_id:
        if slide in _archived_slide_names():
            return set(_CAPABILITY_VIEW_GRANTS)
        return set(_CAPABILITY_VIEW_GRANTS) | set(_CAPABILITY_ANNOTATE_GRANTS)
    perms = set()
    if _subject_can_view_slide(role, user_id, slide):
        perms |= _CAPABILITY_VIEW_GRANTS
    if (slide not in _archived_slide_names()
            and _subject_can_annotate_slide(role, user_id, slide)):
        perms |= _CAPABILITY_ANNOTATE_GRANTS
    return perms


def _subject_can_annotate_desc(role, uid, desc):
    """claims 主体的 descriptor 形态 annotate 判定（归档检查由调用方先行）。

    与名通道 ``_subject_can_annotate_slide`` 完全同语义的 ID 权威版：
    认证 owner = 本人 ∪ 显式添加（authorize_read allow_public/allow_share=
    False，升级 B R5）；user = slides 行属主 ∪ annotate 档 share 成员；
    本地免认证单租户态（owner 无 uid）→ True。
    """
    if desc is None:
        return False
    if role == user_store.ROLE_OWNER:
        if not uid:
            return True
        return slide_store.authorize_read(desc, actor_user_id=uid,
                                          allow_public=False, allow_share=False)
    if not uid:
        return False
    if desc.owner_user_id and uid == desc.owner_user_id:
        return True
    return slide_store.has_share_permission(uid, desc.slide_id,
                                            share_store.PERMISSION_ANNOTATE)


def _subject_slide_permissions_desc(role, uid, desc):
    """``_subject_slide_permissions`` 的 **slide_id 权威**形态（P2）。

    id_bundle 行（全部新上传）``legacy_filename`` 恒 NULL——名通道
    （share_store.get_slide_meta_full ``WHERE legacy_filename=%s``）对
    original_filename 恒 miss，且 original_filename 跨用户可重名、仅为展示
    字段，不能作判定键。本函数按 slides 行（owner/public）+ authorize_read
    + share 成员关系判定，授予集合与名通道同一常量（_CAPABILITY_*_GRANTS）、
    同一 §6.1 语义；desc 解析不到（None）→ 空集（fail-closed，无「名找不到
    就放行」回退）。
    """
    if desc is None:
        return set()
    if role == user_store.ROLE_OWNER and not uid:
        if _slide_id_archived(desc.slide_id):
            return set(_CAPABILITY_VIEW_GRANTS)
        return set(_CAPABILITY_VIEW_GRANTS) | set(_CAPABILITY_ANNOTATE_GRANTS)
    perms = set()
    if _ai_session_subject_can_view(role, uid, desc):
        perms |= _CAPABILITY_VIEW_GRANTS
    if (not _slide_id_archived(desc.slide_id)
            and _subject_can_annotate_desc(role, uid, desc)):
        perms |= _CAPABILITY_ANNOTATE_GRANTS
    return perms


def can_delete_annotation(roi):
    """owner 任意；否则仅本人创建（roi.owner_user_id == 自己）。"""
    ident = current_identity()
    if ident["role"] == user_store.ROLE_OWNER:
        return True
    return roi.get("owner_user_id") == ident["user_id"]


def can_manage_share(slides):
    """创建分享：owner 任意；user 仅当全部切片归自己。"""
    ident = current_identity()
    if ident["role"] == user_store.ROLE_OWNER:
        return True
    uid = ident["user_id"]
    return all(_slide_owner(s) == uid for s in slides)


def _ready_slide_descs():
    """DB 资产查询：asset_state='ready' 的全部 descriptor（P1-B2 列表源）。

    列表源改 DB（合同 §4：DB asset_state='ready' 是唯一可见性开关——
    「目录扫描=切片」退役）；入口经 resolve_descriptor_path（objects/<
    slide_id>/data.<ext>）stat，文件消失不列出（旧行为）。
    P6 运行时退役：legacy 布局行在 resolver 即 ValueError——fail-closed 不
    列出（待迁移/隔离不可见；visible_ready_slide_ids 的 SQL 侧同口径）。
    """
    try:
        descs = slide_store.list_ready_descriptors()
    except Exception:
        app.logger.warning("slides 资产列表读取失败（fail-closed 空集）",
                           exc_info=True)
        return []
    out = []
    for desc in descs:
        try:
            if not slide_storage.resolve_descriptor_path(
                    desc, root=UPLOAD_DIR).is_file():
                continue  # 入口文件消失：不列出（旧行为）
        except Exception:
            continue  # 路径解析失败（legacy 布局/containment 等）：fail-closed 不列出
        out.append(desc)
    return out


def _visible_slide_descs():
    """当前身份可见的 ready 切片 descriptor 列表。

    P2（合同 §3.5）：P1-B2 遗留的逐行 authorize_read N+1 收敛——判定参数
    与 ``_authorize_or_deny(channel="session")`` 完全同源（本地免认证
    owner=admin 全量；认证 owner=allow_public/allow_share=False；user=默认），
    集合一次算出（slide_store.visible_ready_slide_ids：ready 行扫描 + 授权
    集合两查，常量次），再对 descriptor 列表做内存判定。
    """
    ident = current_identity()
    if not ident.get("user_id") and ident.get("role") != user_store.ROLE_OWNER:
        return []  # guest（无 uid 非本地 owner）：可见集为空（旧口径）
    if ident.get("role") == user_store.ROLE_OWNER and not ident.get("user_id"):
        visible_ids = slide_store.visible_ready_slide_ids(
            actor_role=slide_store.ROLE_ADMIN)
    elif ident.get("role") == user_store.ROLE_OWNER:
        visible_ids = slide_store.visible_ready_slide_ids(
            actor_user_id=ident["user_id"],
            allow_public=False, allow_share=False)
    else:
        visible_ids = slide_store.visible_ready_slide_ids(
            actor_user_id=ident["user_id"])
    return [d for d in _ready_slide_descs() if d.slide_id in visible_ids]


def _visible_slide_names():
    """当前身份可见的切片引用集合（升级 B R5：owner × user 集合分域）。

    user 可见集 = 自己上传的 ∪ public ∪ 认领(view 级 claim，经 share_slides
    ID 关系) ∪ 显式授权（slide_view_grants，slide_id 级）——普通 user 语义
    不变。认证 owner 可见集收紧为本人拥有 ∪ 本账号显式添加且资产生代有效
    （public 与 claimed 不再自动计入；原文档 §5.1）。owner 不再全量短路
    （review P0 2026-09-05）；无主切片（owner_user_id 为空）且非 public 对
    所有身份默认不可见，经管理台显式授权后恢复可见（孤儿切片仍可管理）。
    例外：本地免认证单租户态（owner 无 user_id）恢复全量（不存在「其他
    用户」可隔离）。

    P1-B2：列表源改 DB（asset_state='ready' 的 slides 行 + 入口文件 stat），
    目录上无 slides 行的文件不再出现（「外部程序手工放文件不自动注册」）。
    P3（合同 §4）：返回集合对 id_bundle 行改为 **{slide_id} 集合语义**——
    legacy 行出 legacy 名、id_bundle 行（legacy_filename=NULL）出 slide_id。
    消费方（分享/项目/标注过滤）按「行的 slide_id 有值走 ID、无值按名」分支；
    本集合只做成员判定，不做反解。
    """
    return {(d.legacy_filename or d.slide_id) for d in _visible_slide_descs()}


def _visible_slide_keys():
    """可见集的双键视图（P3 合同 §4 消费方核对用）：(slide_id 集, legacy 名集)。

    行级过滤（rois/comments 等带双列的引用行）按「行有 slide_id → 查 ID 集；
    NULL-ID 历史行 → 查名集」分支——id_bundle 资产只有 ID 键、legacy 资产的
    集合成员键是 legacy_filename（名），两集分开判定不互串。
    """
    descs = _visible_slide_descs()
    return ({d.slide_id for d in descs},
            {d.legacy_filename for d in descs if d.legacy_filename})


def _can_access_project(pid):
    """owner 任意；user 仅自己 owner_user_id 的项目（不存在视为无权）。

    项目**写/管理**路径（更新/增删切片/删除/归档）保持 owner 语义不变
    （本次只做读隔离）；读路径见 _can_read_project。
    """
    if _is_owner():
        return True
    proj = share_store.get_project(pid)
    if proj is None:
        return False
    return proj.get("owner_user_id") == _current_uid()


def _can_read_project(pid):
    """项目**读**访问（详情/标注投影）：owner 与 user 同一创建者口径。

    review P0 2026-09-05：项目详情含项目内切片的标注摘要，owner 全量读
    会经此旁路泄露他人切片的标注——读路径与切片可见集同模型。管理出口走
    /api/admin/*（inventory 是唯一「看全部」）。
    """
    proj = share_store.get_project(pid)
    if proj is None:
        return False
    return proj.get("owner_user_id") == _current_uid()


def _denied(msg="无权访问"):
    """统一的资源级 403 响应（不区分 404/403 以免泄露存在性，简单优先）。"""
    return jsonify(error=msg), 403


def _audit(action, target_type=None, target_id=None, slide=None, detail=None,
           slide_id=None):
    """best-effort 记一条协作审计事件（Stage 3c-2）。

    record_audit 自身吞写失败，这里不额外 try；在**业务写完成后**、独立于业务锁
    调用（不嵌套在 store 锁内），避免死锁。actor 取当前身份；AUTH_ENABLED=False
    时 role 归一 owner。

    S4：actor 永远是 actor_identity()（真实管理员，不被预览替换）；预览态下
    business 操作按 subject 生效，故在 detail 里附 ``subject_user_id`` 与
    ``preview`` 字段（record_audit 签名不变，subject 经 detail 落库——json detail
    dict / PG detail jsonb 同构）。
    P2（合同 §3.4/R-14）：``slide_id`` 与名称快照 ``slide`` 双写（detail 里的
    slide_id 先例保留兼容）。
    """
    ident = actor_identity()
    detail = dict(detail) if isinstance(detail, dict) else {}
    subject = _preview_subject()
    if subject is not None:
        detail.setdefault("subject_user_id", subject.get("user_id"))
        detail.setdefault("preview", True)
    if slide_id is not None:
        detail.setdefault("slide_id", slide_id)
    share_store.record_audit(
        action=action,
        actor_user_id=ident.get("user_id"),
        actor_role=ident.get("role"),
        target_type=target_type,
        target_id=target_id,
        slide=slide,
        detail=detail,
        slide_id=slide_id,
    )


def _archived_slide_names():
    """属于归档项目的切片名集合（归档只读判定，docs §v1.5）。"""
    return share_store.archived_slide_names()


# --------------------------------------------------------------------------- #
# owner 用户管理（Stage 3a 身份基础；P0-B 起注册模式为 registration_mode）
# --------------------------------------------------------------------------- #
# 注册模式（docs §4.1，P0-B）：settings_store.get_registration_mode 为运行时权威
# （PG platform_settings；旧布尔 registration_open 开关已随 0032/Wave2-Compat
# 删除，mode 键缺行直接降级 closed，不放大注册面）。模式生效还需通过 §3.2 末段的前置
# 条件闸（HTTPS / Secure Cookie / postgres），未满足一律按 closed 处理并告警。
# --------------------------------------------------------------------------- #
def _registration_mode_stored() -> str:
    """存储层注册模式（closed|invite_only|public）；读取失败按 closed 处理。"""
    try:
        return settings_store.get_registration_mode()
    except Exception:
        app.logger.exception("读取 registration_mode 失败，按 closed 处理")
        return "closed"


def _registration_precondition_failures(environ=None, mode=None) -> list:
    """开放注册形态生效的前置条件（docs §3.2 末段，fail-closed）。

    P1-2（review）：判定下沉为 registration_store.registration_mode_
    precondition_failures——app 层与 mail worker 共用同一实现，不再复制逻辑。
    语义（详见共享实现 docstring）：
      invite_only / email_verify_invite_activation 要求 PUBLIC_BASE_URL https、
      ADMIN_SESSION_COOKIE_SECURE、postgres 后端；email_verify 形态额外要求
      邮件通道已配置、载荷加密密钥可用、验证 token 哈希盐非默认。
    """
    return registration_store.registration_mode_precondition_failures(
        environ, mode=mode)


_registration_gate_warned = {"flag": False}

#: 需要 fail-closed 前置闸的开放注册形态（public 原样透传给路由层统一 503）；
#: P1-2 起与共享判定同源（registration_store.REGISTRATION_GATED_MODES）
_REGISTRATION_GATED_MODES = registration_store.REGISTRATION_GATED_MODES


def _effective_registration_mode() -> str:
    """生效注册模式：存储值 × 前置条件闸（未满足降级 closed，每进程告警一次）。

    P1-2（review）：核心判定下沉为 registration_store 共享纯函数——前置条件
    计算经 :func:`_registration_precondition_failures` 委托
    ``registration_store.registration_mode_precondition_failures``，worker
    drain 前置走同一共享实现的组合入口
    ``registration_store.resolve_effective_registration_mode``（worker 绝不
    import Flask app）。本包装只保留 app 层的存储值读取与「降级每进程告警
    一次」行为。降级对象为全部开放形态（invite_only 与 I 线的
    email_verify_invite_activation；后者还叠加邮件通道/载荷密钥/哈希盐前
    置）；P1 起 ``public`` 同为开放形态：env 前置之外叠加**双协议文稿发
    布检查**（§4.1：缺当前发布文稿时不能把 public 宣称为可注册），任一
    缺失降级 closed。
    """
    mode = _registration_mode_stored()
    if mode not in _REGISTRATION_GATED_MODES:
        return mode
    failures = _registration_precondition_failures(mode=mode)
    if mode == registration_store.MODE_PUBLIC and not failures:
        failures = registration_store.public_document_failures()
    if failures:
        if not _registration_gate_warned["flag"]:
            _registration_gate_warned["flag"] = True
            app.logger.warning(
                "registration_mode=%r 但前置条件不满足（%s）：注册功能已"
                " fail-closed 降级为 closed（docs §3.2 末段 + I 线模式前置）",
                mode, "；".join(failures))
        return "closed"
    return mode


def _check_registration_preconditions_or_warn(environ=None):
    """启动期 fail-closed 检查：存储模式非 closed 但前置条件缺失 → 告警。

    处置策略选择「降级为 closed + 告警」而非拒绝启动：匿名只读 Demo 必须保持
    可用（docs §7「匿名只读 Demo 可继续运行，不受邀请注册开关影响」），整体
    SystemExit 会把 Demo 一并拖死；降级后 /register 仍为关闭态，安全语义等价。
    """
    try:
        mode = settings_store.get_registration_mode()
    except Exception:
        return  # json/dual 或存储不可达：读取路径自身 fail-closed 为 closed
    if mode not in _REGISTRATION_GATED_MODES:
        return  # closed 无需检查；public 本阶段路由统一拒绝
    failures = _registration_precondition_failures(environ, mode)
    if failures:
        app.logger.warning(
            "[startup] registration_mode=%r 前置条件不满足（%s）：注册功能"
            "将按 closed 运行；请先完成 TLS/Secure Cookie/邮件通道等配置，"
            "再由 owner 显式切换注册模式",
            mode, "；".join(failures))


# 启动期 fail-closed 检查（§3.2 末段；在定义处就近执行，模块加载即告警一次）
_check_registration_preconditions_or_warn()



# --------------------------------------------------------------------------- #
# 注册模式设置 service（批次 D §5.3：权威实现只此一份，旧路由与 Admin API v1
# 共同调用，不复制校验逻辑）。
# --------------------------------------------------------------------------- #
def _registration_settings_payload() -> dict:
    """注册模式 GET 权威 payload（存储值 × 前置条件闸 + 支持的模式词表）。

    2026-10-08 §4：词表只剩 closed/public（旧存储值 invite_only /
    email_verify_invite_activation 由 settings_store 读取按非法值 fail-closed
    处理为 closed）。
    """
    stored = _registration_mode_stored()
    failures = []
    if stored in _REGISTRATION_GATED_MODES:
        failures = _registration_precondition_failures(mode=stored)
        if stored == registration_store.MODE_PUBLIC and not failures:
            failures = registration_store.public_document_failures()
    effective = "closed" if failures else stored
    return {
        "mode": effective,
        "stored_mode": stored,
        "supported_modes": ["closed", "public"],
        "precondition_failures": failures,
        "registration_open": effective in _REGISTRATION_GATED_MODES,
        "backend": platform_features.current_backend(),
    }


def _set_registration_mode_service(mode, actor_user_id):
    """注册模式 PUT 权威实现（校验 + 写 settings_store + audit）。

    返回 ``(payload, None)`` 或 ``(None, (status, code, message))``——错误以
    三元组返回，由两个路由层（旧 /api/admin/settings/registration 与
    Admin API v1 /api/admin/v1/settings/registration）各自映射错误信封格式；
    校验/审计/前置条件语义在两入口完全一致（§5.3「不复制校验逻辑」）。
    P1 起接受 public：env 前置（TLS/Secure Cookie/邮件通道/载荷密钥/哈希
    盐/管理员通知邮箱）+ 双协议文稿发布检查，未满足 400
    registration_preconditions_failed（缺项文案不含凭据）。
    2026-10-08 §4：只接受 closed/public（邀请码形态退役）。
    """
    if mode not in ("closed", "public"):
        return None, (400, "invalid_request",
                      "mode 需为 closed / public")
    if mode in _REGISTRATION_GATED_MODES:
        failures = _registration_precondition_failures(mode=mode)
        if mode == registration_store.MODE_PUBLIC and not failures:
            failures = registration_store.public_document_failures()
        if failures:
            return None, (400, "registration_preconditions_failed",
                          "注册前置条件不满足：" + "；".join(failures))
    try:
        settings_store.set_registration_mode(mode, updated_by=actor_user_id)
    except ValueError as exc:
        return None, (400, "invalid_request", str(exc))
    _audit("registration.mode_update", target_type="platform_settings",
           target_id="registration_mode", detail={"mode": mode})
    return {"mode": mode}, None


# --------------------------------------------------------------------------- #
# S4 管理员只读身份预览：进入 / 退出（session-isolation-fix-plan §3.4）
#
# owner-only + 统一 CSRF（before_request，/api/* 只认 header）。进入时在
# session 记 preview={subject_user_id, expires_at, actor_user_id}；目标用户
# 每请求重新解析（禁用/删除即自动退出）；TTL 默认 15 分钟过期自动退出。
# start/stop 各记一条审计（actor + subject）。AUTH_ENABLED=False 下明确 400
# （无认证维度可预览，保持「无 preview、identity 归一 owner」不变量）。
# --------------------------------------------------------------------------- #
@app.route("/api/admin/preview/start", methods=["POST"])
def api_admin_preview_start():
    """进入只读身份预览。body: {user_id}。owner-only（查 actor）+ CSRF。

    - 目标用户必须存在且未禁用（禁用用户不可作 subject）→ 400；
    - AUTH_ENABLED=False → 400（预览以认证身份为前提）；
    - 幂等：重复 start 刷新 TTL（同 subject）或切换 subject（覆盖写）。
    - 审计 preview.start（actor + subject + TTL）。
    """
    if not AUTH_ENABLED:
        return jsonify(error="预览需要启用认证（AUTH_ENABLED）"), 400
    auth = _require_owner()
    if auth:
        return auth
    body = request.get_json(silent=True) or {}
    user_id = body.get("user_id")
    if not isinstance(user_id, str) or not user_id.strip():
        return jsonify(error="缺少 user_id 字段"), 400
    try:
        user = user_store.get_user(user_id.strip())
    except Exception:
        app.logger.exception("preview target lookup failed: %s", user_id)
        return jsonify(error="预览目标用户查询失败"), 500
    if user is None:
        return jsonify(error="用户不存在", code="subject_not_found"), 404
    if user.get("disabled"):
        return jsonify(error="禁用用户不可作为预览对象",
                       code="subject_disabled"), 400
    actor = actor_identity()
    expires_at = time.time() + PREVIEW_TTL_SECONDS
    session[PREVIEW_SESSION_KEY] = {
        "subject_user_id": user["user_id"],
        "expires_at": expires_at,
        "actor_user_id": actor.get("user_id") or "",
    }
    _audit("preview.start", target_type="user", target_id=user["user_id"],
           slide=None, detail={"subject_user_id": user["user_id"],
                               "subject_role": user.get("role") or "",
                               "expires_at": expires_at,
                               "ttl_seconds": PREVIEW_TTL_SECONDS})
    return jsonify(ok=True, preview={
        "subject_user_id": user["user_id"],
        "subject_role": user.get("role") or "",
        "expires_at": expires_at,
        "actor_user_id": actor.get("user_id") or "",
    })


@app.route("/api/admin/preview/stop", methods=["POST"])
def api_admin_preview_stop():
    """退出身份预览。owner-only（查 actor）+ CSRF；无预览时幂等成功。

    审计 preview.stop（actor；本次退出时的 subject 若可解析则一并记录）。
    """
    if not AUTH_ENABLED:
        return jsonify(error="预览需要启用认证（AUTH_ENABLED）"), 400
    auth = _require_owner()
    if auth:
        return auth
    pv = _preview_state() or {}
    stopped_subject = pv.get("subject_user_id") or ""
    _quit_preview()
    _audit("preview.stop", target_type="user", target_id=stopped_subject or None,
           slide=None, detail={"subject_user_id": stopped_subject or None})
    return jsonify(ok=True, preview=None)


# --------------------------------------------------------------------------- #
# owner AI 预算设置 / 用量（docs §4.2 / §9.2，PT-3）
#
# 仅 postgres 后端（json/dual 无跨 worker 一致预算，fail-closed 503）；owner
# only；全部写方法走统一 CSRF（before_request）。保存上限不清空已有用量；
# 「开启新预算周期」二次确认 + audit。
# --------------------------------------------------------------------------- #
#: 预算限制整数上限（防误填巨型值；次数/步数 sane bound）
_BUDGET_LIMIT_MAX = 1_000_000
#: owner 可经 PUT 修改的周期限制字段（与 budget_store._PERIOD_LIMIT_COLUMNS 对齐；
#: P0-B §3.7 新增 owner_reserved_turn_limit / user_pool_turn_limit）
_BUDGET_SETTINGS_FIELDS = (
    "platform_turn_limit", "demo_turn_limit", "user_turn_limit",
    "owner_reserved_turn_limit", "user_pool_turn_limit",
    "platform_task_max_steps", "own_task_max_steps_limit", "demo_task_max_steps",
    "demo_enabled", "demo_per_browser_limit", "demo_max_concurrency",
)
#: 允许 0 的限制字段（0=关闭该子池：Demo 子额度 / owner 保留 / user 共享池）
_BUDGET_ZEROABLE_FIELDS = frozenset((
    "demo_turn_limit", "owner_reserved_turn_limit", "user_pool_turn_limit"))


def _validate_budget_settings(body, current_limits):
    """校验 owner 提交的预算限制（docs §4.2 + §3.7 池隔离）。

    body 里只允许 _BUDGET_SETTINGS_FIELDS；次数/步数为有界非负整数
    （_BUDGET_ZEROABLE_FIELDS 允许 0=关闭子池，其余需 >0）；demo_enabled 布尔。
    关系校验（按「本次提交 + 未提交沿用现值」合并后判定）：
      1. user_pool_turn_limit + owner_reserved_turn_limit
         <= platform_turn_limit（周期口径的池拆分不越界）。
    注意：demo_turn_limit 自 0014 起为「每日（滚动 24h 窗口）」口径，与
    周期总量的累计口径不再可比，故不再参与「<= platform」及周期加和约束
    （每日上限可与周期总量任意相对大小；owner 保留池仍由服务端闸保证）。
    返回 (validated, None) 或 (None, err)。
    """
    unknown = set(body.keys()) - set(_BUDGET_SETTINGS_FIELDS)
    if unknown:
        return None, "未知字段：{}".format(", ".join(sorted(unknown)))
    validated = {}
    for field in _BUDGET_SETTINGS_FIELDS:
        if field not in body:
            continue
        raw = body.get(field)
        if field == "demo_enabled":
            if not isinstance(raw, bool):
                return None, "demo_enabled 需为布尔值"
            validated[field] = raw
            continue
        iv, err = _coerce_tuning_int(raw, field)
        if err:
            return None, err
        if field in _BUDGET_ZEROABLE_FIELDS:
            if iv < 0:
                return None, "{} 不可为负（0=关闭该子池）".format(field)
        elif iv <= 0:
            return None, "{} 需为正整数（> 0）".format(field)
        if iv > _BUDGET_LIMIT_MAX:
            return None, "{} 不可超过 {}".format(field, _BUDGET_LIMIT_MAX)
        validated[field] = iv
    # 关系校验（合并现值后；仅周期口径字段参与，demo_turn_limit 为每日口径除外）
    merged = dict(current_limits)
    merged.update(validated)
    platform = int(merged.get("platform_turn_limit") or 0)
    user_pool = int(merged.get("user_pool_turn_limit") or 0)
    owner_reserve = int(merged.get("owner_reserved_turn_limit") or 0)
    if user_pool + owner_reserve > platform:
        return None, (
            "子池之和（user_pool {} + owner_reserve {} = {}）不可超过"
            " platform_turn_limit（{}）".format(
                user_pool, owner_reserve,
                user_pool + owner_reserve, platform))
    return validated, None


# --------------------------------------------------------------------------- #
# owner Demo 目录管理（docs §5.1 / 任务 §3，PT-4）
#
# 只有 owner 能把切片加入/移出 Demo allowlist（public ≠ 互联网匿名可见）。
# 移出/删除联动 revoke_by_slide：capability 立即失效、未完成 run 标记终止，
# 并按返回的 terminated_runs 释放对应预算 reservation（已 consumed 拒绝释放）。
# --------------------------------------------------------------------------- #
def _release_budget_for_terminated_runs(terminated_runs):
    """按 request_id 向 HistoPilot 确认后 consume / release / 顺延。

    ``terminated_runs`` 为 revoke_by_slide 返回的 demo_runs 流水 dict 列表
    （含 demo_run_id / request_id / attempt；0026 起 run 与 capability 分离，
    不再回查 demo_sessions）。

    不得盲 release：sidecar 已接受但平台尚未 accept 时必须 consume，否则会
    退回已经产生模型成本的额度。found+已接受 → consume（run 侧已被 revoke
    置为 expired 终态，不重复流转）；missing → release；不可达或尚未接受 →
    顺延 reservation；预留行**读取失败** → 本轮跳过该 rid（下轮重试，
    fix 2026-09-11 P2：不得以 expected_attempt=None 绕过 attempt CAS）。
    """
    released = []
    for run in terminated_runs or []:
        rid = (run or {}).get("request_id")
        if not rid:
            continue
        try:
            budget_row = budget_store.get_reservation(rid)
        except Exception:
            # fix 2026-09-11（P2）：读取失败时若置 budget_row=None 继续，
            # consume/release 会以 expected_attempt=None 跳过乐观并发检查
            # （budget_store 只在 expected_attempt 非 None 时做 attempt CAS），
            # 可能消费/释放已被新尝试接替的预留行。对账由 ai-budget-reclaim
            # 守护线程周期执行，本轮跳过、下轮重试，天然安全。
            app.logger.warning(
                "terminated run 预算对账读取预留失败，本轮跳过：%s", rid,
                exc_info=True)
            continue
        budget_attempt = (budget_row or {}).get("attempt") if budget_row else None
        verdict, hp_sid, accepted = _histopilot_lookup_request(rid)
        if verdict == "found" and accepted:
            try:
                budget_store.consume(rid, hp_sid or "",
                                     expected_attempt=budget_attempt)
            except budget_store.ReservationAttemptConflict:
                try:
                    budget_store.extend_reservation(
                        rid, budget_store.DEFAULT_RESERVATION_TTL_SECONDS)
                except Exception:
                    pass
            except ValueError:
                pass  # 已 consumed
            except Exception:
                app.logger.warning("terminated run 预算 consume 失败：%s", rid,
                                   exc_info=True)
                try:
                    budget_store.extend_reservation(
                        rid, budget_store.DEFAULT_RESERVATION_TTL_SECONDS)
                except Exception:
                    pass
        elif verdict == "missing" or verdict == "abandoned":
            try:
                budget_store.release(rid, expected_attempt=budget_attempt)
                released.append(rid)
            except budget_store.ReservationAttemptConflict:
                try:
                    budget_store.extend_reservation(
                        rid, budget_store.DEFAULT_RESERVATION_TTL_SECONDS)
                except Exception:
                    pass
            except ValueError:
                pass  # 已 consumed：不退款
            except Exception:
                app.logger.warning("terminated run 预算释放失败：%s", rid,
                                   exc_info=True)
        else:
            # unavailable 或 found 但尚未接受：顺延，不得退款
            try:
                budget_store.extend_reservation(
                    rid, budget_store.DEFAULT_RESERVATION_TTL_SECONDS)
            except Exception:
                app.logger.warning("terminated run 预算顺延失败：%s", rid,
                                   exc_info=True)
    return released


def _revoke_demo_slide(slide_id):
    """切片下架/删除路径的 Demo 撤销联动：移除目录条目（若有）+ revoke + 释放预算。

    删除切片时目录条目一并移除（避免悬空条目指向已删除文件）；移出目录与
    删除切片共享 revoke_by_slide 语义（§9.3）。
    """
    try:
        result = demo_store.catalog_remove(slide_id)
        if result is not None:
            revoke = result["revoke"]
        else:
            # 不在目录内（不应发生——删除入口已查过）：仅按 slide 撤销防御
            revoke = demo_store.revoke_by_slide(slide_id)
    except Exception:
        app.logger.warning("Demo revoke_by_slide 失败：%s", slide_id, exc_info=True)
        return {"expired_capabilities": 0, "terminated_runs": [],
                "released_reservations": []}
    released = _release_budget_for_terminated_runs(
        revoke.get("terminated_runs"))
    return dict(revoke, released_reservations=released)


@app.route("/api/admin/demo-catalog", methods=["GET"])
def api_admin_demo_catalog_list():
    """列出 Demo 目录（owner）。"""
    auth = _require_owner()
    if auth:
        return auth
    items = []
    for entry in demo_store.catalog_list_ordered():
        item = dict(entry)
        item["name"] = demo_store.resolve_slide_filename(entry["slide_id"])
        items.append(item)
    return jsonify({"slides": items})


@app.route("/api/admin/demo-catalog", methods=["PUT"])
def api_admin_demo_catalog_put():
    """加入/更新 Demo 目录条目（owner，UPSERT）。

    body: {slide（文件名）, display_name?, description?, display_name_en?,
    description_en?, sort_order?, is_default?}。
    切片文件必须存在（allowlist 只接受真实入库切片）；首次加入时为其确保稳定
    slide_id。is_default=true 时设为默认 Demo 切片。
    双语（工单 B / 0057）：display_name/description 为中文/缺省语言，
    display_name_en/description_en 可选（缺省 None = 无译文，读取端回落）。
    """
    auth = _require_owner()
    if auth:
        return auth
    body = request.get_json(silent=True) or {}
    slide = body.get("slide")
    slide_id = body.get("slide_id")
    if slide_id is not None:
        # P3：id_bundle 资产无 legacy_filename——按 slide_id 收录（ready 门禁：
        # 未发布/已删除资产不进 Demo allowlist）。
        if not isinstance(slide_id, str) or not slide_id.strip():
            return jsonify(error="slide_id 非法"), 400
        desc = None
        try:
            desc = slide_store.resolve_slide_id(slide_id.strip())
        except Exception:
            desc = None
        if desc is None or desc.asset_state != slide_store.SlideState.READY:
            return jsonify(error="切片不存在或未发布：%s" % slide_id), 404
        slide = slide or desc.legacy_filename or desc.original_filename
        slide_id = desc.slide_id
    else:
        if not isinstance(slide, str) or not slide:
            return jsonify(error="缺少 slide"), 400
        if not (UPLOAD_DIR / _safe_name(slide)).is_file():
            return jsonify(error="切片文件不存在：%s" % slide), 404
        slide_id = share_store.get_slide_id(slide)
        if slide_id is None:
            # 首次为该切片建立稳定身份（slides 行由 meta 写入路径创建）。
            # 【P4-app §7 核对】demo 目录 PUT 是 set_slide_meta 的**允许
            # 残留位**（demo 环境按名登记 legacy 资产；P5/P6 随 demo 目录
            # 强校验/迁移收口）。
            share_store.set_slide_meta(slide)
            slide_id = share_store.get_slide_id(slide)
        if slide_id is None:
            return jsonify(error="无法解析切片稳定 id：%s" % slide), 404
    display_name = body.get("display_name")
    description = body.get("description")
    display_name_en = body.get("display_name_en")
    description_en = body.get("description_en")
    if display_name is not None and not isinstance(display_name, str):
        return jsonify(error="display_name 需为字符串"), 400
    if description is not None and not isinstance(description, str):
        return jsonify(error="description 需为字符串"), 400
    if display_name_en is not None and not isinstance(display_name_en, str):
        return jsonify(error="display_name_en 需为字符串"), 400
    if description_en is not None and not isinstance(description_en, str):
        return jsonify(error="description_en 需为字符串"), 400
    sort_order = body.get("sort_order") or 0
    try:
        sort_order = int(sort_order)
    except (TypeError, ValueError):
        return jsonify(error="sort_order 需为整数"), 400
    try:
        entry = demo_store.catalog_add(
            slide_id, display_name=display_name, description=description,
            sort_order=sort_order, added_by=current_identity().get("user_id"),
            display_name_en=display_name_en,
            description_en=description_en)
        if body.get("is_default") is True:
            entry = demo_store.catalog_set_default(slide_id)
    except ValueError as exc:
        return jsonify(error=str(exc)), 400
    _audit("demo_catalog.add", target_type="demo_catalog", target_id=slide_id,
           slide=slide)
    entry = dict(entry)
    entry["name"] = slide
    return jsonify(entry)


@app.route("/api/admin/demo-catalog", methods=["DELETE"])
def api_admin_demo_catalog_delete():
    """从 Demo 目录移除（owner）：同事务联动 revoke_by_slide（§9.3）。

    body/query: {slide（文件名）} 或 {slide_id}。返回被撤销统计与释放的预算
    预占 request_id 列表。
    """
    auth = _require_owner()
    if auth:
        return auth
    body = request.get_json(silent=True) or {}
    slide = body.get("slide") or request.args.get("slide")
    slide_id = body.get("slide_id") or request.args.get("slide_id")
    if not slide_id and isinstance(slide, str) and slide:
        slide_id = share_store.get_slide_id(slide)
        if slide_id is None:
            # 给了文件名但解析不出稳定 id（从未入库）→ 404（区别于缺参 400）
            return jsonify(error="切片不存在或从未入库：%s" % slide), 404
    if not slide_id:
        return jsonify(error="缺少 slide 或 slide_id"), 400
    result = demo_store.catalog_remove(slide_id)
    if result is None:
        return jsonify(error="切片不在 Demo 目录内"), 404
    released = _release_budget_for_terminated_runs(
        result["revoke"].get("terminated_runs"))
    _audit("demo_catalog.remove", target_type="demo_catalog", target_id=slide_id)
    return jsonify(
        removed=result["entry"],
        expired_capabilities=result["revoke"].get("expired_capabilities", 0),
        terminated_runs=result["revoke"].get("terminated_runs", []),
        released_reservations=released,
    )


# =========================================================================== #
# Admin API v1 —— 只读子集（PR3b，docs/admin-billing-plugin-implementation-plan.md §9）
#
# 面向 admin.workspace 插件（经 AdminBridge → apiFetch/CSRF 调用）的分页、
# 可版本化管理 API；旧非 v1 /api/admin/* 管理面已随 R3 wave1 物理删除，
# v1 是唯一活面（preview / demo-catalog / plugins 等专用端点除外）。
#
# 本批只做**只读**（+ provider balance refresh 这一个受控动作）：
#   - 全部端点 `_require_owner()`（actor 判定——预览态 actor 仍是 owner，但
#     预览下的写方法本就被 _preview_write_guard 拦截；POST refresh 同样受
#     CSRF 双提交保护）；
#   - 列表一律 cursor/limit（keyset 或显式 offset 游标），禁止全量返回；
#   - 敏感字段红线（§9）：响应绝不出现 password_hash / api_key / 完整邀请
#     token / 完整 IP / outbox 路径 / credential fingerprint；
#   - billing 系端点 PG-only（旧 json/dual 稳定 503 pg_backend_required 门
#     已随 R3 Wave3 退役；billing_store §6.1 fail-closed 语义不再触发）。
#   - overview 分段标记（用户段可用；billing 段失败时
#     {available:false, code:"...internal"}）——选择分段是因为概览的用户计数
#     始终真实可用，整体 503 会让管理页连基本用户概况都失去。批次 D1 起
#     turn_budget 段移出概览。
# =========================================================================== #
#: admin v1 列表缺省/最大 limit
_ADMIN_V1_DEFAULT_LIMIT = 50
_ADMIN_V1_MAX_LIMIT = 200
#: provider balance refresh 的进程内节流窗口（秒；§9 速率收敛意识）
PROVIDER_BALANCE_REFRESH_MIN_INTERVAL_SECONDS = 60.0
#: 失败后的重试间隔（秒；2026-09-11 可诊断性修复）：失败只盖 fail 章、不动
#: 成功章——否则一次失败后 60s 内重试只得 429，真实错误被节流掩盖
PROVIDER_BALANCE_REFRESH_FAILURE_RETRY_SECONDS = 10.0
_provider_balance_refresh_state = {"last_ok_attempt": 0.0,
                                   "last_fail_attempt": 0.0,
                                   "in_flight": False}
_provider_balance_refresh_lock = threading.Lock()
#: provider balance 的固定 provider id（当前唯一官方来源）
BILLING_BALANCE_PROVIDER = "deepseek"

#: 审计 detail 中**永不导出**的键片段（§10.5：密码/token/API key/完整 IP
#: 永不展示；命中即整键丢弃，不做值脱敏——防形态演化漏网）
_ADMIN_V1_AUDIT_DROP_KEY_FRAGMENTS = (
    "password", "secret", "api_key", "apikey", "token", "credential",
    "fingerprint", "cookie",
)
#: IP 类键（完整 IP 永不展示：统一丢弃，admin 页无消费场景。用边界片段而非
#: 裸 "ip" 子串——否则 "description" 这类无害键也会被误伤）
_ADMIN_V1_AUDIT_DROP_IP_KEYS = ("_ip", "ip_", "ipaddr", "remote_addr",
                                "forwarded_for")
_ADMIN_V1_AUDIT_DROP_IP_EXACT = frozenset({"ip", "clientip", "peer"})


def _require_owner_admin_v1():
    """Admin API v1 统一 owner 门控：_require_owner() + **预览态一律拒绝**。

    与 PR3a /admin 宿主页同口径（§14.1 权限行「匿名/user/preview subject 均
    不能访问 admin」）：预览态下 actor 虽仍是 owner，但管理读端点与预览 subject
    视角并存只会制造 actor/subject 混淆，且预览写 guard 本就拦 POST——统一
    拒绝（403 preview_forbidden）保持两个入口行为一致。
    """
    auth = _require_owner()
    if auth:
        return auth
    if AUTH_ENABLED and _preview_active():
        return _admin_v1_error(
            403, "preview_forbidden", "身份预览期间管理 API 不可用（请先退出预览）")
    return None


def _admin_v1_error(status, code, message):
    """admin v1 统一错误信封（code 稳定、message 无敏感信息）。"""
    return jsonify(error={"code": code, "message": message}), status


def _admin_v1_encode_cursor(obj):
    """游标对象 → 不透明 base64url 字符串（服务端私有格式，客户端只回传）。"""
    raw = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _admin_v1_decode_cursor(raw):
    """不透明游标 → dict；None/损坏一律 None（回到第一页，不抛错）。"""
    if not raw or not isinstance(raw, str):
        return None
    try:
        pad = "=" * (-len(raw) % 4)
        data = base64.urlsafe_b64decode(raw + pad).decode("utf-8")
        obj = json.loads(data)
        return obj if isinstance(obj, dict) else None
    except (ValueError, TypeError):
        return None


def _admin_v1_limit_arg():
    """limit 查询参数 → [1, _ADMIN_V1_MAX_LIMIT]（缺省 50；非法回缺省）。"""
    raw = request.args.get("limit")
    try:
        limit = int(raw) if raw is not None else _ADMIN_V1_DEFAULT_LIMIT
    except (TypeError, ValueError):
        return _ADMIN_V1_DEFAULT_LIMIT
    return max(1, min(limit, _ADMIN_V1_MAX_LIMIT))


def _admin_v1_flag_arg(name):
    """布尔筛选参数 → True/False/None（None=不过滤）。"""
    raw = (request.args.get(name) or "").strip().lower()
    if raw in ("true", "1", "yes"):
        return True
    if raw in ("false", "0", "no"):
        return False
    return None


# --------------------------------------------------------------------------- #
# §5 v0.3 修订（P2）：admin v1 金额 wire 全部十进制整数字符串
#
# JS Number 超 2^53（≈9,007,199 CNY 对应的 nano 值量级）读取即静默失真，
# 因此 nano-CNY 金额在 admin v1 wire 上禁用 JSON number：出口统一 str(int)，
# 入口只接受十进制字符串。入参限 1..19 位（可负号）；19 位字符串在
# (2^63-1, 10^19) 区间仍会溢出 PG BIGINT，解析后再卡一次界给确定性 400。
# --------------------------------------------------------------------------- #
#: 金额入参形态（§9 caps/adjustments；JSON number 一律拒绝）
_ADMIN_V1_NANO_IN_RE = re.compile(r"^-?[0-9]{1,19}$")
_PG_BIGINT_MAX = 2 ** 63 - 1
_PG_BIGINT_MIN = -(2 ** 63)

#: 响应中按字段名匹配即字符串化的 nano-CNY 键（白名单制，不误伤 token 计数）。
#: 后三个是审计 detail 内的金额镜像键（billing_store 的 caps/adjust 审计
#: detail 用无 _cny 后缀拼写；§10.5 审计页同样走金额字符串化，否则
#: >2^53 的金额经 JSON number 进浏览器会静默失真——owner 复审 P2 遗留）。
_ADMIN_V1_NANO_OUT_KEYS = frozenset((
    "balance_nano", "amount_nano_cny", "soft_cap_nano_cny",
    "hard_cap_nano_cny", "provider_cost_nano_cny", "charge_nano_cny",
    "soft_spend_cap_nano", "hard_spend_cap_nano", "total_balance_nano",
    "granted_balance_nano", "topped_up_balance_nano",
    "soft_cap_nano", "hard_cap_nano", "balance_after_nano",
    # 批次 B（§3.1/§3.2）：金额策略与周/月窗口的 nano 字段（额度面值、
    # 窗口 snapshot/spent/reserved/remaining、对账器 drift 口径、调整审计
    # 里的前后额度镜像）——同样必须十进制字符串出线，防 >2^53 失真
    "limit_nano_cny", "limit_nano_snapshot", "spent_nano_cny",
    "reserved_nano_cny", "remaining_nano", "overage_nano",
    "expected_spent_nano", "actual_spent_nano", "spent_drift_nano",
    "expected_reserved_nano", "actual_reserved_nano", "reserved_drift_nano",
    "previous_limit_nano_snapshot", "new_limit_nano_snapshot",
    "estimated_nano", "actual_nano",
    # 批次 D（§5.1/§5.2）原用户月额度/邀请月额度模板键已随 R3 Wave2-Compat
    # 退役；批次 B wave 2（§Batch B API/bridge 契约）：一次性总额度形态与邀请
    # total 模板、三键拆分的 spend 设置值（同样 BIGINT → 十进制字符串）
    "total_limit_nano_cny", "opening_spent_nano_cny",
    "default_limit_nano_cny", "user_default_total_limit_nano_cny",
    "demo_weekly_limit_nano_cny", "owner_monthly_limit_nano_cny",
    # 2026-10-20（review 一.3/二）：费用聚合出口的任务/范围金额镜像键——
    # 本任务已用、所选范围内、范围外（完整任务金额 − 范围内）与待结算预占
    # 同样是 BIGINT nano，必须十进制字符串出线（浏览器 Number 会静默失真）
    "lifetime_charge_nano_cny", "lifetime_provider_cost_nano_cny",
    "in_range_charge_nano_cny", "in_range_provider_cost_nano_cny",
    "outside_range_charge_nano_cny", "outside_range_provider_cost_nano_cny",
    "remaining_nano_cny",
))


def _admin_v1_nano_str(value):
    """nano-CNY 整数 → 十进制字符串（None 透传；唯一标量出口转换点）。"""
    if value is None:
        return None
    return str(int(value))


def _admin_v1_nano_out(value):
    """admin v1 响应对象 → 金额字段十进制字符串化（§5 v0.3 修订）。

    递归 dict/list；键名命中 ``_ADMIN_V1_NANO_OUT_KEYS`` 的值经
    :func:`_admin_v1_nano_str` 转换，其余原样。所有 admin v1 金额出口
    （overview / users / account / usage-events / ledger / provider-balance /
    caps / adjustments）统一走本 helper，禁止散落 str()。
    """
    if isinstance(value, dict):
        return {
            k: (_admin_v1_nano_str(v) if k in _ADMIN_V1_NANO_OUT_KEYS
                else _admin_v1_nano_out(v))
            for k, v in value.items()
        }
    if isinstance(value, list):
        return [_admin_v1_nano_out(v) for v in value]
    return value


# --------------------------------------------------------------------------- #
# 2026-10-20（review 一.1/一.3/二）：费用/账务的身份投影与聚合出口
#
# 要点（与 review 逐条对应）：
#   - 身份由**服务端批量投影**（单条 SELECT），不再依赖用户页缓存；规则与
#     「用户列表 identity」同源（email_normalized → email → login_id）；
#     Demo 主体显示 Demo；未知身份显式降级（identity=null +
#     identity_source='unknown'），原始 user_id 只进技术详情，绝不伪造邮箱；
#   - 聚合先于分页（store 侧 keyset），金额按原始整数 nano 求和后**统一
#     舍入一次**（Decimal，half away from zero），wire 同时给 nano 十进制
#     字符串与两位小数 CNY 字符串；
#   - 邮箱只用于展示/搜索：搜索先在服务端解析成 user_id 集合，再按账务主键
#     user_id 过滤（不把邮箱当账务键）。
# --------------------------------------------------------------------------- #
#: 默认时间范围：近 7 个 Asia/Shanghai 自然日（含今天）
_ADMIN_AGG_DEFAULT_DAYS = 7
#: 单次聚合查询的最大范围（护栏；更长历史请缩小窗口）
_ADMIN_AGG_MAX_RANGE_DAYS = 90
#: 邮箱搜索命中的 user_id 上限（超出截断并在响应显式标记，不静默丢）
_ADMIN_IDENTITY_SEARCH_LIMIT = 500
#: Asia/Shanghai 固定 UTC+8（无夏令时；与 site_stats_store 同口径，不引
#: tzdata 依赖）
_ADMIN_SHANGHAI_TZ = timezone(timedelta(hours=8))


def _admin_v1_cny_from_nano(nano):
    """整数 nano-CNY → 两位小数 CNY 字符串（half away from zero，纯 Decimal）。

    「先按原始整数 nano 求和、最后统一舍入一次」是本函数存在的唯一理由：
    逐条舍入再相加会与权威合计出现分差；全程不经 float/JS Number。
    """
    if nano is None:
        return None
    value = int(nano)
    sign = "-" if value < 0 else ""
    from decimal import Decimal, ROUND_HALF_UP
    quant = (Decimal(abs(value)) / Decimal(1000000000)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP)
    return sign + str(quant)


def _admin_v1_agg_amounts(value):
    """递归给聚合出口的每个 ``*_nano_cny`` 追加同义 ``*_cny`` 两位小数串。

    只在聚合出口使用（明细出口的金额渲染由前端既有 fmtCny 负责）；nano 键
    本身仍按 §5 v0.3 出十进制字符串，前端不得 Number 累加。
    """
    if isinstance(value, dict):
        out = {k: _admin_v1_agg_amounts(v) for k, v in value.items()}
        for key, raw in list(out.items()):
            if key.endswith("_nano_cny") and raw is not None:
                out[key[:-len("_nano_cny")] + "_cny"] = _admin_v1_cny_from_nano(
                    raw)
        return out
    if isinstance(value, list):
        return [_admin_v1_agg_amounts(v) for v in value]
    return value


def _admin_v1_attach_identity(items, *, id_key="user_id",
                              subject_key="subject_type"):
    """身份主列批投影（单条 SELECT，无 N+1）。

    ``items`` 内每个 dict 按 ``id_key``（默认 user_id）取主体、按
    ``subject_key`` 识别 demo 主体；写入统一键 ``identity`` /
    ``identity_source`` / ``identity_user_id``（技术详情用原始 ID）/
    ``identity_note``（降级说明）/ ``identity_disabled``（技术详情，不影响
    主列展示：禁用账号照常显示邮箱）。投影失败按「未知身份」降级——只影响
    展示列，不让整页 500。
    """
    items = [it for it in (items or []) if isinstance(it, dict)]
    ids = [it.get(id_key) for it in items if it.get(id_key)]
    try:
        ident = user_store.get_user_identity_map(ids)
    except Exception:
        app.logger.warning("admin 费用身份批投影失败（按未知身份降级）",
                           exc_info=True)
        ident = {}
    for item in items:
        uid = item.get(id_key)
        if item.get(subject_key) == "demo":
            item["identity"] = "Demo"
            item["identity_source"] = "demo"
            item["identity_user_id"] = None
            item["identity_note"] = "Demo 主体（匿名体验），不伪装成注册用户"
            continue
        row = ident.get(str(uid)) if uid else None
        if row is None:
            item["identity"] = None
            item["identity_source"] = "unknown"
            item["identity_user_id"] = str(uid) if uid else None
            item["identity_note"] = (
                "事件行没有 user_id 镜像（主体未就绪的历史行）" if not uid
                else "账号记录不存在或不可用；不伪造邮箱")
            item["identity_disabled"] = None
            continue
        item["identity"] = row["identity"]
        item["identity_source"] = row["identity_source"]
        item["identity_user_id"] = str(uid)
        item["identity_note"] = None
        item["identity_disabled"] = row["disabled"]
        item["identity_display_name"] = row["display_name"]
    return items


def _admin_v1_attach_task_status(items):
    """批投影任务行的权威生命周期状态（review P2-3；单条查询，无 N+1）。

    只认权威来源（demo_runs / ai_budget_reservations / ai_run_bindings）；
    没有任何来源 → ``status='unknown'``（UI「状态未知」），绝不用最后一条
    usage 的时间猜「进行中/已结束」。小时视图的内联任务行与「按任务」视图
    行必须走同一入口，保证与 task-detail 的状态一致。
    """
    items = [it for it in (items or []) if isinstance(it, dict)]
    req_ids = sorted({str(it.get("request_id")) for it in items
                      if it.get("request_id")})
    try:
        states = billing_store.admin_task_lifecycle_states(req_ids)
    except Exception:
        app.logger.warning("admin 费用任务状态批投影失败（按状态未知降级）",
                           exc_info=True)
        states = {}
    for item in items:
        rid = item.get("request_id")
        state = states.get(str(rid)) if rid else None
        if state:
            item["status"] = state["status"]
            item["status_source"] = state["source"]
            item["status_detail"] = state["detail"]
        else:
            item["status"] = "unknown"
            item["status_source"] = None
            item["status_detail"] = None
    return items


def _admin_v1_email_filter_ids():
    """``email`` 查询参数 → (user_ids|None, truncated)。

    无参数 → (None, False)（不过滤）。命中 0 个 → ([], False)（响应明确
    空页，不退化成全表）。邮箱子串匹配 email_normalized/email/login_id。
    """
    raw = (request.args.get("email") or request.args.get("q") or "").strip()
    if not raw:
        return None, False
    limit = _ADMIN_IDENTITY_SEARCH_LIMIT
    ids = user_store.list_user_ids_matching_identity(raw, limit=limit + 1)
    truncated = len(ids) > limit
    return ids[:limit], truncated


def _admin_v1_range_arg(raw):
    """范围参数 → aware datetime（先按 epoch 秒，再按 RFC3339 解析）。

    查询串里两者都是字符串；epoch 用 float 解析（秒，可带小数），非数字才
    交给 ``billing_store._as_aware_dt``（RFC3339）。解析失败抛 ValueError
    （路由映射 400），不做「猜时间」的静默兜底。
    """
    text = str(raw or "").strip()
    if not text:
        raise ValueError("空的时间参数")
    try:
        return datetime.fromtimestamp(float(text), tz=timezone.utc)
    except (TypeError, ValueError):
        pass
    return billing_store._as_aware_dt(text)


def _admin_v1_usage_range():
    """``since``/``until`` → (since, until, 元信息 dict)。

    接受 epoch 秒或 RFC3339；缺省 = 近 7 个 Asia/Shanghai 自然日（含今天）。
    范围非法/过大 → ValueError（路由映射 400），不静默回退到全量。
    """
    raw_since = (request.args.get("since") or "").strip()
    raw_until = (request.args.get("until") or "").strip()
    default_applied = not (raw_since or raw_until)
    try:
        if default_applied:
            now = datetime.now(timezone.utc)
            local = now.astimezone(_ADMIN_SHANGHAI_TZ)
            start_local = ((local - timedelta(days=_ADMIN_AGG_DEFAULT_DAYS - 1))
                           .replace(hour=0, minute=0, second=0, microsecond=0))
            since = start_local.astimezone(timezone.utc)
            until = now
        else:
            since = _admin_v1_range_arg(raw_since) if raw_since else None
            until = _admin_v1_range_arg(raw_until) if raw_until else None
            if since is None or until is None:
                raise ValueError("since 与 until 需同时提供")
            if since >= until:
                raise ValueError("since 需早于 until")
            if (until - since) > timedelta(days=_ADMIN_AGG_MAX_RANGE_DAYS):
                raise ValueError("时间范围超过 %d 天，请缩小窗口"
                                 % _ADMIN_AGG_MAX_RANGE_DAYS)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("since/until 需为 epoch 秒或 RFC3339 时间：%s"
                         % (exc,)) from exc
    return since, until, {
        "since": since.timestamp(),
        "until": until.timestamp(),
        "timezone": billing_store.ADMIN_AGG_TIMEZONE,
        "default_applied": default_applied,
        "default_days": _ADMIN_AGG_DEFAULT_DAYS,
        "amount_scope": "selected_range",
    }


def _admin_v1_agg_cursor(raw_cursor, size):
    """不透明游标 → 长度 ``size`` 的元组（None 原样；非法 → None）。"""
    if not raw_cursor:
        return None
    keys = raw_cursor.get("k")
    if not isinstance(keys, list) or len(keys) != size:
        return None
    return tuple(keys)


def _admin_v1_account_remaining(subject_type, subject_id, user_id=None):
    """账户剩余额度及其类型（review 一.3 step A 的账户侧投影，只读）。

    - ``user``（注册用户）→ 一次性总额度（``ai_spend_total_allowances``）；
    - ``owner`` → 月窗口额度（``ai_spend_windows``）；
    - ``demo`` → 全站共享 Demo 周窗口；
    - 投影不可用（缺额度行/策略被禁用）→ ``limit_type='unavailable'`` +
      稳定 ``error``，不伪造 0 剩余。
    """
    out = {
        "subject_type": subject_type,
        "subject_id": subject_id,
        "limit_type": "unavailable",
        "limit_type_label": "额度投影不可用",
        "remaining_nano_cny": None,
        "limit_nano_cny": None,
        "spent_nano_cny": None,
        "reserved_nano_cny": None,
        "window_start": None,
        "window_end": None,
        "source": None,
        "error": None,
    }
    try:
        if subject_type == "demo":
            stats = spend_store.admin_demo_spend_stats("current")
            out.update({
                "limit_type": "demo_week_window",
                "limit_type_label": "Demo 周窗口额度（全站共享）",
                "remaining_nano_cny": stats.get("remaining_nano"),
                "limit_nano_cny": stats.get("limit_nano_cny"),
                "spent_nano_cny": stats.get("spent_nano_cny"),
                "reserved_nano_cny": stats.get("reserved_nano_cny"),
                "window_start": stats.get("window_start"),
                "window_end": stats.get("window_end"),
                "source": "spend_store.admin_demo_spend_stats",
            })
            return out
        item = spend_store.admin_users_spend_summaries(
            [(subject_type, subject_id)]).get(subject_id) or {}
        if item.get("error"):
            out["error"] = item["error"]
            return out
        total = item.get("total")
        window = item.get("window")
        if total is not None:
            out.update({
                "limit_type": "user_total_allowance",
                "limit_type_label": "注册用户一次性总额度",
                "remaining_nano_cny": total.get("remaining_nano"),
                "limit_nano_cny": total.get("total_limit_nano_cny"),
                "spent_nano_cny": total.get("spent_nano_cny"),
                "reserved_nano_cny": total.get("reserved_nano_cny"),
                "source": total.get("source"),
            })
            return out
        if window is not None:
            out.update({
                "limit_type": "owner_month_window",
                "limit_type_label": "Owner 月窗口额度",
                "remaining_nano_cny": (
                    spend_store.window_remaining_nano(window)),
                "limit_nano_cny": window.get("limit_nano_snapshot"),
                "spent_nano_cny": window.get("spent_nano_cny"),
                "reserved_nano_cny": window.get("reserved_nano_cny"),
                "window_start": window.get("window_start"),
                "window_end": window.get("window_end"),
                "source": window.get("policy_id"),
            })
            return out
        out["error"] = "spend_projection_missing"
    except spend_store.SpendError as exc:
        out["error"] = getattr(exc, "code", "spend_error")
    except Exception:
        app.logger.warning("admin 账户剩余额度投影失败", exc_info=True)
        out["error"] = "spend_projection_unavailable"
    return out


def _admin_v1_amount_in(value, field, *, allow_negative=False):
    """admin v1 金额入参：十进制字符串 → int（§5 v0.3 修订；None 透传）。

    - 只接受 ``^-?[0-9]{1,19}$`` 字符串，JSON number / 小数 / 超长一律
      ``ValueError``（消息含「金额须为十进制字符串（防 float 失真）」），
      路由层映射 400；
    - 解析后卡 PG BIGINT 上下界（溢出区间的 19 位值给确定性 400，不让
      INSERT 抛 500）；
    - ``allow_negative=False``（caps）时负数同样 400。
    """
    if value is None:
        return None
    if not isinstance(value, str) or not _ADMIN_V1_NANO_IN_RE.match(value):
        raise ValueError(
            "%s 金额须为十进制字符串（防 float 失真；1..19 位整数%s）"
            % (field, "，manual_adjustment 可为负" if allow_negative else ""))
    number = int(value)
    if not _PG_BIGINT_MIN <= number <= _PG_BIGINT_MAX:
        raise ValueError(
            "%s 超出 PG BIGINT 范围（|值| ≤ 9223372036854775807）" % field)
    if number < 0 and not allow_negative:
        raise ValueError("%s 需为非负整数的十进制字符串（nano-CNY）" % field)
    return number


def _admin_v1_sanitize_audit_detail(value, key=None):
    """审计 detail 递归脱敏（§10.5 红线）。

    - 键名含敏感片段（password/secret/api_key/token/credential/fingerprint/
      cookie/IP 类）→ 整键丢弃；
    - ``idempotency_key`` 只保留后 8 字符（§10.5「idempotency key 后缀」）；
    - dict/list 递归，其余标量原样保留（detail 本就不落敏感内容，这里是
      出口防线而非唯一防线）。
    """
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            ks = str(k).lower()
            if any(frag in ks for frag in _ADMIN_V1_AUDIT_DROP_KEY_FRAGMENTS):
                continue
            if any(ipk in ks for ipk in _ADMIN_V1_AUDIT_DROP_IP_KEYS) \
                    or ks in _ADMIN_V1_AUDIT_DROP_IP_EXACT:
                continue
            if ks == "idempotency_key" and isinstance(v, str) and v:
                out[k] = v[-8:]
                continue
            cleaned = _admin_v1_sanitize_audit_detail(v, key=k)
            if cleaned is not _ADMIN_V1_DROP:
                out[k] = cleaned
        return out
    if isinstance(value, list):
        out = []
        for item in value:
            cleaned = _admin_v1_sanitize_audit_detail(item)
            if cleaned is not _ADMIN_V1_DROP:
                out.append(cleaned)
        return out
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        return _ADMIN_V1_DROP
    return value


#: 哨兵：sanitize 过程中标记「丢弃」（不能给 None——None 是合法 JSON 值）
_ADMIN_V1_DROP = object()


def _admin_v1_identity_map(user_ids):
    """批量 user_id → 完整邮箱用户名（email 优先，否则 login_id；展示 J）。

    供 owner 管理台把审计 actor / 用量明细 / 额度 / 账单等以 user_id 出线的
    位置统一映射为身份主列。查询失败返回空 map（展示降级，不 fail-closed）。
    """
    wanted = {str(u) for u in user_ids if u}
    if not wanted:
        return {}
    out = {}
    try:
        for u in user_store.list_users():
            uid = str(u.get("user_id") or "")
            if uid in wanted:
                email = str(u.get("email_normalized")
                            or u.get("email") or "")
                out[uid] = email or u.get("login_id") or uid
    except Exception:
        app.logger.warning("身份主列映射查询失败（按 user_id 展示）",
                           exc_info=True)
    return out


def _admin_v1_audit_event_out(event, identity_map=None):
    """audit 行 → admin v1 导出形态（detail 脱敏；顶层键白名单）。

    detail 脱敏后再经 ``_admin_v1_nano_out``：审计 detail 里的金额镜像
    （caps 的 soft_cap_nano/hard_cap_nano、调账的 amount_nano_cny/
    balance_after_nano）同样字符串化——>2^53 的金额以 JSON number 出线，
    浏览器 JSON.parse 会静默失真（owner 复审 P2 遗留修复）。
    展示 J：actor_identity = actor 的完整邮箱用户名（email 优先，否则
    login_id）；user_id 保留为次级技术详情。
    """
    detail = event.get("detail")
    cleaned = _admin_v1_sanitize_audit_detail(
        detail if isinstance(detail, dict) else {})
    actor_uid = str(event.get("actor_user_id") or "") or None
    return {
        "id": event.get("id"),
        "ts": event.get("ts"),
        "actor_user_id": event.get("actor_user_id"),
        "actor_identity": (identity_map or {}).get(actor_uid)
        if actor_uid else None,
        "actor_role": event.get("actor_role"),
        "action": event.get("action"),
        "target_type": event.get("target_type"),
        "target_id": event.get("target_id"),
        "slide": event.get("slide"),
        "detail": _admin_v1_nano_out(cleaned),
    }


def _admin_v1_registration_methods(user_ids):
    """注册方式归因：registration.redeem 审计（actor=被创建 user）→ invite。

    其余（owner 直接创建）→ manual；查询失败按 manual（管理页展示用途，
    不是权限判定，不 fail-closed）。campaign/source 留位 null 由 PR4 填充。
    """
    invite_users = set()
    try:
        events = share_store.list_audit(
            limit=_ADMIN_V1_MAX_LIMIT * 5, action="registration.redeem")
        for ev in events:
            actor = ev.get("actor_user_id")
            if actor:
                invite_users.add(str(actor))
    except Exception:
        app.logger.warning("注册方式归因查询失败（按 manual 展示）",
                           exc_info=True)
    return {str(u): ("invite" if str(u) in invite_users else "manual")
            for u in user_ids}


def _admin_v1_uploads_section():
    """uploads 段（G7）：committing 收口积压观测——只给计数与年龄。

    不暴露路径、原文件名或用户标识（含 fail-closed 保持 committing 的证据
    冲突任务，它们正是需要人工处置的积压）。json 后端同样可观测
    （upload_tasks.json 只读列举）；列举失败分段标记不可用，不拖垮整个概览。
    """
    try:
        tasks = upload_task_store.list_tasks(
            state=upload_task_store.STATE_COMMITTING)
    except Exception:
        app.logger.exception("admin v1 overview uploads 段读取失败")
        return {"available": False, "code": "upload_tasks_unavailable"}
    now = time.time()
    ages = [max(0.0, now - float(t.get("commit_started_at") or now))
            for t in tasks if t.get("commit_started_at")]
    backlog = [a for a in ages
               if a > upload_task_store.UPLOAD_COMMIT_TIMEOUT_SECONDS]
    return {
        "available": True,
        "committing": len(tasks),
        "committing_oldest_age_seconds": round(max(ages), 1) if ages else 0.0,
        # 超过 commit 超时仍未收口（含证据冲突 fail-closed 的任务）
        "committing_backlog": len(backlog),
    }


@app.route("/api/admin/v1/overview", methods=["GET"])
def admin_v1_overview():
    """概览（§10.1）：用户计数 + billing 用量/余额 + uploads 收口观测。

    billing 段含 model calls（今日/周期）、cache token 合计与命中率、
    provider cost / charge 合计（nano）、unpriced 数、ingestion lag、DeepSeek
    最新余额快照与年龄。
    批次 D1（§4.2）：turn 预算历史聚合移出概览（turn 消费闸早已退役，
    turn-budgets 只读端点暂留兼容但不再进 overview payload，插件不渲染；
    确认一个发布周期无消费者后另批删除 GET）。
    uploads 段（G7）：V1/ZIP 收口 committing/backlog 计数与最老年龄
    （json/PG 双后端可观测；只含聚合计数，不暴露路径/文件名/用户）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    users = user_store.list_users()
    # 2026-10-09 §2：total/active/disabled/ai_access 只计正式用户
    # （account_kind='real'），dogfood 单独计数（界面可不展示）——避免
    # 「AI access 用户数 > 用户总数」的口径错位。
    real_users = [u for u in users
                  if (u.get("account_kind") or "real") == "real"]
    users_section = {
        "total": len(real_users),
        "active": sum(1 for u in real_users if not u.get("disabled")),
        "disabled": sum(1 for u in real_users if u.get("disabled")),
        "ai_access": sum(1 for u in real_users if u.get("ai_access")),
        "dogfood": sum(1 for u in users
                       if (u.get("account_kind") or "real") == "dogfood"),
    }

    try:
        period_start = None
        try:
            report = budget_store.usage_report()
            period_start = report["period"].get("started_at")
        except Exception:
            # 「周期起点」只是金额聚合的窗口收窄优化；budget 周期读取
            # 失败按全量窗口继续（unpriced/今日等 KPI 不因冻结历史缺
            # 失而缺席）
            app.logger.warning("概览读取预算周期失败（按全量窗口）",
                               exc_info=True)
        # 「今日」按计价时区（Asia/Shanghai）零点，与价格时段同口径
        now_local = datetime.now(tz=billing_pricing.PRICING_TIMEZONE)
        today_start = now_local.replace(
            hour=0, minute=0, second=0, microsecond=0).isoformat()
        stats = billing_store.admin_overview_usage_stats(
            period_start=period_start, today_start=today_start)
        snapshot = billing_store.latest_provider_balance_snapshot(
            BILLING_BALANCE_PROVIDER)
        age = None
        if snapshot is not None:
            age = max(0.0, time.time() - float(snapshot["observed_at"]))
        billing_section = _admin_v1_nano_out({
            "available": True,
            "provider": BILLING_BALANCE_PROVIDER,
            "model_calls_today": stats["model_calls_today"],
            "model_calls_period": stats["model_calls_period"],
            "cache_hit_input_tokens": stats["cache_hit_input_tokens"],
            "cache_miss_input_tokens": stats["cache_miss_input_tokens"],
            "output_tokens": stats["output_tokens"],
            "cache_hit_ratio": stats["cache_hit_ratio"],
            "provider_cost_nano_cny": stats["provider_cost_nano_cny"],
            "charge_nano_cny": stats["charge_nano_cny"],
            "unpriced_count": stats["unpriced_count"],
            "ingestion_lag_seconds_max":
                stats["ingestion_lag_seconds_max"],
            "ingestion_lag_seconds_avg":
                stats["ingestion_lag_seconds_avg"],
            # §7.2 批次 A 只读口径：cutover 前旧错误价格影子数据
            # 区分展示（legacy_pricing_note 固定说明，不参与硬额度）
            "pricing_cutover_epoch": stats["pricing_cutover_epoch"],
            "legacy_priced_events": stats["legacy_priced_events"],
            "legacy_pricing_note": stats["legacy_pricing_note"],
            "provider_balance_snapshot": snapshot,
            "provider_balance_age_seconds": age,
        })
    except Exception:
        app.logger.exception("admin v1 overview billing 段读取失败")
        return _admin_v1_error(500, "internal", "概览读取失败")

    # 研究段（2026-10-20 §三）：异常删除任务计数（终态 failed 待人工处置）
    try:
        research_section = {
            "available": True,
            "abnormal_deletion_jobs":
                research_consent_store.count_abnormal_deletion_jobs(),
        }
    except Exception:
        app.logger.warning("概览读取研究删除任务计数失败（按不可用展示，"
                           "不渲染成「无异常」）", exc_info=True)
        research_section = {"available": False,
                            "abnormal_deletion_jobs": None}

    return jsonify(
        users=users_section,
        billing=billing_section,
        # 2026-10-20（评审 §三）：研究删除不再有独立一级页——概览只在
        # **有异常删除任务**（重试耗尽的终态 failed，待人工处置）时给计数，
        # 管理台据此显示「待处理研究数据任务 N」并点入筛选这些用户；
        # 无异常时 abnormal_deletion_jobs=0（UI 整块隐藏，不显示 0 噪音）。
        # 读取失败 available=False（前端不显示——绝不把读失败渲染成「无异常」）。
        research=research_section,
        # 批次 D1（§4.2）：turn_budget 段已移出概览（R3 wave1 起旧
        # /api/admin/v1/turn-budgets 只读兼容端点亦已删除，插件不渲染）
        # G7：V1/ZIP 收口状态机的 committing 积压观测（只含计数与年龄）
        uploads=_admin_v1_uploads_section(),
        backend=platform_features.current_backend(),
    )


@app.route("/api/admin/v1/users", methods=["GET"])
def admin_v1_users():
    """用户列表（§10.2 只读）：cursor(offset) 分页 + 搜索 + enabled/ai_access
    筛选 + kind/sort 参数（2026-10-08 §2）。

    每行：display name、login ID 掩码、role、enabled、ai_access、创建时间、
    注册方式、``account_kind``（real|dogfood）、``last_login_at``（格式与
    created_at 相同的 epoch 秒；未登录过 null）、``last_active_at``（0089：
    最近一次页面导航/写请求时间，同格式；暂无记录 null），金额余额/caps
    （未开户 null；json 后端 null）、最近 AI 调用时间（json 后端 null）、
    ``research``（2026-10-09 §2：``{state: "granted"|"withdrawn"|null,
    granted: bool}``，user_research_consents 单条批量查询装配）。

    - ``kind=real|dogfood|all``（默认 real）：按 users.account_kind 筛选
      （all = 不筛选）；
    - ``sort=joined_desc|joined_asc|last_login_desc|last_active_desc``（默认
      joined_desc）：**分页前**对全量完成排序，user_id 作稳定次键；
      ``last_login_desc`` / ``last_active_desc`` 下对应时间 IS NULL 恒排末尾
      （同样按 user_id 稳定）。``last_login_desc`` 保留兼容（旧前端仍可用），
      管理台列表的排序**选项**改为 ``last_active_desc``（默认仍为
      ``joined_desc``）。前端切换筛选/排序时清空 cursor（offset 分页在全量
      排序后切片，语义稳定）。
    - ``research=abnormal``（2026-10-20 §三）：只保留**有异常删除任务**
      （重试耗尽的终态 failed，待人工处置）的用户——概览「待处理研究数据
      任务 N」点入即带此参数；其余取值 400（不做隐式兜底）。

    spend 字段（Batch B wave 2，§Batch B API/bridge 契约）：按角色 + target
    返回**互斥**形态原样透传——role=user 且 target=total_allowance →
    ``spend.total={allowance_id,total_limit_nano_cny,spent_nano_cny,...}``
    （无 window 键）；role=owner 或 cutover 前 target=window → 现 window
    形态（policy_* + window）。缺行/策略缺失等单主体失败带稳定 ``error``
    code。前端两种形态同时出现必须报契约错误，不得任选其一（§4.3）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    limit = _admin_v1_limit_arg()
    cur = _admin_v1_decode_cursor(request.args.get("cursor"))
    offset = int(cur.get("o") or 0) if cur else 0
    if offset < 0:
        offset = 0
    search = (request.args.get("q") or "").strip().lower() or None
    enabled_f = _admin_v1_flag_arg("enabled")
    ai_f = _admin_v1_flag_arg("ai_access")
    kind = (request.args.get("kind") or "real").strip() or "real"
    if kind not in ("real", "dogfood", "all"):
        return _admin_v1_error(
            400, "invalid_request", "kind 需为 real / dogfood / all")
    sort = (request.args.get("sort") or "joined_desc").strip() or "joined_desc"
    if sort not in ("joined_desc", "joined_asc", "last_login_desc",
                    "last_active_desc"):
        return _admin_v1_error(
            400, "invalid_request",
            "sort 需为 joined_desc / joined_asc / last_login_desc / "
            "last_active_desc")
    # 2026-10-20 §三：research=abnormal 只看有异常（终态 failed）删除任务的
    # 用户；空串/缺键 = 不筛选（未知取值显式 400，不静默忽略）
    research_f = (request.args.get("research") or "").strip() or None
    if research_f is not None and research_f != "abnormal":
        return _admin_v1_error(400, "invalid_request",
                               "research 需为 abnormal（或缺省）")

    users = user_store.list_users()
    if kind != "all":
        users = [u for u in users
                 if (u.get("account_kind") or "real") == kind]
    # 排序在分页前对全量完成（§2：用户量小，内存排序 + offset 分页）；
    # user_id 稳定次键；对应时间 IS NULL 恒排末尾。
    if sort == "joined_asc":
        users.sort(key=lambda u: (float(u.get("created_at") or 0.0),
                                  str(u.get("user_id") or "")))
    elif sort in ("last_login_desc", "last_active_desc"):
        field = "last_active_at" if sort == "last_active_desc" else "last_login_at"
        users.sort(key=lambda u: (
            u.get(field) is None,
            -(float(u.get(field) or 0.0)),
            str(u.get("user_id") or "")))
    else:
        users.sort(key=lambda u: (-float(u.get("created_at") or 0.0),
                                  str(u.get("user_id") or "")))
    if search:
        # 展示 J：搜索支持精确/模糊邮箱——q 含 @ 时按规范化邮箱精确匹配
        # 命中，否则对 login_id/email/display_name 做子串（模糊）匹配
        def _search_hit(u):
            login = str(u.get("login_id") or "").lower()
            email = str(u.get("email_normalized")
                        or u.get("email") or "").lower()
            name = str(u.get("display_name") or "").lower()
            if "@" in search:
                return search == email or search == login \
                    or search in email or search in login
            return search in login or search in email or search in name
        users = [u for u in users if _search_hit(u)]
    if enabled_f is not None:
        users = [u for u in users if bool(u.get("disabled")) != enabled_f]
    if ai_f is not None:
        users = [u for u in users if bool(u.get("ai_access")) == ai_f]
    if research_f == "abnormal":
        # 异常研究删除任务的用户集合（去重）；读取失败 = 显式 503——把读失败
        # 渲染成「没有待处理用户」会让操作员漏掉真实处置
        try:
            abnormal_uids = set(
                research_consent_store.abnormal_deletion_user_ids())
        except Exception:
            app.logger.exception("admin v1 users 研究异常筛选读取失败")
            return _admin_v1_error(503, "storage_unavailable",
                                   "存储暂不可用，请稍后重试")
        users = [u for u in users
                 if str(u.get("user_id") or "") in abnormal_uids]

    page = users[offset:offset + limit + 1]
    has_more = len(page) > limit
    page = page[:limit]
    user_ids = [u.get("user_id") for u in page]

    accounts = last_calls = {}
    reg_methods = _admin_v1_registration_methods(user_ids)
    # 2026-10-09 §2：研究数据授权列（granted/withdrawn/None）——单条批量
    # SELECT 装配（research_consent_store.consent_states_map），不逐行 N+1；
    # 查询失败按「未授权」降级展示（只读展示列，不 fail-closed 整页）。
    research_by_user = {}
    try:
        research_by_user = research_consent_store.consent_states_map(user_ids)
    except Exception:
        app.logger.warning("admin v1 users 研究授权批量查询失败（按未授权展示）",
                           exc_info=True)
    # 批次 D（§6.2）→ Batch B wave 2：每用户 spend 投影（owner/user 按
    # target 互斥形态；单事务批量解析）。PR4 的 user_acquisition 归因查询
    # 已随批次 D1 删除（用户列表不再触达归因表）。
    spend_by_user = {}
    try:
        spend_by_user = spend_store.admin_users_spend_summaries([
            ("owner" if u.get("role") == user_store.ROLE_OWNER
             else "user", str(u.get("user_id") or ""))
            for u in page if u.get("user_id")])
    except Exception:
        app.logger.warning("admin v1 users 金额投影查询失败（按空展示）",
                           exc_info=True)
    try:
        accounts = billing_store.admin_account_summaries(user_ids)
        last_calls = billing_store.admin_last_ai_call_by_user()
    except Exception:
        app.logger.exception("admin v1 users 附属数据读取失败")
        return _admin_v1_error(500, "internal", "用户列表读取失败")

    items = []
    for u in page:
        uid = str(u.get("user_id") or "")
        spend = _admin_v1_user_spend_wire(spend_by_user.get(uid), u)
        email_norm = str(u.get("email_normalized")
                         or u.get("email") or "") or None
        items.append({
            "user_id": uid,
            "display_name": u.get("display_name"),
            # 展示 J（owner 管理台）：主列 = 完整邮箱用户名（有已验证 email
            # 用 email，否则 login_id；不再用随意 display_name 冒充身份）。
            # user_id 为次级技术详情（drawer 内展示）。
            "identity": email_norm or u.get("login_id") or uid,
            "identity_source": "email" if email_norm else "login_id",
            "email": u.get("email") or email_norm,
            "email_verified": u.get("email_verified_at") is not None,
            "activation_state": u.get("activation_state") or "active",
            "activation_source": u.get("activation_source"),
            "login_id_masked": registration_store.mask_login_id(
                u.get("login_id") or ""),
            "role": u.get("role"),
            "enabled": not bool(u.get("disabled")),
            "ai_access": bool(u.get("ai_access")),
            "created_at": u.get("created_at"),
            # 2026-10-08 §2：分类 + 最近登录（格式与 created_at 相同；
            # 未登录过 null——「暂无记录」）
            "account_kind": u.get("account_kind") or "real",
            "last_login_at": u.get("last_login_at"),
            # 0089：最近活跃（页面导航/写请求；抽屉仍展示 last_login_at）
            "last_active_at": u.get("last_active_at"),
            "registration_method": reg_methods.get(uid, "manual"),
            # 批次 D1（§4.4）：campaign/source 用户级归因字段整键删除
            #（历史数据仍冻结在 user_acquisition 表，仅审计工具可达）
            # 批次 F：turn_used/turn_limit 字段删除（turn 消费闸退役；
            # 金额侧见 billing/spend 字段）
            # 金额余额（billing；未开户 null，绝不伪造 0 余额账户；金额字段
            # 十进制字符串化，§5 v0.3）
            "billing": _admin_v1_nano_out(accounts.get(uid)),
            # Batch B wave 2：按角色/target 互斥的金额投影
            "spend": spend,
            # 2026-10-09 §2：研究数据授权（已授权 granted / 已撤回 withdrawn /
            # 未授权 None；declined/reconsent_required 展示口径同未授权）
            "research": research_by_user.get(uid) or {"state": None,
                                                      "granted": False},
            "last_ai_call_at": last_calls.get(uid),
        })
    next_cursor = None
    if has_more:
        next_cursor = _admin_v1_encode_cursor({"o": offset + limit})
    return jsonify(items=items, next_cursor=next_cursor, limit=limit,
                   billing_available=True)



@app.route("/api/admin/v1/billing/usage-events", methods=["GET"])
def admin_v1_billing_usage_events():
    """usage 明细分页（§10.4）：model/user_id/email/status 筛选。

    status 仅接受 priced/unpriced（unpriced 不混入「0 元调用」——金额列保持
    null 而非 0）。2026-10-20（review 一.1）：每行带服务端批投影的身份主列
    （identity/identity_source；Demo=Demo；未知身份显式降级、原始 user_id 进
    identity_user_id 技术详情），不再依赖用户页缓存；``email`` 先解析成
    user_id 集合再按账务主键过滤。旧明细接口保留（兼容，详情/展开仍用它）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    limit = _admin_v1_limit_arg()
    raw_cursor = _admin_v1_decode_cursor(request.args.get("cursor"))
    cursor = None
    if raw_cursor and "k" in raw_cursor and isinstance(raw_cursor["k"], list) \
            and len(raw_cursor["k"]) == 2:
        cursor = (raw_cursor["k"][0], raw_cursor["k"][1])
    status = (request.args.get("status") or "").strip() or None
    if status is not None and status not in billing_store.ADMIN_USAGE_STATUSES:
        return _admin_v1_error(
            400, "invalid_request",
            "status 需为 %s" % (billing_store.ADMIN_USAGE_STATUSES,))
    user_id = (request.args.get("user_id") or "").strip() or None
    try:
        search_ids, search_truncated = _admin_v1_email_filter_ids()
    except Exception:
        app.logger.exception("admin v1 usage 邮箱搜索失败")
        return _admin_v1_error(500, "internal", "邮箱搜索失败")
    user_ids = [user_id] if user_id is not None else search_ids
    if user_id is not None:
        search_truncated = False
    try:
        page = billing_store.admin_usage_events_page(
            cursor=cursor, limit=limit,
            model=(request.args.get("model") or "").strip() or None,
            user_id=user_id, user_ids=(user_ids if user_id is None else None),
            request_id=(request.args.get("request_id") or "").strip() or None,
            session_id=(request.args.get("session_id") or "").strip() or None,
            subject_type=(request.args.get("subject_type") or "").strip() or None,
            status=status)
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    except Exception:
        app.logger.exception("admin v1 usage events 读取失败")
        return _admin_v1_error(500, "internal", "用量明细读取失败")
    next_cursor = None
    if page["next_cursor"] is not None:
        next_cursor = _admin_v1_encode_cursor({"k": list(page["next_cursor"])})
    items = _admin_v1_attach_identity(page["items"])
    # 计价金额字段十进制字符串化（§5 v0.3；unpriced 保持 null 不混 0 元）
    return jsonify(items=_admin_v1_nano_out(items),
                   next_cursor=next_cursor, limit=limit,
                   identity_search_truncated=search_truncated)


