@app.route("/api/admin/v1/billing/usage-summary", methods=["GET"])
def admin_v1_billing_usage_summary():
    """费用聚合（review 二，2026-10-20）：``view=hour``（默认，按用户/小时）
    或 ``view=task``（按任务），服务端先聚合再分页（keyset 稳定分组键）。

    参数：``since``/``until``（epoch 秒或 RFC3339；缺省近 7 个 Asia/Shanghai
    自然日）、``email``（身份子串搜索 → 先解析成 user_id 集合）、``user_id``
    （精确主体）、``model``、``sort``、``cursor``、``limit``。

    - 小时桶固定 Asia/Shanghai 自然小时；``view=hour`` 的行内联该小时的
      ``tasks``（上限 ``ADMIN_MAX_TASKS_PER_GROUP``，超出 ``tasks_truncated``）；
    - 任务键 = 权威 request_id + 主体身份；``request_id`` 缺失的历史行按
      主体 + 会话分组并标 ``unattributed``（「历史未归属调用」）；
    - void 排除、unpriced 只计数（金额 unknown，绝不按 0 元）；金额按整数
      nano 求和后统一舍入一次，nano 与两位小数 CNY 字符串同时出线；
    - ``totals`` 为所选范围的权威合计（含 ``unpriced_amount='unknown'``、
      ``ledger_included=false``——与账本分开，不做 event + ledger 双计）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    limit = _admin_v1_limit_arg()
    view = (request.args.get("view") or "hour").strip()
    if view not in billing_store.ADMIN_USAGE_VIEWS:
        return _admin_v1_error(400, "invalid_request",
                               "view 需为 %s"
                               % (billing_store.ADMIN_USAGE_VIEWS,))
    sort = (request.args.get("sort") or "").strip() or None
    default_sort = "hour_desc" if view == "hour" else "activity_desc"
    if sort is None:
        sort = default_sort
    if sort not in billing_store.ADMIN_USAGE_SORTS:
        return _admin_v1_error(400, "invalid_request",
                               "sort 需为 %s"
                               % (billing_store.ADMIN_USAGE_SORTS,))
    if view == "hour" and sort == "activity_desc":
        sort = "hour_desc"
    if view == "task" and sort == "hour_desc":
        sort = "activity_desc"
    model = (request.args.get("model") or "").strip() or None
    user_id = (request.args.get("user_id") or "").strip() or None
    status = (request.args.get("status") or "").strip() or None
    if status is not None and status not in billing_store.ADMIN_USAGE_STATUSES:
        return _admin_v1_error(
            400, "invalid_request",
            "status 需为 %s" % (billing_store.ADMIN_USAGE_STATUSES,))
    try:
        since, until, range_meta = _admin_v1_usage_range()
        search_ids, search_truncated = _admin_v1_email_filter_ids()
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    except Exception:
        app.logger.exception("admin v1 usage summary 参数解析失败")
        return _admin_v1_error(500, "internal", "邮箱搜索失败")
    user_ids = [user_id] if user_id is not None else search_ids
    if user_id is not None:
        search_truncated = False
    raw_cursor = _admin_v1_decode_cursor(request.args.get("cursor"))
    if view == "hour":
        cursor_size = 4 if sort == "charge_desc" else 3
    else:
        cursor_size = 3 if sort == "charge_desc" else 2
    cursor = _admin_v1_agg_cursor(raw_cursor, cursor_size)
    try:
        if view == "hour":
            page = billing_store.admin_usage_hour_summary(
                since=since, until=until, user_ids=user_ids, model=model,
                status=status, sort=sort, cursor=cursor, limit=limit)
        else:
            page = billing_store.admin_usage_task_page(
                since=since, until=until, user_ids=user_ids, model=model,
                status=status, sort=sort, cursor=cursor, limit=limit)
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    except Exception:
        app.logger.exception("admin v1 usage summary 读取失败")
        return _admin_v1_error(500, "internal", "费用聚合读取失败")
    items = _admin_v1_attach_identity(page["items"])
    if view == "hour":
        # 小时行内联任务行：身份 + 权威生命周期状态（同一批投影）
        for item in items:
            tasks = item.get("tasks") or []
            _admin_v1_attach_identity(tasks)
            _admin_v1_attach_task_status(tasks)
    else:
        _admin_v1_attach_task_status(items)
    next_cursor = None
    if page["next_cursor"] is not None:
        next_cursor = _admin_v1_encode_cursor({"k": list(page["next_cursor"])})
    payload = _admin_v1_nano_out({
        "view": view,
        "sort": sort,
        "items": items,
        "totals": page["totals"],
        "next_cursor": next_cursor,
        "limit": page["limit"],
        "range": range_meta,
        "identity_search_truncated": search_truncated,
        "identity_search": (request.args.get("email") or "").strip() or None,
        # 口径说明（页面直接展示，避免把两套金额读成一本账）
        "amount_scope_note": (
            "金额为 ai_usage_events 的 priced 事件合计（void 排除、unpriced "
            "金额未知）；不含账本；hold 预占单列不进已用"),
        "timezone": billing_store.ADMIN_AGG_TIMEZONE,
    })
    return jsonify(_admin_v1_agg_amounts(payload))


@app.route("/api/admin/v1/billing/task-detail", methods=["GET"])
def admin_v1_billing_task_detail():
    """单任务明细 + 预算投影（review 一.3 step A；只读）。

    定位：``request_id`` + ``subject_type`` + ``subject_id``（历史未归属行
    传 ``session_id`` 且不带 request_id）。返回：

    - ``in_range`` / ``lifetime`` / ``outside_range``：所选范围内、完整任务、
      范围外（完整 − 范围内）金额与调用——展开时看完整任务金额，避免把完整
      任务总额重复叠加到每个小时行；
    - ``status``（权威生命周期：running/finished/accepted/unknown，来自
      demo_runs / ai_budget_reservations / ai_run_bindings；没有来源时
      unknown，UI 显示「状态未知」，绝不用最后一条 usage 时间猜）；
    - ``budget``：本任务已用（lifetime priced charge）与待结算预占（open
      holds，按会话；hold 表没有 request_id 列）分列，unpriced 只计数；
      step A 明确「未设置单次上限，按账户剩余额度控制」（per_task_cap 恒
      null）——**本轮不实现单次上限（step B）**；
    - ``account``：主体账户剩余额度及其类型（用户一次性总额度 / Owner 月
      窗口 / Demo 周窗口）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    request_id = (request.args.get("request_id") or "").strip() or None
    subject_type = (request.args.get("subject_type") or "").strip() or None
    subject_id = (request.args.get("subject_id") or "").strip() or None
    session_id = (request.args.get("session_id") or "").strip() or None
    if not subject_type or not subject_id:
        return _admin_v1_error(400, "invalid_request",
                               "subject_type 与 subject_id 必填")
    if subject_type not in ("owner", "user", "demo"):
        return _admin_v1_error(400, "invalid_request",
                               "subject_type 需为 owner|user|demo")
    if not request_id and not session_id:
        return _admin_v1_error(
            400, "invalid_request",
            "需要 request_id（权威任务键）；无 request_id 的历史行请带 session_id")
    try:
        since, until, range_meta = _admin_v1_usage_range()
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    try:
        detail = billing_store.admin_task_detail(
            request_id=request_id, subject_type=subject_type,
            subject_id=subject_id, session_id=session_id,
            since=since, until=until)
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    except Exception:
        app.logger.exception("admin v1 task detail 读取失败")
        return _admin_v1_error(500, "internal", "任务明细读取失败")
    detail["range"] = range_meta
    if request_id:
        detail = _admin_v1_attach_identity([detail], subject_key="subject_type")[0]
    else:
        detail["identity"] = None
        detail["identity_source"] = "unknown"
        detail["identity_user_id"] = None
        detail["identity_note"] = "历史未归属调用（无 request_id，无权威生命周期）"
    detail["account"] = _admin_v1_account_remaining(
        subject_type, subject_id, user_id=detail.get("user_id"))
    return jsonify(_admin_v1_agg_amounts(_admin_v1_nano_out(detail)))


def _admin_v1_provider_balance_payload():
    """最新 provider 余额快照 + 年龄（无快照 → snapshot:null；金额字符串化）。"""
    snapshot = billing_store.latest_provider_balance_snapshot(
        BILLING_BALANCE_PROVIDER)
    age = None
    if snapshot is not None:
        age = max(0.0, time.time() - float(snapshot["observed_at"]))
    import pg_store
    with pg_store.connect() as conn:
        row = conn.execute(
            "SELECT ts, detail FROM audit_events WHERE action = %s"
            " ORDER BY ts DESC LIMIT 1",
            ("billing.provider_balance_auto_check",)).fetchone()
    return _admin_v1_nano_out({
        "provider": BILLING_BALANCE_PROVIDER,
        "snapshot": snapshot,
        "age_seconds": age,
        "auto_check": {
            "enabled": os.environ.get("PROVIDER_BALANCE_AUTO_CHECK_ENABLED", "1") == "1",
            "last_checked_at": row[0].isoformat() if row else None,
            "status": (row[1] or {}).get("status") if row else None,
            "refresh_interval_seconds": 3600,
            "retry_interval_seconds": 300,
        },
    })


@app.route("/api/admin/v1/billing/provider-balance", methods=["GET"])
def admin_v1_billing_provider_balance():
    """DeepSeek 最新余额快照 + 年龄（§10.1/§10.4 余额卡数据源）。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    try:
        return jsonify(**_admin_v1_provider_balance_payload())
    except Exception:
        app.logger.exception("admin v1 provider balance 读取失败")
        return _admin_v1_error(500, "internal", "供应商余额读取失败")


@app.route("/api/admin/v1/billing/provider-balance/refresh", methods=["POST"])
def admin_v1_billing_provider_balance_refresh():
    """手动抓取 DeepSeek GET /user/balance 并写快照（§6.6/§9）。

    - 用**加密保存的官方 API key**（ai_config.json 的 enc: 密文经
      _load_ai_config/_decrypt_api_key 解密，密钥 ai_secret.key 0600）；
      key 绝不进日志/响应/审计；
    - 金额十进制字符串经 billing_pricing.parse_balance_to_nano（Decimal 精确
      换算，禁 float 中转）；解析失败只返回错误类别，**不写伪造零余额**；
    - 简单节流（进程内，请求发出**前不预盖章**，成功/失败分账——2026-09-11
      可诊断性修复）：距上次**成功** <
      PROVIDER_BALANCE_REFRESH_MIN_INTERVAL_SECONDS（缺省 60s）或距上次
      **失败** < PROVIDER_BALANCE_REFRESH_FAILURE_RETRY_SECONDS（10s）或
      已有请求 in-flight → 429 refresh_throttled（message 带还需等待的秒数）。
      in-flight 在锁内原子占用、finally 释放，避免首个上游请求未完成时后续
      请求都穿过历史完成时间检查并打到上游。
    - 失败错误类别（稳定 code）：provider_not_configured /
      provider_unreachable / provider_rejected（4xx）/ provider_error（5xx、
      响应形态异常）/ invalid_balance_response（金额解析失败）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth

    return _refresh_provider_balance()


def _refresh_provider_balance():
    """Shared refresh implementation; caller supplies owner auth or system context."""
    def _throttled(wait_seconds):
        # 429 message 带还需等待的秒数（文案中文，code 稳定不变）
        return _admin_v1_error(
            429, "refresh_throttled",
            "刷新过于频繁，还需等待 %ds 再试" % wait_seconds)

    cfg = _load_ai_config()
    if _effective_provider_kind(cfg) != AI_PROVIDER_DEEPSEEK_OFFICIAL:
        # 配置类拒绝发生在请求发出前，不消耗节流窗口 / in-flight
        return _admin_v1_error(
            400, "provider_not_configured",
            "provider balance 仅支持 deepseek_official 官方配置")
    api_key = str(cfg.get("api_key") or "").strip()
    if not api_key:
        return _admin_v1_error(
            400, "provider_not_configured", "官方 API key 未配置")

    with _provider_balance_refresh_lock:
        now = time.time()
        state = _provider_balance_refresh_state
        if state.get("in_flight"):
            return _throttled(1)
        ok_wait = math.ceil(PROVIDER_BALANCE_REFRESH_MIN_INTERVAL_SECONDS
                            - (now - state["last_ok_attempt"]))
        if ok_wait > 0:
            return _throttled(ok_wait)
        fail_wait = math.ceil(PROVIDER_BALANCE_REFRESH_FAILURE_RETRY_SECONDS
                              - (now - state["last_fail_attempt"]))
        if fail_wait > 0:
            return _throttled(fail_wait)
        state["in_flight"] = True

    try:
        return _admin_v1_billing_provider_balance_refresh_body(cfg, api_key)
    finally:
        with _provider_balance_refresh_lock:
            _provider_balance_refresh_state["in_flight"] = False


def _admin_v1_billing_provider_balance_refresh_body(cfg, api_key):
    base = str(cfg.get("base_url") or DEEPSEEK_BASE_URL).strip().rstrip("/")
    url = base + "/user/balance"

    def _resp_excerpt(resp, limit=300):
        # 官方（错误）响应 body 可记：api_key 只在请求头、不在 body；
        # 截断到 300 字符防日志膨胀（字节流按 utf-8 容错解码）
        return (getattr(resp, "content", b"") or b"").decode(
            "utf-8", "replace")[:limit]

    def _fail(status, code, message, http_status=None, resp_excerpt=None):
        # 失败：盖 fail 章、**不动**成功章；key 不进日志/响应——日志只含
        # 类别、上游 HTTP 状态码与错误 body 截断，请求头一律不记
        with _provider_balance_refresh_lock:
            _provider_balance_refresh_state["last_fail_attempt"] = time.time()
        if http_status is None:
            app.logger.warning("provider balance refresh 失败（%s）", code)
        else:
            app.logger.warning(
                "provider balance refresh 失败（%s, HTTP %s）：%s",
                code, http_status, resp_excerpt or "")
        return _admin_v1_error(status, code, message)

    try:
        # Authorization 头只进官方端点；异常文本可能含 URL，但 URL 不含 key
        resp = requests.get(url, headers={
            "Authorization": "Bearer " + api_key,
        }, timeout=10.0)
    except (requests.ConnectionError, requests.Timeout):
        return _fail(502, "provider_unreachable", "官方余额端点不可达")
    except Exception:
        # 兜底必须记异常对象（否则真实失败原因无法诊断，2026-09-11）
        app.logger.exception("provider balance refresh 请求异常")
        return _fail(502, "provider_error", "官方余额端点请求失败")
    if 400 <= resp.status_code < 500:
        return _fail(502, "provider_rejected",
                     "官方余额端点拒绝（HTTP %d）" % resp.status_code,
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    if resp.status_code != 200:
        return _fail(502, "provider_error",
                     "官方余额端点异常（HTTP %d）" % resp.status_code,
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    try:
        body = resp.json()
    except ValueError:  # requests JSONDecodeError 是 ValueError 子类
        return _fail(502, "provider_error", "官方余额响应非 JSON",
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    if not isinstance(body, dict):
        return _fail(502, "provider_error", "官方余额响应形态非法",
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    infos = body.get("balance_infos")
    cny = None
    if isinstance(infos, list):
        for info in infos:
            if isinstance(info, dict) and str(
                    info.get("currency") or "").upper() == "CNY":
                cny = info
                break
    if cny is None:
        return _fail(502, "invalid_balance_response", "响应缺少 CNY 余额条目",
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    try:
        total = billing_pricing.parse_balance_to_nano(cny["total_balance"])
        granted = billing_pricing.parse_balance_to_nano(
            cny.get("granted_balance"))
        topped = billing_pricing.parse_balance_to_nano(
            cny.get("topped_up_balance"))
    except (KeyError, TypeError, ValueError):
        # 不写伪造零余额：解析失败只报错误类别（§5/§6.6）
        return _fail(502, "invalid_balance_response", "余额金额解析失败",
                     http_status=resp.status_code,
                     resp_excerpt=_resp_excerpt(resp))
    is_available = bool(body.get("is_available"))
    try:
        snapshot = billing_store.insert_provider_balance_snapshot(
            BILLING_BALANCE_PROVIDER, "CNY", total, granted, topped,
            is_available, datetime.now(timezone.utc))
    except Exception:
        app.logger.exception("provider balance 快照写入失败")
        return _admin_v1_error(500, "internal", "余额快照写入失败")
    # 成功：盖成功章、清失败章（失败章只影响 10s 重试节奏）
    with _provider_balance_refresh_lock:
        _provider_balance_refresh_state["last_ok_attempt"] = time.time()
        _provider_balance_refresh_state["last_fail_attempt"] = 0.0
    if has_request_context():
        _audit("billing.provider_balance_refresh",
               target_type="provider_balance", target_id=BILLING_BALANCE_PROVIDER,
               detail={"status": "ok", "is_available": is_available})
    return jsonify(ok=True, snapshot=_admin_v1_nano_out(snapshot),
                   age_seconds=0.0, provider=BILLING_BALANCE_PROVIDER)


@app.route("/api/admin/v1/audit", methods=["GET"])
def admin_v1_audit():
    """审计分页（§10.5）：cursor(offset) + action 筛选，detail 出口脱敏。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    limit = _admin_v1_limit_arg()
    cur = _admin_v1_decode_cursor(request.args.get("cursor"))
    offset = int(cur.get("o") or 0) if cur else 0
    if offset < 0:
        offset = 0
    action = (request.args.get("action") or "").strip() or None
    try:
        events = share_store.list_audit(limit=limit + 1, offset=offset,
                                        action=action)
    except Exception:
        app.logger.exception("admin v1 audit 读取失败")
        return _admin_v1_error(500, "internal", "审计读取失败")
    has_more = len(events) > limit
    events = events[:limit]
    next_cursor = None
    if has_more:
        next_cursor = _admin_v1_encode_cursor({"o": offset + limit})
    identity_map = _admin_v1_identity_map(
        [ev.get("actor_user_id") for ev in events])
    return jsonify(
        items=[_admin_v1_audit_event_out(e, identity_map) for e in events],
        next_cursor=next_cursor, limit=limit)


# --------------------------------------------------------------------------- #
# PR5：Admin API v1 写端点（§9 表写行 / §12.2 Phase B 调账 / §13 PR5 批次）
#
# 统一口径：
#   - owner 门控 = _require_owner_admin_v1（_require_owner + 预览态一律 403，
#     与只读端点/宿主页同口径 §14.1）；CSRF 沿用 before_request 全局闸；
#   - 旧建号端点 POST /api/admin/users 曾 410 退役（review R2-F1：total 模式
#     下会建出无 allowance 行的用户），R3 wave1 已随旧管理面一并物理删除；
#     R6（2026-09-19 service review §8）：手动建号的 v1 入口
#     POST /api/admin/v1/users 也一并 410 退役（管理面不再提供手动建号，
#     用户获取统一走正常注册/邀请码；用户管理写面只剩 enable/disable/
#     ai-access/password-reset，break-glass 不变量原样保持——owner 禁用/
#     重置一律 409，disable/enable 同事务推进 auth_version）；
#   - 身份冲突清单/孤儿处置两端点（GET identity-conflicts、POST
#     discard-pending，review P2-2 产品闭环）同批 410 退役（R6）：管理面
#     不再提供身份冲突页与物理删除入口；退役入口对任何已登录调用方（含
#     owner）稳定 410 endpoint_retired 且不读不写任何数据（匿名在
#     before_request 认证闸照常 401）；
#   - billing 写（caps/adjustments）端点已随 R3 wave1 下线（bridge 侧早已
#     无调用方；billing_store 写原语保留，供调账工具链使用）；
#   - 响应红线与只读端点一致：绝不含 password_hash / ai_config（内含 enc:
#     密文形态）/ 完整邀请 token（创建邀请的明文码仅首次响应返回 + no-store）
#     / 完整 IP。
# --------------------------------------------------------------------------- #
def _admin_v1_retired(method_hint):
    """R6 退役端点的统一 410 响应。

    认证闸（before_request）仍先于本分支：匿名请求照常 401；任何**已登录**
    调用方（含 owner/预览态/普通用户）一律 410，视图内不再有任何读写——
    不建用户、不删行、不写审计。
    """
    return _admin_v1_error(
        410, "endpoint_retired",
        "该管理入口已退役（R6）：不再提供%s，请改用正常注册/邀请流程" % method_hint)


def _admin_v1_user_out(user):
    """用户写端点响应出口：剥 password_hash 与 ai_config（§9 敏感红线）。"""
    out = dict(user or {})
    out.pop("password_hash", None)
    out.pop("ai_config", None)
    return out


@app.route("/api/admin/v1/users", methods=["POST"])
def admin_v1_users_create():
    """R6 退役（2026-09-19 service review §8）：手动新建用户入口下线。

    管理台「新建用户」表单与桥方法（admin.users.create）已同批移除；本端点
    对任何**已登录**调用方（owner/普通用户/预览态；匿名经 before_request
    认证闸照常 401）稳定返回 410 endpoint_retired，**不执行任何操作**
    （不建用户、不写审计、不读库）。用户获取统一走正常
    注册（invite_only / email_verify_invite_activation）；既有用户的额度
    调整仍走 /api/admin/v1/spend/users/<id>/total-limit。
    """
    return _admin_v1_retired("手动新建用户")


def _admin_v1_set_user_enabled(user_id, enabled):
    """enable/disable 共用实现（镜像旧 3832/3855：owner → 409 break-glass）。"""
    target = user_store.get_user(user_id)
    if target is None:
        return _admin_v1_error(404, "user_not_found", "用户不存在")
    if target.get("role") == user_store.ROLE_OWNER:
        return _admin_v1_error(
            409, "owner_break_glass",
            "不能经 Web 启用/禁用 owner（docs §3.2 不变量 5）；owner 恢复"
            "请使用主机侧 break-glass CLI（useradmin）")
    user = user_store.set_user_disabled(user_id, not enabled)
    _audit("user.enable" if enabled else "user.disable",
           target_type="user", target_id=user_id)
    return jsonify(user=_admin_v1_user_out(user))


@app.route("/api/admin/v1/users/<user_id>/enable", methods=["POST"])
def admin_v1_users_enable(user_id):
    """启用用户（镜像旧端点：store 层同事务推进 auth_version）。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    return _admin_v1_set_user_enabled(user_id, True)


@app.route("/api/admin/v1/users/<user_id>/disable", methods=["POST"])
def admin_v1_users_disable(user_id):
    """禁用用户（旧 session 立即失效：disable 同事务 auth_version+1）。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    return _admin_v1_set_user_enabled(user_id, False)


@app.route("/api/admin/v1/users/<user_id>/ai-access", methods=["POST"])
def admin_v1_users_ai_access(user_id):
    """设置平台 AI 权限（镜像旧 4163；body {enabled: bool}；PG-only）。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    body = request.get_json(silent=True) or {}
    if not isinstance(body.get("enabled"), bool):
        return _admin_v1_error(400, "invalid_request", "缺少 enabled 布尔字段")
    import user_store_pg
    user = user_store_pg.set_user_ai_access(user_id, bool(body["enabled"]))
    if user is None:
        return _admin_v1_error(404, "user_not_found", "用户不存在")
    _audit("user.ai_access", target_type="user", target_id=user_id,
           detail={"enabled": bool(body["enabled"])})
    return jsonify(user=_admin_v1_user_out(user))


@app.route("/api/admin/v1/users/<user_id>/account-kind", methods=["POST"])
def admin_v1_users_account_kind(user_id):
    """设置账号分类（2026-10-08 §2；body {account_kind: "real"|"dogfood"}）。

    - 与 enable/ai-access 同组语义：owner 权限（_require_owner_admin_v1，
      预览态拒绝）+ 全局 CSRF（before_request）；
    - 值未变 → 不写审计（返回当前值）；变化 → 审计
      ``admin.user.account_kind``，detail 记录前后值；
    - 不改 session、额度、角色、启用状态（auth_version 不推进——分类是纯
      管理标注，不影响任何凭据语义）。
    """
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    body = request.get_json(silent=True) or {}
    kind = body.get("account_kind")
    if kind not in user_store.ACCOUNT_KINDS:
        return _admin_v1_error(
            400, "invalid_request",
            "account_kind 需为 %s" % (user_store.ACCOUNT_KINDS,))
    try:
        after, changed, before = user_store.set_user_account_kind(user_id, kind)
    except ValueError as exc:
        return _admin_v1_error(400, "invalid_request", str(exc))
    if after is None:
        return _admin_v1_error(404, "user_not_found", "用户不存在")
    if changed:
        _audit("admin.user.account_kind", target_type="user",
               target_id=user_id,
               detail={"from": before, "to": after})
    return jsonify(user_id=user_id, account_kind=after, changed=bool(changed))


@app.route("/api/admin/v1/users/<user_id>/password-reset", methods=["POST"])
def admin_v1_users_password_reset(user_id):
    """重置普通用户密码（镜像旧 3877：owner → 409；hash 与 auth_version+1 同事务）。"""
    auth = _require_owner_admin_v1()
    if auth:
        return auth
    target = user_store.get_user(user_id)
    if target is None:
        return _admin_v1_error(404, "user_not_found", "用户不存在")
    if target.get("role") == user_store.ROLE_OWNER:
        return _admin_v1_error(
            409, "owner_break_glass",
            "不能经 Web 重置 owner 密码（docs §3.2 不变量 5）：owner 请用"
            "「修改我的密码」自助修改；失联恢复走主机侧 break-glass CLI")
    body = request.get_json(silent=True) or {}
    new_password = body.get("password")
    if not isinstance(new_password, str) or not new_password:
        return _admin_v1_error(400, "invalid_request", "缺少密码")
    if (len(new_password) < user_store.PASSWORD_MIN_LENGTH
            or len(new_password) > user_store.PASSWORD_MAX_LENGTH):
        return _admin_v1_error(
            400, "invalid_request",
            "密码长度须在 %d..%d 字符之间（当前 %d 字符）"
            % (user_store.PASSWORD_MIN_LENGTH, user_store.PASSWORD_MAX_LENGTH,
               len(new_password)))
    try:
        user = user_store.set_user_password(user_id, new_password)
    except ValueError as e:
        return _admin_v1_error(400, "invalid_request", str(e))
    if user is None:
        return _admin_v1_error(404, "user_not_found", "用户不存在")
    _audit("user.password_reset", target_type="user", target_id=user_id,
           detail={"sessions_revoked": True})
    return jsonify(user=_admin_v1_user_out(user))


