#: sha256_expected 声明的格式校验（/api/ingestions 创建契约）。
_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


def _upload_v2_cleanup_confirmed(task):
    """清理确认收口（R12 §3.3 单事务）：释放预约 + 删 pending 行同一
    事务（``upload_task_store.confirm_cleanup_and_release``：task → quota
    → reservation 锁序）。DB 失败整笔回滚——**失败必须留下持久重试记录**
    （此前无 pending 行时补登记一行），不以「文件已删」冒充收口成功。"""
    try:
        upload_task_store.confirm_cleanup_and_release(
            task["upload_id"],
            fallback_reservation_id=task.get("reservation_id"))
    except Exception:
        app.logger.exception("清理确认收口失败（补登记重试，容量保留）：%s",
                             task.get("upload_id"))
        try:
            upload_task_store.record_cleanup_pending(
                task["upload_id"], task.get("reservation_id"),
                error="cleanup confirm closeout failed")
        except Exception:
            app.logger.exception(
                "收口失败后的 pending 补登记失败（容量保留，孤儿扫描兜底）"
                "：%s", task.get("upload_id"))


# --------------------------------------------------------------------------- #
# COS 直传摄取 API（合同 §4，Phase 3）。裁决 A-presign-parts：只有
# parts/sign 一个授权接口，/credentials 不存在（B 已否决）。
# 写接口经全局登录 + CSRF 闸；COS 网络调用一律不在本进程（worker 专用），
# 本块唯一的授权产物是纯本地计算的绑定 Content-Length 预签名 URL。
# --------------------------------------------------------------------------- #
def _cos_ingestion_ready():
    """COS 直传可用性（服务端权威：capability + 凭证 + 池未暂停）。"""
    _sid, _skey, ok = cos_config.cos_credentials()
    if not ok or not cos_config.capability_available_for(
            current_identity()["role"], ok):
        return None, (jsonify(error="cos 直传未开放", code="cos_unavailable"), 404)
    try:
        pool = cos_pool_store.get_pool_state()
    except Exception:
        app.logger.exception("cos pool state read failed")
        return None, (jsonify(error="cos 直传暂不可用",
                              code="cos_unavailable"), 503)
    if pool is None:
        return None, (jsonify(error="cos 直传暂不可用",
                              code="cos_unavailable"), 503)
    return pool, None


_INGESTION_STAGE = {
    ingestion_store.WAITING: "waiting_space",
    ingestion_store.PREPARING: "uploading",
    ingestion_store.UPLOADING: "uploading",
    ingestion_store.COMPLETING: "awaiting_server",
    ingestion_store.QUEUED: "downloading",
    ingestion_store.DOWNLOADING: "downloading",
    ingestion_store.VALIDATING: "validating",
    ingestion_store.READY: "readiness",
    ingestion_store.COMPLETED: "viewable",
    ingestion_store.CANCELLED: "terminal",
    ingestion_store.FAILED: "terminal",
    ingestion_store.EXPIRED: "terminal",
}


def _ingestion_state_body(job, *, queue_position=None):
    """任务状态 JSON（阶段文案映射合同 §5；不含任何秘密/签名 URL）。

    U2（0075）：kind 下发；zip 附 items 子视图（逐逻辑切片的
    slide_id/state/fail_code）；conversion 附 conversion 子视图（转换任务
    状态/产物 slide_id——ready 才有）；非 native 的 validating 与
    conversion 的 ready 文案为 processing（解包/转换进行中）。"""
    kind = (job.get("kind") or ingestion_store.KIND_NATIVE)
    stage = _INGESTION_STAGE.get(job["state"], "terminal")
    if kind != ingestion_store.KIND_NATIVE:
        if job["state"] == ingestion_store.VALIDATING:
            stage = "processing"
        if kind == ingestion_store.KIND_CONVERSION \
                and job["state"] == ingestion_store.READY:
            stage = "processing"  # 源已入账、转换在途（completed=转换 ready）
    body = {
        "job_id": job["job_id"],
        "state": job["state"],
        "kind": kind,
        "stage": stage,
        "declared_size": job["declared_size"],
        "format_ext": job["format_ext"],
        "viewer_ready": bool(job.get("viewer_ready")),
        "cleanup_status": job.get("cleanup_status"),
        # 0072：本地清理进度独立暴露（对外文案反映清理状态，不以远端成功
        # 证明本地已删除）。
        "local_cleanup_status": job.get("local_cleanup_status"),
        "fail_code": job.get("fail_code"),
        # 0084（upload-liveness）：终态失败的安全细节（稳定白名单值，如
        # raster_format_mismatch）——前端映射为针对性可读文案；fail_code
        # 语义保持不变。
        "fail_detail": job.get("fail_detail") or None,
        "created_at": job.get("created_at"),
        "expires_at": job.get("waiting_expires_at")
        if job["state"] == ingestion_store.WAITING else job.get("job_deadline_at"),
    }
    if kind == ingestion_store.KIND_ZIP:
        items = ingestion_store.list_ingestion_job_items(job["job_id"])
        if items:
            body["items"] = items
    elif kind == ingestion_store.KIND_CONVERSION:
        conv = ingestion_store.conversion_view(job)
        if conv is not None:
            body["conversion"] = conv
    if job["state"] == ingestion_store.DOWNLOADING:
        body["downloaded_bytes"] = job.get("downloaded_bytes")
    if job["state"] == ingestion_store.UPLOADING and job.get("part_plan_json"):
        # 非秘密冻结计划（编号+长度）：浏览器据此申请签名与切片上传
        body["total_parts"] = len(job["part_plan_json"])
        body["parts"] = [{"part_number": int(p["part_number"]),
                          "length": int(p["length"])}
                         for p in job["part_plan_json"]]
    # P4-b（合同 §5.6）：slide 引用从任务绑定读（job_slide_ref——job.slide_id
    # 创建即分配，结算前后都在）；不再按 slide_canonical_name 名字解析（新
    # 资产无 legacy_filename，按名 resolve 对 id_bundle 产物恒 None）。
    ref = ingestion_store.job_slide_ref(job)
    if ref["slide"]:
        body["slide"] = ref["slide"]
    if ref["slide_id"]:
        body["slide_id"] = ref["slide_id"]
    if queue_position is not None:
        body["queue_position"] = queue_position
    return body


def _ingestion_fetch(job_id):
    """ownership 拉取：本人或 owner；他人/不存在统一 403（不泄露存在性）。"""
    ident = current_identity()
    job = ingestion_store.get_job(job_id)
    uid = ident.get("user_id") or ""
    if (job is None
            or (job["owner_user_id"] != uid
                and ident.get("role") != user_store.ROLE_OWNER)):
        return None, (jsonify(error="无权限"), 403)
    return job, None


def _touch_ingestion_client_seen(job):
    """owner 触点：刷新任务的 ``client_seen_at``（0084，upload-liveness）。

    liveness 表达「上传方浏览器还在场」——只在归属客户端本人发起的
    status 轮询 / parts/sign / upload-complete 时刷新（owner 视角的他人
    查看不触发；节流由 store 侧 COS_CLIENT_SEEN_TOUCH_SECONDS 控制）。
    任何失败只降级记日志，绝不影响响应。"""
    ident = current_identity()
    uid = (ident.get("user_id") or "").strip()
    if not uid or (job.get("owner_user_id") or "") != uid:
        return
    try:
        ingestion_store.touch_client_seen(job["job_id"])
    except Exception:  # noqa: BLE001 - 触点失败不阻塞控制请求
        app.logger.debug("client_seen_at 刷新失败（job=%s）", job["job_id"],
                         exc_info=True)


@app.route("/api/ingestions", methods=["POST"])
def api_ingestions_create():
    """创建 COS 直传任务（合同 §4/§6.1；U2 起接受全部用户上传形态）。

    大小校验先于容量排队（§2.1 两层）：非法 → 422 invalid_declared_size；
    超产品上限 → 413 upload_too_large；超池**结构性**准入上限（配置门禁
    未过）→ 503 cos_pool_below_product_limit（fail-closed，不是等待、不是
    回退）；**均不建行、不占预约、不发凭证、不进等待**。其余创建门禁
    通过而池瞬时余额不足时 202 + waiting_capacity（含排队位置）。

    格式（U2 §3.2）：注册表派生——原生单文件 native / 归档 zip /
    convert-required conversion；裸 bundle（.mrxs）与未登记格式 422 说明
    原因（无 fallback 指引）。可选 sha256_expected（64 hex）为整对象声明，
    下载校验后比对（不符=确定性失败 hash_mismatch）。

    先转换后上传阶段 1：可选 direct_class（浏览器嗅探文件头后的直传类别
    声明，词表见 upload_direct_class）。直传关闭格式（.svs）无合法
    unconverted-variant:svs-jp2k 声明 → 422 convert_in_browser +
    tools_url（conversion_moved_to_browser 同形，旧码保留在 conversion
    retry 410 路径）；kfb/kfbf（conversion）维持关闭。大小合同先行裁定，
    直传关闭闸其后（均不建行/不占预约/不发凭证）。声明随任务落库
    （0078），worker 在 open_slide 之前按 upload_direct_class 核验。

    可选 expected_account（跨账号归属核对，P1 2026-10-15）：客户端条目
    绑定的账号（/api/auth/info 的 user_id 同格式）。带且 ≠ 当前会话
    user_id → 409 account_mismatch（任何写入之前——不建行/不占预约/不进
    等待）；缺字段保持现行为；免认证部署（会话无 user_id）跳过核对。
    """
    if not can_upload():
        return jsonify(error="无上传权限"), 403
    pool, err = _cos_ingestion_ready()
    if err is not None:
        return err

    body = request.get_json(silent=True) or {}

    # P1 跨账号归属核对（cross-account 2026-10-15）：浏览器转换/直传把**条目
    # 绑定的账号**（expected_account，与 /api/auth/info 顶层 user_id 同格式、
    # 入队/上传开始时冻结）随创建请求带来。前端缓存身份不可能可靠——转换
    # 期间另一标签页退出并换账号登录后，本页仍以旧身份通过前端归属校验，
    # 而请求带的是**新账号的会话 cookie**。服务器是唯一权威：同一请求内
    # 用当前会话身份核对，不符即 409 account_mismatch。核对在任何写入之前
    # 完成：不建行、不预分配 slide_id、不占容量预约/名额、不进等待——零
    # 静默上传。缺字段（旧客户端）保持现行为；免认证部署（AUTH_ENABLED=
    # False，会话无稳定 user_id）本就无归属语义可比对（任务 owner 按配置
    # owner 解析，见 ingestion_store.asset_owner_for_job），跳过核对。
    expected_account = body.get("expected_account")
    if expected_account is not None:
        if (not isinstance(expected_account, str)
                or not expected_account.strip()):
            return jsonify(error="expected_account 需为非空字符串"), 400
        session_uid = (current_identity().get("user_id") or "")
        if session_uid and expected_account != session_uid:
            return jsonify(error="account_mismatch",
                           code="account_mismatch"), 409

    filename = body.get("filename")
    if not isinstance(filename, str) or not filename.strip():
        return jsonify(error="缺少 filename 字段"), 400
    safe = _sanitize_name(filename.strip())
    if not safe:
        return jsonify(error="非法文件名"), 400
    kind, ferr = _cos_ingestion_kind_for(safe)
    if ferr is not None:
        return ferr
    if kind == "conversion" and not SERVER_CONVERSION_CREATION:
        # 不建行、不占预约、不发凭证：引导到本机「转换并上传」
        #（阶段 1：统一错误码 convert_in_browser；旧码保留在 conversion
        # retry 410 路径，前端两个码都映射同一文案）
        return _convert_in_browser_closed(
            "该格式需在本机转换后上传，请使用切片转换工具（/tools/slides）"), 422

    try:
        declared_size = int(body.get("declared_size"))
    except (TypeError, ValueError):
        declared_size = -1
    if declared_size <= 0:
        return jsonify(
            error="declared_size 需为正整数（十进制字节）",
            code="invalid_declared_size"), 422
    product_max = int(UPLOAD_PRODUCT_MAX_BYTES)
    if declared_size > product_max:
        # 产品上限（§2.1 单一权威）：超限即拒，不建行/不占预约/不进等待。
        return jsonify(
            error="文件超过平台上限",
            code="upload_too_large",
            max_size_bytes=product_max), 413
    max_bytes = int(cos_pool_store.admission_limit_bytes(pool))
    if declared_size > max_bytes:
        # §2.1 配置门禁：池结构性可准入上限 < 产品上限——等待永远不可能
        # 满足，不是用户问题；fail-closed 503（部署预检未过的显性失败）。
        return jsonify(
            error="服务端存储配置暂不能接纳该大小（容量池准入上限低于平台"
                  "上限，待运维调整）",
            code="cos_pool_below_product_limit",
            max_size_bytes=product_max), 503

    # 先转换后上传阶段 1：直传类别声明校验 + 直传关闭闸（大小合同**之后**
    # 裁定——非法大小/超限先给各自的稳定码；本闸不建行/不占预约/不发凭证）
    direct_class, dc_err = _validate_direct_class(
        safe, kind, body.get("direct_class"))
    if dc_err is not None:
        return dc_err

    sha_expected = body.get("sha256_expected")
    if sha_expected is not None and (
            not isinstance(sha_expected, str)
            or not _SHA256_RE.match(sha_expected)):
        return jsonify(error="sha256_expected 需为 64 位十六进制字符串"), 400

    idem = body.get("idempotency_key")
    if idem is not None and (not isinstance(idem, str) or not idem.strip()
                             or len(idem) > 128):
        return jsonify(error="idempotency_key 需为非空字符串（≤128）"), 400
    # P4-app（合同 §5.1/C2）：名称冲突预检（(UPLOAD_DIR/safe).exists() ∨
    # _upload_name_conflict）拆除——创建即预分配 slide_id，objects/<sid>
    # 唯一天然无冲突；同名并发各发各的 ID。

    ident = current_identity()
    try:
        job, _created = ingestion_store.create_waiting_job(
            owner_user_id=(ident.get("user_id") or ""),
            owner_role=(ident.get("role") or ""),
            filename=filename.strip(), safe_name=safe,
            format_ext=(safe.rsplit(".", 1)[-1].lower()
                        if "." in safe else ""),
            declared_size=declared_size,
            idempotency_key=(idem.strip() if idem else None),
            policy_version="v1-manual",
            route_reason=body.get("route_reason") or "manual_cos",
            kind=kind,
            sha256_expected=(sha_expected.lower() if sha_expected else None),
            direct_class=direct_class)
    except ingestion_store.IngestionStateError as e:
        # 空 owner（本地态未配置 owner，不允许自动认领）是服务端配置故障 →
        # 500；仅容量等待上限（cos_waiting_limit）落 409（P4-app C2 收口：
        # 不再混入 name_unavailable 族——预检已拆，创建即预分配 slide_id）。
        if "owner" in str(e):
            app.logger.error("COS 任务创建失败（owner 解析失败）：%s", e)
            return jsonify(error=str(e), code="ingestion_owner_missing"), 500
        return jsonify(error=str(e), code="cos_waiting_limit"), 409

    # 创建后立即尝试准入（容量不足转等待；池对账暂停/水位同样只等待）
    try:
        upload_guard.check_disk_watermark(UPLOAD_DIR)
        watermark_ok = True
    except upload_guard.DiskWatermarkExceeded:
        watermark_ok = False
    out = ingestion_store.try_admit_job(job["job_id"],
                                        disk_watermark_ok=watermark_ok)
    job = out["job"] or job
    resp = _ingestion_state_body(job)
    if out["outcome"] == "waiting" and job["state"] == ingestion_store.WAITING:
        resp["code"] = "cos_waiting_capacity"
        resp["queue_position"] = ingestion_store.queue_position(job["job_id"])
        resp["status_url"] = "/api/ingestions/%s" % job["job_id"]
    elif out["outcome"] == "terminal":
        resp["code"] = out["reason"] or job.get("fail_code")
    return jsonify(resp), 202


@app.route("/api/ingestions/<job_id>", methods=["GET"])
def api_ingestion_status(job_id):
    """阶段/进度快照（不触发任何远程读取；进度是服务端权威持久值）。

    owner 本人的轮询同时刷新 client_seen_at（0084 liveness；等待期 5s
    轮询、上传期心跳共用的在场证据）。"""
    job, err = _ingestion_fetch(job_id)
    if err is not None:
        return err
    _touch_ingestion_client_seen(job)
    position = (ingestion_store.queue_position(job_id)
                if job["state"] == ingestion_store.WAITING else None)
    return jsonify(_ingestion_state_body(job, queue_position=position))


@app.route("/api/ingestions/<job_id>/upload-complete", methods=["POST"])
def api_ingestion_upload_complete(job_id):
    """幂等记录「浏览器侧完成」（§4）：worker 随后核验远端对象。

    owner 触点先行刷新 client_seen_at（0084 liveness；终态冲突时同样算
    在场证据）。"""
    job, err = _ingestion_fetch(job_id)
    if err is not None:
        return err
    _touch_ingestion_client_seen(job)
    try:
        job = ingestion_store.request_upload_complete(job_id)
    except ingestion_store.IngestionStateError as e:
        return jsonify(error=str(e), code="ingestion_state_conflict"), 409
    return jsonify(_ingestion_state_body(job)), 202


@app.route("/api/ingestions/<job_id>/cancel", methods=["POST"])
def api_ingestion_cancel(job_id):
    """幂等取消：worker 停下载、Abort/清理、释放预约；已入库走切片删除。"""
    job, err = _ingestion_fetch(job_id)
    if err is not None:
        return err
    try:
        job = ingestion_store.cancel_job(job_id)
    except ingestion_store.CommitInProgress as e:
        # 提交已开始（intent 持久化）：取消被拒，落库后走切片删除合同
        # （review 740e823 P1-3 取消/提交互斥）。
        return jsonify(error=str(e), code="commit_in_progress"), 409
    except ingestion_store.IngestionStateError as e:
        return jsonify(error=str(e), code="already_committed"), 409
    return jsonify(_ingestion_state_body(job)), 202


@app.route("/api/ingestions/<job_id>/parts/sign", methods=["POST"])
def api_ingestion_parts_sign(job_id):
    """A 方案唯一授权接口：批量签发绑定 Content-Length 的 UploadPart URL。

    纯本地签名（无 COS 网络调用）；只签冻结计划内分块；短 TTL 可续签同一
    uploadId。暂停/取消/超时/超配额后停发（状态机闸）。响应 no-store。
    """
    pool, err = _cos_ingestion_ready()
    if err is not None:
        return err
    job, err = _ingestion_fetch(job_id)
    if err is not None:
        return err
    # owner 触点（0084 liveness）：分块签名是上传方浏览器在场的最强证据。
    _touch_ingestion_client_seen(job)
    if job["state"] != ingestion_store.UPLOADING:
        return jsonify(
            error="任务当前状态 %s 不接受分块签名" % job["state"],
            code="ingestion_state_conflict"), 409
    # 0072 生命周期（plan §4.3）：不给失去容量责任的任务签发新授权——
    # quota 适用身份必须持有绑定有效（reserved）的本地预约；缺失/已结算
    # 即不变量异常，fail-closed 拒签（恢复扫描/核账处置）。
    if job["owner_role"] == "user" and (job["owner_user_id"] or "").strip():
        rid = (job.get("local_reservation_id") or "").strip()
        res = upload_guard.get_reservation(rid) if rid else None
        if not rid or res is None or \
                not upload_guard.reservation_holder_matches(
                    res, "ingestion_job", job_id) or \
                not upload_guard.reservation_holds_capacity(res):
            app.logger.error(
                "ingestion job %s 本地预约绑定无效（rid=%r state=%r）——拒签",
                job_id, rid or None, (res or {}).get("state"))
            return jsonify(
                error="任务本地容量责任异常，暂停签发（待恢复/清理编排处置）",
                code="local_reservation_invalid"), 409
    if pool is not None and cos_pool_store.admission_paused(pool):
        return jsonify(error="容量对账暂停，暂停签发",
                       code="cos_capacity_reconcile_required"), 503

    body = request.get_json(silent=True) or {}
    nums = body.get("part_numbers")
    if (not isinstance(nums, list) or not nums
            or not all(isinstance(n, int) and not isinstance(n, bool)
                       for n in nums)):
        return jsonify(error="part_numbers 需为非空整数数组"), 400
    if len(set(nums)) != len(nums):
        return jsonify(error="part_numbers 不得重复"), 400
    plan = {int(p["part_number"]): int(p["length"])
            for p in (job.get("part_plan_json") or [])}
    if not plan or not job.get("upload_id") or not job.get("object_key"):
        return jsonify(error="分块计划未就绪，请稍后重试",
                       code="plan_not_ready"), 409
    if any(n not in plan for n in nums):
        return jsonify(error="part_numbers 含计划外编号"), 400
    if len(nums) > cos_config.COS_SIGN_BATCH_MAX_PARTS:
        return jsonify(
            error="单批最多 %d 个分块"
                  % cos_config.COS_SIGN_BATCH_MAX_PARTS), 400
    if not ingestion_store.record_sign_batch(job_id, nums):
        return jsonify(error="签名请求过于频繁，请稍后重试",
                       code="cos_sign_rate_limited"), 429
    try:
        urls = [cos_client.presign_upload_part(
                    job["object_key"], job["upload_id"], n, plan[n])
                for n in sorted(nums)]
    except cos_client.CosConfigMissing:
        return jsonify(error="cos 直传暂不可用", code="cos_unavailable"), 503
    except cos_client.CosClientError as e:
        app.logger.warning("presign part failed: %s", e)
        return jsonify(error="签名失败", code="presign_failed"), 500
    resp = jsonify(job_id=job_id, upload_id=job["upload_id"],
                   transport="presign_parts", urls=urls)
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/api/ingestions/<job_id>/resume", methods=["POST"])
def api_ingestion_resume(job_id):
    """恢复上传会话（§4 resume）：completing 未收口时回 uploading 续传。

    首版语义：浏览器按自身未确认分块重取签名重传（同编号 UploadPart 覆盖
    旧块，绑定长度保证不越界）；worker Complete 前仍以可信 ListParts 核对
    为准，浏览器上报仅是提示。
    """
    job, err = _ingestion_fetch(job_id)
    if err is not None:
        return err
    try:
        job = ingestion_store.request_resume(job_id)
    except ingestion_store.IngestionStateError as e:
        return jsonify(error=str(e), code="ingestion_state_conflict"), 409
    return jsonify(_ingestion_state_body(job)), 202


@app.route("/api/conversions", methods=["GET"])
def api_conversion_list():
    """当前身份的转换任务列表（open/recent，分页）。本人隔离。"""
    import conversion_http
    if not can_upload():
        return jsonify(error="无上传权限"), 403
    return _jsonify_pair(conversion_http.handle_list(
        current_identity(), request.args))


@app.route("/api/conversions/<job_id>", methods=["GET"])
def api_conversion_get(job_id):
    """查询转换任务（仅任务归属者；他人统一 404）。"""
    import conversion_http
    if not can_upload():
        return jsonify(error="无上传权限"), 403
    payload, status = conversion_http.handle_get(current_identity(), job_id)
    # P4-app（合同 §3.6）：轮询打开目标的 slide_id 直接来自任务视图
    #（public_view 含任务绑定 slide_id——create_job 即分配，ready 前后都在；
    # 不再按 canonical 名 resolve，id_bundle 产物无 legacy_filename）。
    return _jsonify_pair((payload, status))


@app.route("/api/conversions/<job_id>/retry", methods=["POST"])
def api_conversion_retry(job_id):
    """重试 failed/cancelled 转换任务（同 id 重新入队，不重复扣配额）。"""
    import conversion_http
    import conversion_worker
    if not can_upload():
        return jsonify(error="无上传权限"), 403
    if not SERVER_CONVERSION_CREATION:
        return _server_conversion_closed(
            "后台转换已停用，请在本机重新转换并上传"), 410
    ident = current_identity()
    job = conversion_store.get_job(job_id)
    # 源可用性按任务源解析判定（P4-app：任务 staging 副本 / 平铺 alias
    # 过渡——不再只看 UPLOAD_DIR/<source_name>）。
    source_available = bool(
        job and conversion_worker.resolve_source(job, UPLOAD_DIR))
    return _jsonify_pair(conversion_http.handle_retry(
        ident, job_id, source_available=source_available))


@app.route("/api/slide/<name>", methods=["DELETE"])
def api_slide_delete(name):
    """关闭句柄并删除切片（legacy alias → 统一删除编排，P5 合同 §1.8）。

    .mrxs 切片带有同名伴侣数据目录（去扩展名后的目录），一并删除。
    Stage 3a-2a：owner 任意；user 仅自己的切片。
    PT-4：切片在 Demo 目录内时联动撤销（capability 失效 + 未完成 run 终止 +
    对应预算预占释放，docs §9.3）。
    升级 B R7：删除文件前清理该切片的全部 view 授权（按 legacy 名 + 旧
    slide_id 残留，单事务）——同名再上传后旧授权不自动生效（失效语义），
    需要系统管理重新添加；删除后无孤儿授权行残留。
    P5（合同 §1.8 删除端点归一）：本端点与 DELETE /api/slides/<slide_id>
    共用同一编排——legacy alias 解析（resolve_legacy_alias，tombstone 冻结
    别名）→ request_delete CAS + slide_delete_jobs 落库（同事务）→ 同步尝试
    执行一次（用户感知不变）→ daemon 兜底重试。mark_deleted_compat 直写
    已随之拆除。**R-12：legacy 资产删除维持不回退 used_bytes（0013 口径；
    P6 迁移演练时统一对账）**；tombstone 保留 legacy_filename（授权映射
    随之冻结，旧别名不重绑新 ID）。
    无 slides 行的平铺文件是 admin inventory 的 orphan_files 人口（P1-B2
    只报告不认领）——统一编排需要资产行（状态机+任务+账本），按名裸
    unlink 退役（不按名猜 owner；物理处置走 P6 迁移工具链）→ 404。
    """
    if not can_delete_slide(name):
        return _denied()
    # 只做路径形态校验（不要求文件存在——tombstone 行的幂等重放 DELETE
    # 也走统一编排返回 200；文件缺失由资产行状态机裁决）。
    safe = _sanitize_name(name)
    if not safe or safe != name:
        return jsonify(error="非法文件名"), 400
    desc = None
    try:
        desc = slide_store.resolve_legacy_alias(safe)
    except Exception:
        app.logger.warning("legacy alias 解析失败（fail-closed）：%s", safe,
                           exc_info=True)
    if desc is None:
        return jsonify(error="切片不存在", code="slide_not_found"), 404
    return _slide_delete_unified(
        desc, requested_by=current_identity().get("user_id"),
        legacy_response=True)


# --------------------------------------------------------------------------- #
# P5 统一删除编排（docs/slide-id-refactor-p5-contract-20260925.md §1-2）：
#
#   request_delete（ready→deleting CAS + slide_delete_jobs 落库，同事务）
#     → 执行器（端点同步尝试一次 + daemon 兜底；lease + 退避）：
#         阶段 2 授权/关系联动（fail-closed，可重入）
#         阶段 3 物理清理（两种布局；幂等；失败停留 deleting 重试）
#         阶段 4 结算（advisory 锁 + deleting→deleted CAS +（仅 id_bundle）
#                refund_used_bytes_locked 同事务；幂等键=CAS 本身）
#
# 重复 DELETE：deleted → 幂等 200；deleting → 触发执行器（任务 failed 复位
# pending）。重复执行/worker 重启不得重复减账（CAS 只成功一次）、不得重复
# 清理别人（remove_bundle 只认 slide_id 独占目录；legacy 只动冻结别名文件）。
# --------------------------------------------------------------------------- #
#: 删除执行器 daemon 的轮询间隔（秒；<=0 关闭——测试隔离用）
_SLIDE_DELETE_WORKER_ENV = "SLIDE_DELETE_WORKER_INTERVAL_SECONDS"


def _env_float(name, default):
    try:
        return float(os.environ.get(name) or default)
    except (TypeError, ValueError):
        return float(default)


#: 任务租约时长（claim 后超时视为 worker 崩溃，可重领）
_SLIDE_DELETE_LEASE_SECONDS = _env_float("SLIDE_DELETE_LEASE_SECONDS", 300)
#: 失败退避基数（base * 2^attempts，封顶）
_SLIDE_DELETE_BACKOFF_BASE_SECONDS = _env_float(
    "SLIDE_DELETE_BACKOFF_BASE_SECONDS", 2)
_SLIDE_DELETE_BACKOFF_CAP_SECONDS = 3600.0


def _slide_delete_unified(desc, requested_by, *, legacy_response=False):
    """统一删除编排（两个 DELETE 端点共用；P5 合同 §1.1/§1.2/§1.8）。

    阶段 1（短事务）：advisory 锁（第一把锁）→ slides 行 FOR UPDATE →
    分流：deleted 幂等返回 / deleting 复位 failed 任务后重触发执行 /
    可删态 CAS→deleting 且 slide_delete_jobs 落库（同事务）。
    随后同步尝试执行一次（用户感知与 P3 内联版一致）；执行异常返回 503
    （delete_retryable），daemon 按 lease+退避兜底。

    可删态口径：id_bundle 恒 ready（状态机严格）；legacy 布局资产放行
    ready/legacy/failed（迁移期清理语义——旧行 any-state 可删的能力保留，
    failed 行的文件多已缺失，结算幂等不受影响）。staging 恒 409。
    """
    sid = desc.slide_id
    legacy_layout = desc.storage_layout != slide_store.StorageLayout.ID_BUNDLE
    allowed = ((slide_store.SlideState.READY, slide_store.SlideState.LEGACY,
                slide_store.SlideState.FAILED) if legacy_layout
               else (slide_store.SlideState.READY,))
    state = None
    import psycopg.rows
    conn = pg_store.connect()
    conn.row_factory = psycopg.rows.dict_row
    try:
        with pg_store.transaction(conn):
            with conn.cursor() as cur:
                slide_store.acquire_slide_lock(cur, sid)  # 第一把锁
                cur.execute("SELECT asset_state FROM slides "
                            "WHERE slide_id=%s FOR UPDATE", (sid,))
                row = cur.fetchone()
                if row is None:
                    return jsonify(error="切片不存在",
                                   code="slide_not_found"), 404
                state = row["asset_state"]
                if state == slide_store.SlideState.DELETED:
                    pass  # 幂等：已完成（不重复减账；事务后统一 200）
                elif state == slide_store.SlideState.DELETING:
                    # 重放 DELETE：仅复位 failed 任务（活租约/终态不动）
                    slide_store.enqueue_delete_job(sid, requested_by,
                                                   conn=conn)
                elif state in allowed:
                    if not slide_store.request_delete(
                            sid, expected_state=state,
                            requested_by=requested_by, conn=conn):
                        return jsonify(
                            error="切片状态 %s 不可删除" % state,
                            code="slide_state_conflict"), 409
                else:
                    return jsonify(error="切片状态 %s 不可删除" % state,
                                   code="slide_state_conflict"), 409
    finally:
        conn.close()
    if state == slide_store.SlideState.DELETED:
        # 幂等 200（结算已完成，不重复减账）
        if legacy_response:
            return jsonify(ok=True)
        return jsonify(ok=True, slide_id=sid, state="deleted")
    try:
        _slide_delete_execute(sid)
    except Exception as exc:
        app.logger.exception("删除执行失败（保持 deleting，daemon 兜底重试）："
                             "%s", sid)
        # 同步尝试的失败即一次尝试：记入任务（last_error 证据 + 退避基线），
        # daemon 领取重试；对 daemon 已领取（cleaning）的任务无破坏（执行
        # 幂等，收口状态由最后完成方收敛）。
        try:
            slide_store.finish_delete_job_by_slide(
                sid, slide_store.DELETE_JOB_FAILED, error=str(exc))
        except Exception:
            app.logger.warning("删除任务 failed 收口写入失败（daemon 兜底）"
                               "：%s", sid, exc_info=True)
        if legacy_response:
            return jsonify(error="删除清理失败，将重试",
                           code="delete_retryable"), 503
        return jsonify(error="删除清理失败，将重试",
                       code="delete_retryable", slide_id=sid,
                       state="deleting"), 503
    # 同步执行成功：把本请求落库的任务直接收口 done（daemon 不再重复领取）
    try:
        slide_store.finish_delete_job_by_slide(sid,
                                               slide_store.DELETE_JOB_DONE)
    except Exception:
        app.logger.warning("删除任务 done 收口写入失败（daemon 幂等兜底）"
                           "：%s", sid, exc_info=True)
    if legacy_response:
        return jsonify(ok=True)
    return jsonify(ok=True, slide_id=sid, state="deleted")


def _slide_delete_invalidations(desc):
    """阶段 2：授权/关系联动清理（物理删除前，fail-closed；可重入——
    重复执行/daemon 重试无副作用）。

    覆盖面（P5 合同 §1.6 七类入口 + HistoPilot 会话）：
      1. slide_view_grants（按 slide_id 权威 + legacy 名历史残留，单事务）；
      2. share_slides 成员行（R-04：旧 token 不因同名新上传恢复访问）；
      3. Demo 撤销（catalog 条目 + capability 失效 + 未完成 run 终止 +
         预算预占释放）；
      4. run grants（按 slide_id + 名兜底；HP 侧旧会话/回放由 grant 失效
         与读取门禁冻结，不绑定新同名内容）；
      5. conversion 任务作废 + 源副本/平铺 sidecar（.manifest.json/
         .associated）清理（legacy 名联动语义保留）；
      6. baidu_import_items 引用行失效（P4 偏差 #3 复审：删资产本体，
         全部引用行失效——在途→failed、ready→标注）；
      7. 缓存（句柄池/tile/render 统计按 slide_id 失效）；
      8. legacy 布局：对运行中 sidecar run 发起既有取消（R6d 同款；
         id_bundle 无 legacy 名，sidecar /sessions 按名查询不适用——
         run grant 撤销 + TTL 兜底，P3 裁决口径）。
    研究维度不动（伪名/研究删除按 user 维度既有编排）。
    """
    sid = desc.slide_id
    legacy_name = desc.legacy_filename  # id_bundle 恒 None（仅审计/兜底用）
    if legacy_name:
        try:
            share_store.revoke_slide_view_grants_for_slide(
                legacy_name, slide_id=sid)
        except Exception:
            app.logger.warning("切片删除的 view 授权清理失败：%s", legacy_name,
                               exc_info=True)
    try:
        slide_store.revoke_view_grants_by_slide_id(sid)
    except Exception:
        app.logger.warning("切片删除的 view 授权清理（按 ID）失败：%s", sid,
                           exc_info=True)
    try:
        slide_store.remove_share_membership(sid)
    except Exception:
        app.logger.warning("切片删除的 share 成员行清理失败：%s", sid,
                           exc_info=True)
    try:
        _revoke_demo_slide(sid)
    except Exception:
        app.logger.warning("切片删除的 Demo 撤销联动失败：%s", sid,
                           exc_info=True)
    _revoke_run_grants_for_slide_id(sid, name=legacy_name)
    try:
        _cleanup_conversion_sidecars(sid, canonical_name=legacy_name)
    except Exception:
        app.logger.warning("切片删除的转换 sidecar 清理失败：%s", sid,
                           exc_info=True)
    try:
        import baidu_import_store
        baidu_import_store.invalidate_items_for_slide(sid)
    except Exception:
        app.logger.warning("切片删除的 baidu 引用行失效失败：%s", sid,
                           exc_info=True)
    if desc.storage_layout == slide_store.StorageLayout.ID_BUNDLE:
        _close_slide(_slide_cache_key_for(sid, desc.original_filename or ""),
                     slide_id=sid)
    else:
        _close_slide(legacy_name, slide_id=sid)
        try:
            if legacy_name and desc.owner_user_id:
                _cancel_sidecar_runs_for_owners(
                    legacy_name, [desc.owner_user_id],
                    reason="slide_deleted")
        except Exception:
            app.logger.warning("切片删除的运行中 run 取消联动失败：%s",
                               legacy_name, exc_info=True)


def _slide_delete_physical(desc):
    """阶段 3：两种布局的物理清理（P5 合同 §1.3；幂等，异常向上抛）。"""
    sid = desc.slide_id
    if desc.storage_layout == slide_store.StorageLayout.ID_BUNDLE:
        # 仅该 ID 的独占目录；绝不按显示名扫描删除（no-clobber 的对偶：
        # no-residue）
        return slide_storage.remove_bundle(sid, root=UPLOAD_DIR)
    name = desc.legacy_filename or ""
    if not name:
        return False
    removed = False
    try:
        (UPLOAD_DIR / name).unlink()
        removed = True
    except FileNotFoundError:
        pass
    # MRXS：删除伴侣数据目录（先做安全检查确保在 UPLOAD_DIR 内）；
    # <name>.manifest.json / <name>.associated 平铺 sidecar 由
    # _cleanup_conversion_sidecars(canonical_name=...) 联动清理（同语义）。
    if name.lower().endswith(".mrxs"):
        stem = name[: -len(".mrxs")]
        companion = UPLOAD_DIR / stem
        try:
            companion.resolve().relative_to(UPLOAD_DIR.resolve())
        except ValueError:
            pass
        else:
            if companion.is_dir():
                shutil.rmtree(companion, ignore_errors=True)
                removed = True
    return removed


def _slide_delete_settle(sid, layout):
    """阶段 4：结算事务——advisory 锁 + deleting→deleted CAS + 幂等减账。

    幂等键 = 本 CAS（只成功一次→减账只发生一次；重复执行/双 worker 安全）。
    R-12：**只对 id_bundle 资产退款**——legacy 布局资产不回退 used_bytes
    （0013 过渡口径，P6 迁移演练后统一对账）；tombstone 保留
    legacy_filename（授权映射冻结）。返回 (settled, refunded_bytes)。
    """
    settled = False
    refunded = 0
    import psycopg.rows
    conn = pg_store.connect()
    conn.row_factory = psycopg.rows.dict_row
    try:
        with pg_store.transaction(conn):
            with conn.cursor() as cur:
                slide_store.acquire_slide_lock(cur, sid)  # 第一把锁
                cur.execute(
                    "UPDATE slides SET asset_state=%s, deleted_at=now(), "
                    "updated_at=now() WHERE slide_id=%s AND asset_state=%s",
                    (slide_store.SlideState.DELETED, sid,
                     slide_store.SlideState.DELETING))
                if cur.rowcount == 1:
                    settled = True
                    # 结算在该 CAS 事务内：used_bytes 幂等减 accounted_bytes
                    #（GREATEST 兜底防负；仅 id_bundle）。
                    cur.execute(
                        "SELECT owner_user_id, accounted_bytes FROM slides "
                        "WHERE slide_id=%s", (sid,))
                    srow = cur.fetchone()
                    owner = (srow["owner_user_id"] or "") if srow else ""
                    bytes_n = int(srow["accounted_bytes"] or 0) if srow else 0
                    if (layout == slide_store.StorageLayout.ID_BUNDLE
                            and owner and bytes_n > 0):
                        upload_guard.refund_used_bytes_locked(cur, owner,
                                                              bytes_n)
                        refunded = bytes_n
    finally:
        conn.close()
    return settled, refunded


def _slide_delete_execute(sid):
    """执行器主体（端点同步尝试与 daemon 共用；可重入/重放安全）。

    幂等：已 deleted 直接返回（结算幂等键=CAS，不重复减账）；物理清理
    幂等（remove_bundle 缺目录 False / legacy unlink FileNotFound pass）。
    非 deleting 态（含行缺失/被并发结算）不执行物理清理——已 deleted 返回
    摘要，其余抛错（任务记 failed，人工可见 last_error）。返回执行摘要。
    """
    desc = slide_store.resolve_slide_id(sid)
    if desc is None:
        raise ValueError("slides 行缺失（拒绝盲删）：%s" % sid)
    if desc.asset_state == slide_store.SlideState.DELETED:
        return {"already_deleted": True, "bundle_removed": False,
                "refunded_bytes": 0, "layout": desc.storage_layout}
    if desc.asset_state != slide_store.SlideState.DELETING:
        raise RuntimeError("资产不在 deleting 态（%s），拒绝物理清理"
                           % desc.asset_state)
    _slide_delete_invalidations(desc)
    removed = _slide_delete_physical(desc)
    settled, refunded = _slide_delete_settle(sid, desc.storage_layout)
    if settled:
        # 审计 best-effort：daemon 无请求上下文（_audit 的 actor_identity
        # 依赖 session）——降级为无 actor 审计行，绝不因审计失败中断结算
        #（与 _audit_grant_event 同款双跳）。
        try:
            _audit("slide.delete", target_type="slide", target_id=sid,
                   slide=desc.legacy_filename, slide_id=sid,
                   detail={"slide_id": sid, "layout": desc.storage_layout,
                           "bundle_removed": removed,
                           "refunded_bytes": refunded,
                           "view_grants_revoked": True})
        except Exception:
            try:
                share_store.record_audit(
                    action="slide.delete", actor_user_id=None,
                    actor_role=None, target_type="slide", target_id=sid,
                    slide=desc.legacy_filename,
                    detail={"slide_id": sid, "layout": desc.storage_layout,
                            "bundle_removed": removed,
                            "refunded_bytes": refunded,
                            "view_grants_revoked": True,
                            "trigger": "delete_executor"})
            except Exception:
                app.logger.info("slide.delete 审计失败（executor）：%s", sid)
    return {"already_deleted": False, "bundle_removed": removed,
            "refunded_bytes": refunded, "layout": desc.storage_layout,
            "settled": settled}


def run_slide_delete_worker_once(*, max_jobs=1, worker_id=None):
    """删除执行器单轮：领取到期任务并执行（测试可确定性驱动——直调本
    函数，不起 daemon 线程）。

    每任务：claim（lease + 退避谓词，FOR UPDATE SKIP LOCKED 防双领）→
    执行（幂等清理+结算）→ done；异常 → failed（last_error，attempts 已
    在领取时 +1，指数退避后由下一轮重领）。返回本轮执行的任务数。
    """
    wid = worker_id or "pid-%d-t%d" % (os.getpid(), threading.get_ident())
    done = 0
    for _ in range(max(1, int(max_jobs))):
        try:
            job = slide_store.claim_due_delete_job(
                wid,
                lease_seconds=_SLIDE_DELETE_LEASE_SECONDS,
                backoff_base_seconds=_SLIDE_DELETE_BACKOFF_BASE_SECONDS,
                backoff_cap_seconds=_SLIDE_DELETE_BACKOFF_CAP_SECONDS)
        except Exception:
            app.logger.warning("删除任务领取失败（下一轮重试）", exc_info=True)
            return done
        if job is None:
            return done
        done += 1
        try:
            _slide_delete_execute(job["slide_id"])
        except Exception as exc:
            app.logger.warning("删除任务执行失败（退避重试）：%s",
                               job["slide_id"], exc_info=True)
            try:
                slide_store.finish_delete_job(
                    job["job_id"], slide_store.DELETE_JOB_FAILED,
                    error=str(exc))
            except Exception:
                app.logger.warning("删除任务 failed 收口写入失败：%s",
                                   job["job_id"], exc_info=True)
        else:
            try:
                slide_store.finish_delete_job(job["job_id"],
                                              slide_store.DELETE_JOB_DONE)
            except Exception:
                app.logger.warning("删除任务 done 收口写入失败（下轮幂等）："
                                   "%s", job["job_id"], exc_info=True)
    return done


def _revoke_run_grants_for_slide_id(slide_id, *, name=None,
                                    created_by_user_id=None,
                                    trigger="slide_deleted"):
    """run grants 撤销联动（P3 合同 §5 by-ID 删除用；P5 起两个删除端点
    统一经 _slide_delete_invalidations 调用）：按 slide_id（权威）＋历史
    NULL-ID 同名行兜底（P2 list_run_grants 双口径——撤销钩子必须覆盖全部
    行）。

    2026-10-08 缺陷修复：``created_by_user_id`` 给出时只撤销**该创建者**
    名下的 grant（管理员结束临时查看只撤自己派生的运行授权——上传者及
    其他独立授权用户的 grant 保持有效）；切片删除路径不传该参数 → 仍撤销
    全部（语义不变）。``trigger`` 仅影响审计事件标注。"""
    try:
        if slide_id:
            grants = share_store.list_run_grants(slide_id=slide_id,
                                                 include_revoked=True)
        elif name:
            grants = share_store.list_run_grants(slide=name,
                                                 include_revoked=True)
        else:
            return
    except Exception:
        app.logger.warning("切片删除的 run grant 清理列举失败：%s",
                           slide_id or name, exc_info=True)
        return
    for g in grants:
        if g.get("revoked"):
            continue
        if (created_by_user_id is not None
                and (g.get("created_by_user_id") or "")
                != created_by_user_id):
            continue
        try:
            share_store.revoke_run_grant(g["grant_id"])
            _audit_grant_event("run_grant.revoke", g["grant_id"],
                               g.get("slide"), {"trigger": trigger})
        except Exception:
            app.logger.warning("run grant 撤销失败：%s", g.get("grant_id"),
                               exc_info=True)


@app.route("/api/slides/<slide_id>", methods=["DELETE"])
def api_slide_delete_by_id(slide_id):
    """切片删除（权威端点；P5 合同 §1.8——与 legacy 名端点共用统一编排）。

    编排（锁序/语义见 slide_store 模块 docstring 与 _slide_delete_unified）：
    advisory 锁 → request_delete（ready→deleting，**立即拒读**）+
    slide_delete_jobs 落库（同事务）→ 同步尝试执行一次（授权联动清理 →
    物理清理 → 结算；用户感知不变）→ daemon 兜底重试（lease+退避）。

    幂等（合同 §2）：重复 DELETE / worker 重试不重复减——减账与
    deleting→deleted 的 CAS **同一事务**，CAS 只成功一次即减账只发生一次；
    已 deleted → 200 幂等返回；deleting（上次清理中断）→ 重触发执行。
    R-12：**只对 id_bundle 资产减账**；legacy 布局资产（按 ID 解析到）经
    同一编排但不退款（0013 口径），tombstone 保留 legacy_filename。
    同名重传恒新 ID（allocate_slide 不查原名）——旧分享/授权/标注/AI
    run grant/Demo 不指向新资产（授权面已随本删除清理）。
    """
    ident = current_identity()
    desc = None
    try:
        desc = slide_store.resolve_slide_id(slide_id)
    except Exception:
        app.logger.warning("slide_id 解析失败（fail-closed）：%s", slide_id,
                           exc_info=True)
    if desc is None:
        return jsonify(error="切片不存在", code="slide_not_found"), 404
    # 权限：与 can_delete_slide 同口径（owner 任意；user 仅自己的切片）——
    # id_bundle 行按资产行 owner 判定（无按名反查）。
    if ident.get("role") != user_store.ROLE_OWNER:
        if (desc.owner_user_id or "") != (ident.get("user_id") or ""):
            return _denied()
    return _slide_delete_unified(
        desc, requested_by=ident.get("user_id"))


@app.route("/api/slide/<name>/info")
def api_slide_info(name):
    """单个切片元数据。Stage 3a-2a：can_view_slide，无权 403。

    P1-B2：入参按 legacy alias 解析（resolve_legacy_alias）→ authorize_read
    统一门禁（asset_state='ready' 唯一可见性开关）→ descriptor 路径读取；
    无行/无权保持 403（不泄露存在性差异），行存在且授权后文件缺失保持 404。
    响应追加 slide_id/original_filename/display_name/format_ext（旧字段不变）。

    Batch 3（§6.1）：additive 返回 image_mode / channels /
    default_render_context / default_render_token / warnings / plane /
    deepzoom / server_capability（flag 关只暴露探测字段）。所有新字段
    optional，旧客户端忽略即可。
    """
    desc = _authorize_legacy_read(name)
    if desc is None:
        return _denied()
    path = _desc_read_path(desc)
    info = _slide_info_dict_desc(desc, path)
    if info.get("error"):
        return jsonify(info)
    try:
        info.update(_slide_render_info_fields(desc))
    except (slide_render.RenderRequestError, slide_io.SlideRenderError) as e:
        return _render_error_response(e)
    except slide_cache.SlideFileChanged:
        return jsonify(error="slide_file_changed",
                       code="slide_file_changed"), 503
    return jsonify(info)


@app.route("/api/slide/<name>/render-context", methods=["POST"])
def api_slide_render_context(name):
    """渲染上下文规范化（§6.2，不落库）：can_view_slide 先行鉴权。

    请求只提交用户选择 active_channels[] / plane；服务端验证 + 绑定当前
    asset revision，返回 canonical context + fingerprint + render_token。
    P1-B2：legacy alias 解析 + authorize_read 门禁（语义同 info 端点）。
    """
    desc = _authorize_legacy_read(name)
    if desc is None:
        return _denied()
    _desc_read_path(desc)
    body = request.get_json(silent=True)
    return _render_context_post_response(desc, body)


@app.route("/api/slides/<slide_id>/render-context", methods=["POST"])
def api_slide_render_context_by_id(slide_id):
    """render-context 的 ID 原生路由（P2 前端缺口④，合同 §4）。

    语义与按名端点一致（共用 _render_context_post_response）；render token
    本就按 slide_id 绑定（R-15 已收口）。
    """
    desc, err = _authorize_id_read(slide_id)
    if err is not None:
        return err
    body = request.get_json(silent=True)
    return _render_context_post_response(desc, body)


def _slide_dzi_response(desc, files_url):
    """DZI XML 共用实现（P2，合同 §4）：Url 指向调用方通道的 tiles 前缀。"""
    _desc_read_path(desc)
    entry = _get_slide(desc)
    with slide_cache.borrow_pair(entry) as pair:
        dz = pair["dz"]
        # DZI Size 取最高层（level_count-1）尺寸
        width, height = dz.level_dimensions[-1]

    xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<Image xmlns="http://schemas.microsoft.com/deepzoom/2008" '
        f'Url="{files_url}" Format="jpeg" '
        f'Overlap="{DZ_OVERLAP}" TileSize="{DZ_TILE_SIZE}">'
        f'<Size Width="{width}" Height="{height}"/>'
        "</Image>"
    )
    resp = Response(xml, mimetype="application/xml")
    # DZI 元数据短期可变（重传/换切片后 URL 不变但尺寸会变），用短缓存
    resp.headers["Cache-Control"] = "max-age=60"
    return resp


@app.route("/api/slide/<name>.dzi")
def api_slide_dzi(name):
    """手工生成 Deep Zoom XML。Stage 3a-2a：can_view_slide，无权 403。

    P1-B2：legacy alias 解析 + authorize_read 门禁 + descriptor 路径。
    """
    desc = _authorize_legacy_read(name)
    if desc is None:
        return _denied()
    safe = desc.legacy_filename or _sanitize_name(name)
    return _slide_dzi_response(desc, "/api/slide/%s_files/" % safe)


@app.route("/api/slides/<slide_id>/dzi")
def api_slide_dzi_by_id(slide_id):
    """ID 原生 DZI（P2，合同 §4）：瓦片 URL 指向 /api/slides/<id>/tiles/。"""
    desc, err = _authorize_id_read(slide_id)
    if err is not None:
        return err
